window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-02"]={"block":"med:med-clinica-medica-med-clm-02","label":"MED · MED CLM 02","count":424,"questions":[{"id":"med-clinica-medica-med-clm-02-345453","number":"345453","sourceNumber":"345453","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Quando a decisão de tratar com antibiótico a diarreia aguda no adulto for tomada,\ndeve-se dar preferência por ou\n. Assinale a alternativa que\npreencha correta e respectivamente as lacunas:","options":{"A":"Azitromicina / uma fluoroquinolona.","B":"Uma fluoroquinolona / sulfametoxazol-trimetropim.","C":"Azitromicina / metronidazol.","D":"Uma fluoroquinolona / metronidazol."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-345502","number":"345502","sourceNumber":"345502","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Criança com 2 anos de vida apresenta quadro de diarreia há 3 meses, com fezes\nsemilíquidas, sem sangue e de odor fétido.\nSua mãe relata que esse quadro é intercalado com\nfezes pastosas. Nega febre e apresenta vômitos esporádicos. Ao exame: pálida (+), afebril, muito\nemagrecida (peso e altura abaixo do percentil 10). Pulmões sem ruídos adventícios, cardiovascular\nnormal, abdome distendido e sem visceromegalias. O pediatra levantou a hipótese diagnóstica de\nDoença Celíaca? Marque a alternativa CORRETA em relação aos exames que devem ser\nsolicitados para paciente com suspeita de doença celíaca:","options":{"A":"Anticorpo antiendomísio e anticorpo antitransglutaminase tecidual.","B":"Teste do suor com pilocarpina e iontoforese.","C":"IgE especifica para alimentos e Anticorpo antiendomísio.","D":"Curva de tolerância à lactose e anticorpo antitransglutaminase tecidual."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-283273","number":"283273","sourceNumber":"283273","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 32 anos, do sexo masculino, comparece referindo diarreia volumosa,\nassociada à perda de sangue e muco,\nemagrecimento e lesão de borda anal. Assinale a alternativa\nCORRETA quanto ao diagnóstico mais provável.","options":{"A":"Síndrome de intestino irritável.","B":"Doença de Crohn.","C":"Retocolite ulcerativa.","D":"Colite amebiana."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-247138","number":"247138","sourceNumber":"247138","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma Paciente procura o ambulatório com queixas de diarreia crônica. Qual dos\nsintomas abaixo fala contra o diagnóstico de\ndiarreia funcionar (Síndrome do Intestino Irritável)?","options":{"A":"Piora da diarreia após as refeições (reflexo gastrocólico).","B":"Diarreia noturna que interfere no sono.","C":"Presença de muco transparente nas fezes.","D":"Cólica abdominais difusas e de forte intensidade.","E":"Nenhuma das alternativas."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-217648","number":"217648","sourceNumber":"217648","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma doença tem distribuição bimodal, afetando adultos jovens, com um segundo pico\nde incidência aos setenta anos de idade,\napresenta prevalência particularmente aumentada em\njudeus asquenazes e acomete mais comumente o íleo distal e o cólon proximal. O tabagismo\nassocia-se a um pior prognóstico. Os anti-inflamatórios não hormonais parecem estar associados a\nexacerbações. A doença caracterizada no texto acima é:","options":{"A":"Doença de Whipple.","B":"Linfoma de Hodgkin.","C":"Câncer intestinal.","D":"Doença de Crohn."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-217643","number":"217643","sourceNumber":"217643","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação às parasitoses no Brasil, analise as afirmativas abaixo. l. A profilaxia para\na maioria das doenças parasitárias se\nrestringe ao uso de vacinas. ll. As principais medidas\nprofiláticas contra as verminoses são educação sanitária e saneamento básico. lll. Helmintos são\nparasitas do tubo digestivo, que causam doenças como giardíase, amebíase e toxoplasmose. lV. O\ntratamento da água e o uso de instalações sanitárias adequadas previnem algumas das doenças\nparasitárias mais comuns entre as populações. V. Higiene pessoal e boa alimentação são medidas\nprofiláticas individuais. Estão CORRETAS:","options":{"A":"l, lll e lV.","B":"l, ll e lV.","C":"ll, lll e V.","D":"ll, lV e V."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-182616","number":"182616","sourceNumber":"182616","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente com diarreia crônica com exame de fezes (parasitológico) e teste fecal para\nantígenos de Giardia lamblia negativos, com teste para gordura fecal anormal, sem nenhuma pista\nsobre a etiologia e com teste da D-xilose anormal. Qual a próxima etapa de investigação para\nmelhor elucidação etiológica?","options":{"A":"Coprocultura.","B":"Biópsia de intestino delgado.","C":"Tomografia para avaliar pâncreas.","D":"Teste de secretina."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-159106","number":"159106","sourceNumber":"159106","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Considerando o melhor tratamento das parasitoses intestinais, numere a coluna da\ndireita de acordo com a da esquerda. (1) Teníase; (2) Ascaridíase; (3) Estrongiloidíase; (4)\nAmebíase; (5) Enterobíase; ( ) Albendazol; ( ) Metronidazol; ( ) Mebendazol; ( ) Praziquantel; ( )\nIvermectina. A ordem correta da numeração, na coluna da direita, de cima para baixo, é:","options":{"A":"3 - 5 - 2 - 1 - 4.","B":"2 - 5 - 1 - 4 - 3.","C":"2 - 4 - 5 - 3 - 1.","D":"2 - 4 - 5 - 1 - 3."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-159067","number":"159067","sourceNumber":"159067","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação às doenças inflamatórias intestinais, é CORRETO afirmar que:","options":{"A":"A colite ulcerativa é uma doença de acometimento transmural do intestino, cursando, portanto,\ncom manifestações de obstrução intestinal.","B":"O acometimento da mucosa na doença de Crohn é contínuo, enquanto na colite ulcerativa há\náreas de mucosa doente intercaladas com mucosa normal.","C":"O achado de reto com mucosa normal à colonoscopia, praticamente, exclui do diagnóstico de\ncolite ulcerativa.","D":"A evolução para carcinoma colorretal é mais comum na doença de Crohn que na colite\nulcerativa."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-135966","number":"135966","sourceNumber":"135966","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente com diarreia crônica, com exame de fezes em busca de parasitas e ovos de\nparasitas negativos e teste para gordura fecal anormal. As condutas que deverão ser tomadas são\nas abaixo, EXCETO:","options":{"A":"Avaliar a possibilidade de diarreia aquosa e inflamatória;","B":"Suspeitar de doença pancreática;","C":"Realizar o teste da D-xilose;","D":"Suspeitar de doença de mucosa instestinal proximal."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37078","number":"37078","sourceNumber":"37078","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação à doença de Crohn podemos afirmar que:","options":{"A":"A azatioprina e o metronidazol são úteis no tratamento das fístulas da doença de Crohn.","B":"A sulfassalazina é eficaz no tratamento da manutenção na fase assintomática da doença.","C":"A eficácia da sulfassalazina na doença de Crohn é igual àquela observada no retocolite\nulcerativa.","D":"A retirada cirúrgica de segmentos intestinais acometidos pela doença de Crohn diminui o índice\nde recidiva da doença em um ano.","E":"Acontece somente no Reto e sigmoide."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37098","number":"37098","sourceNumber":"37098","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mãe relata que seu filho de dois anos, procedente da zona rural de Feijó, apresenta,\ndesde nove meses de vida, diarreia crônica,\nfezes muito fétidas e gordurosas. Esta diarreia é\nacompanhada de distensão abdominal, precário estado nutricional e irritabilidade. A família não faz\nuso de água potável e a mãe insiste em relatar que a sintomatologia iniciou após alimentação\ncomplementar. Você está pensando em:","options":{"A":"Parasitose Intestinal","B":"Diarreia crônica inespecífica","C":"Doença Celíaca","D":"Diarreia Persistente","E":"Enterocolite atípica"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37099","number":"37099","sourceNumber":"37099","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mãe relata que seu filho de dois anos, procedente da zona rural de Feijó, apresenta,\ndesde nove meses de vida, diarreia crônica,\nfezes muito fétidas e gordurosas. Esta diarreia é\nacompanhada de distensão abdominal, precário estado nutricional e irritabilidade. A família não faz\nuso de água potável e a mãe insiste em relatar que a sintomatologia iniciou após alimentação\ncomplementar. Tomando em conta que você está pensando em doença celíaca, você pediria que\nexame complementar para iniciar seu estudo diagnóstico:","options":{"A":"Anticorpo Antitransglutaminase","B":"EPF seriado","C":"Coprologia Funcional","D":"Colonoscopia","E":"Prova de absorção de carboidratos"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37101","number":"37101","sourceNumber":"37101","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Escolar, oito anos, apresentando há dois anos febre intermitente, dores em\narticulações, déficit de crescimento, lesões\nperianais, aftas e ocasionalmente diarreia. Diante\ndesse quadro, qual o possível diagnóstico:","options":{"A":"Adenite mesentérica","B":"Doença Celíaca","C":"Doença de Crohn","D":"Retocolite Ulcerativa","E":"Síndrome do Intestino Irritável"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37103","number":"37103","sourceNumber":"37103","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Escolar, oito anos, apresentando há dois anos febre intermitente, dores em\narticulações, déficit de crescimento, lesões\nperianais, aftas e ocasionalmente diarreia. Ao solicitar\nexames complementares, o que espera encontrar para confirmar sua impressão diagnóstica:","options":{"A":"Ecografia Abdominal com aumento de linfonodos peritoneais","B":"Anticorpo antigliadina > 1:80","C":"Colonoscopia com envolvimento macro e microscópio em ânus","D":"Colonoscopia sem envolvimento macro e microscópio em ânus","E":"Eletroforese de proteínas alterada."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37112","number":"37112","sourceNumber":"37112","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa CORRETA: prolapso retal é um achado comum diante de qual\nparasitose intestinal?","options":{"A":"Ascaridíase.","B":"Oxiuríase.","C":"Tricuríase.","D":"Giardíase.","E":"Nenhuma das alternativas."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37113","number":"37113","sourceNumber":"37113","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na criança portadora de Giardíase, que dados da anamnese chamam mais a atenção\npara o diagnóstico:","options":{"A":"Sangramento nas fezes abundante.","B":"Dor abdominal recorrente e fezes ora diarreicas ora endurecidas","C":"Distensão abdominal e circulação colateral.","D":"Febre e vômitos alimentares.","E":"Nenhuma das alternativas."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37149","number":"37149","sourceNumber":"37149","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A doença de CROHN é caracterizada por:","options":{"A":"Inflamação aguda da mucosa e submucosa do intestino grosso e unicamente do reto","B":"Associa-se a hábitos alimentares ricos em fibras vegetais","C":"Inflamação transmural crônica granulomatosa fistulizante","D":"Associa-se a Síndrome do intestino irritável e Polipose juvenil","E":"Apresenta ulcerações superficiais limitadas na mucosa do ileoterminal"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-29385","number":"29385","sourceNumber":"29385","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Os tumores carcinoides do tubo digestivo estão localizados mais frequentemente na\nseguinte região:","options":{"A":"Reto","B":"Cólon","C":"Duodeno","D":"Apêndice cecal","E":"Jejuno e íleo"},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-369530","number":"369530","sourceNumber":"369530","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Considerando esse caso clínico, indique, dentre os exames seguintes, o mais\nimportante para seguimento do caso:","options":{"A":"Parasitológico de fezes.","B":"Endoscopia digestiva alta.","C":"Mielograma.","D":"Biópsia hepática."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-369531","number":"369531","sourceNumber":"369531","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem, 46 anos de idade, assintomático, realizou exames laboratoriais gerais,\nsolicitados na UBS, que evidenciaram plaquetas\nde 40mil/mm³, com transaminases normais.\nRealizou ultrassonografia de abdome, com sinais de hepatopatia, esplenomegalia, aumento do\ncalibre da veia porta com presença de circulação colateral. Sorologias com IgG reagente para\nesquistossomose e negativas para hepatites virais. Identifique, diante de uma biópsia hepática, o\nachado mais esperado nesse caso:","options":{"A":"Infiltrado linfoplasmocitário periportal.","B":"Oclusão da veia centrolobular.","C":"Granuloma portal.","D":"Fibrose periductular."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-369532","number":"369532","sourceNumber":"369532","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem, 46 anos de idade, assintomático, realizou exames laboratoriais gerais,\nsolicitados na UBS, que evidenciaram\nplaquetas de 40mil/mm³, com transaminases normais.\nRealizou ultrassonografia de abdome, com sinais de hepatopatia, esplenomegalia, aumento do\ncalibre da veia porta com presença de circulação colateral. Sorologias com IgG reagente para\nesquistossomose e negativas para hepatites virais. Em relação ao caso apresentado, é correto\nafirmar:","options":{"A":"O tratamento com praziquantel é capaz de reverter, parcialmente, o dano hepático, devendo ser\nsempre oferecido.","B":"O dano hepático é irreversível e o tratamento estará indicado na presença de ovos viáveis.","C":"O parasitológico de fezes com o método de Baermann deve ser realizado para definição do\ntratamento.","D":"O dano hepático é irreversível, sendo prescindível o parasitológico de fezes e o tratamento com\nantiparasitários."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-341089","number":"341089","sourceNumber":"341089","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Jovem, 15 anos de idade, é acompanhado na UBS com historia de diarreia intermitente\nhá 8 meses. Tem episódios de até 6 dejeções\ndia, com muco e sangue, durando no máximo, 2\ndias, ficando ate 15 dias sem diarreia. Nega correlação com consumo determinado de alimentos.\n\nMorador de zona rural, costuma tomar banho no pequeno açude próximo da sua casa. Consome\nagua fervida e usa fossa seca para suas\ndejeções. Apresenta ao exame físico discreta\nhepatomegalia sem outras alterações. Fez tratamento empírico com albendazol, sem melhora.\n\nRealizou parasitológico de fezes que evidenciou ovos de Schistosoma Mansoni. Considerando a\ndescrição do caso, indique, entre as outras parasitoses, a que poderia ser responsável pelo quadro:","options":{"A":"Giardíase.","B":"Tricuríase.","C":"Amebíase.","D":"Estrongiloidiase."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-341090","number":"341090","sourceNumber":"341090","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Jovem, 15 anos de idade, é acompanhado na UBS com historia de diarreia intermitente\nhá 8 meses. Tem episódios de até 6 dejeções\ndia, com muco e sangue, durando no máximo, 2\ndias, ficando ate 15 dias sem diarreia. Nega correlação com consumo determinado de alimentos.\n\nMorador de zona rural, costuma tomar banho no pequeno açude próximo da sua casa. Consome\nagua fervida e usa fossa seca para suas\ndejeções. Apresenta ao exame físico discreta\nhepatomegalia sem outras alterações. Fez tratamento empírico com albendazol, sem melhora.\n\nRealizou parasitológico de fezes que evidenciou ovos de Schistosoma Mansoni. Indique o fármaco\ndisponível, atualmente no Brasil, para tratamento de primeira linha por seu perfil de segurança\nquanto aos efeitos colaterais:","options":{"A":"Oxamniquine.","B":"Praziquantel.","C":"Nitazoxanida.","D":"Benzonidazol."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-314220","number":"314220","sourceNumber":"314220","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na constituição da parede do trato gastrointestinal, é o segmento da parede em que é\npoupado de lesão inflamatória nos pacientes\ncom colite ulcerativa:","options":{"A":"Mucosa.","B":"Submucosa.","C":"Muscular.","D":"Epitélio."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-275970","number":"275970","sourceNumber":"275970","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual dos parasitas relacionados abaixo apresenta como sintomas predominantes:\ndiarreia, tosse, sibilo, dor abdominal ? de\npredomínio epigástrico, erupção cutânea e perda de\npeso?","options":{"A":"Giardia lamblia.","B":"Ascaris lumbricoides.","C":"Strongyloides stercoralis.","D":"Enterobius vermicularis.","E":"Trichuris trichiura."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-278098","number":"278098","sourceNumber":"278098","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa que apresenta os defeitos estruturais dos enterócitos na Displasia\nEpitelial Intestinal.","options":{"A":"Formação de vacúolos nos enterócitos e desarranjo da arquitetura as microvilosidades.","B":"Estrutura da membrana basal dos enterócitos com anomalias na composição da lamilina e dos\nproteoglicanos.","C":"Mutações no transportador glicose/ sódio.","D":"Alterações do bordo em escova, acarretando perda da função absortiva."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-279055","number":"279055","sourceNumber":"279055","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É responsável pela irrigação do intestino anterior:","options":{"A":"Tronco celíaco.","B":"Artéria mesentérica anterior.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-280425","number":"280425","sourceNumber":"280425","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Masculino, 91 anos, em internação prolongada com uso de várias classes de\nantibióticos. Há 3 dias apresentou febre e diarreia com eliminação de sangue, pus e muco,\nassociada a distensão abdominal sem sinais de peritonite. A principal hipótese diagnóstica é:","options":{"A":"Retocolite ulcerativa idiopática.","B":"Diverticulite complicada.","C":"Atelectasia.","D":"Colite pseudomembranosa."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-280426","number":"280426","sourceNumber":"280426","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É responsável pela etiologia da colite pseudomembranosa:","options":{"A":"Escherichia coli","B":"Acinetobacter sp.","C":"Clostridium difficile","D":"Klebsiella pneumoniae"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-278639","number":"278639","sourceNumber":"278639","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em geral, os tumores carcinoides raramente são malignos e se originam das células\nprecursoras neuroendócrinas e podem se apresentar em qualquer lugar do corpo humano. A\nlocalização mais comum é o trato gastrointestinal, abrangendo mais da metade de todos os\ncarcinoides. Assinale a alternativa com os locais mais comuns do trato gastrointestinal:","options":{"A":"Intestino delgado, reto e o apêndice cecal.","B":"Intestino grosso, reto, estômago.","C":"Esôfago, intestino delgado e reto.","D":"Reto, pâncreas e mesentério."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-279069","number":"279069","sourceNumber":"279069","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É responsável pela irrigação do intestino médio:","options":{"A":"Tronco celíaco.","B":"Artéria mesentérica anterior.","C":"Artéria mesentérica superior.","D":"Artéria mesentérica inferior."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249278","number":"249278","sourceNumber":"249278","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença intestinal inflamatória que pode aceitar como\ncorreto o seguinte item:","options":{"A":"Mais de 6 semanas de diarreia é o prazo sugerido como critério para diferenciação com diarreia\naguda infecciosa.","B":"Menos de 6 semanas de diarreia é o prazo sugerido como critério para diferenciação com\ndiarreia aguda infecciosa.","C":"Mais de 6 meses de diarreia é o prazo sugerido como critério para diferenciação com diarreia\naguda infecciosa.","D":"A diarreia não é sugerida como critério para diferenciação com diarreia aguda infecciosa."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249378","number":"249378","sourceNumber":"249378","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na Doença de Crohn (DC) a atividade aumentada da enzima tiopurinametiltransferase\nTPMT leva a baixa formação de 6-tioguanina e a\naumento dos níveis de 6-metilmercaptopurina,\ncom consequentes redução da eficácia e maior risco de hepatotoxicidade da azatioprina. Podemos\nconcordar com o item:","options":{"A":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativo aumento da atividade da doença,\npossibilitando a redução da dose de corticosteroide, sem aumento de toxicidade hepática.","B":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativa diminuição da atividade da\ndoença, possibilitando a redução da dose de corticosteroide, sem aumento de toxicidade hepática.","C":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativa diminuição da atividade da\ndoença, possibilitando a aumento da dose de corticosteroide, sem aumento de toxicidade hepática.","D":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina, levou a significativa diminuição da atividade da\ndoença, possibilitando a redução da dose de corticosteroide, mas também com aumento de\ntoxicidade hepática."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249279","number":"249279","sourceNumber":"249279","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença intestinal inflamatória sendo sua localização\napenas no esôfago é rara. Somente 5% dos pacientes com essa doença têm acometimento\ngastroduodenal. Podemos apenas aceitar que:","options":{"A":"Quando ocorre acometimento do estômago e do duodeno, justifica-se o uso de fármacos que\nnão alterem agressão péptica, sendo indicados\ninibidores da bomba de prótons.","B":"Quando ocorre acometimento do estômago e do duodeno, justifica-se o uso de fármacos que\ndiminuam a agressão péptica, não sendo indicados inibidores da bomba de prótons.","C":"Quando ocorre acometimento do estômago e do duodeno, justifica-se o uso de fármacos que\ndiminuam a agressão péptica, sendo indicados inibidores da bomba de Na e K.","D":"Quando ocorre acometimento do estômago e do duodeno, justifica-se o uso de fármacos que\ndiminuam a agressão péptica, sendo indicados inibidores da bomba de prótons."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249380","number":"249380","sourceNumber":"249380","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença inflamatória intestinal, que apresenta exame\nhistopatológico pode indicar o seguinte item:","options":{"A":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão segmentar e\npresença de granulomas não caseosos.","B":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão não segmentar\ne presença de granulomas não caseosos.","C":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão segmentar e\npresença de granulomas caseosos.","D":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão generalizado e\nausência de granulomas não caseosos."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249282","number":"249282","sourceNumber":"249282","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na Doença de Crohn (DC), pacientes em uso da associação azatioprina e alopurinol\ndevem ser monitorizados laboratorialmente em\nrelação às contagens de leucócitos, semanalmente\nno primeiro mês e quinzenalmente no segundo mês. Está correto que:","options":{"A":"Ocorrendo leucopenia, recomenda-se o aumento da dose de azatioprina, de acordo com a\ngravidade do caso.","B":"Ocorrendo leucopenia, recomenda-se a redução da dose de azatioprina (50% da dose atual) ou\nmesmo a sua suspensão, de acordo com a\ngravidade do caso.","C":"Ocorrendo leucopenia, recomenda-se a redução da dose de azatioprina (50% da dose atual)\nindependente da gravidade do caso.","D":"Ocorrendo leucopenia, recomenda-se a redução da dose de azatioprina (50% da dose atual),\nmas nunca sua suspensão, independente da gravidade do caso."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249384","number":"249384","sourceNumber":"249384","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na Doença de Crohn (DC) nos casos em que não há resposta inicial com o uso em\ndoses adequadas de azatioprina, recomenda-se a\nassociação de azatioprina mais alopurinol.\n\nAssim, está correto que:","options":{"A":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) semanal.","B":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) mensal.","C":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou\nhipersensibilidade à azatioprina, pode-se usar metotrexato por via EV\nquinzenal.","D":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente não tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) semanal."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249386","number":"249386","sourceNumber":"249386","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença inflamatória intestinal, podemos apenas aceitar\ncomo adequado o item:","options":{"A":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\npior método para o diagnóstico e revela tipicamente lesões ulceradas.","B":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela tipicamente lesões ulceradas, entremeadas de\náreas com mucosa normal, acometimento focal, assimétrico e descontínuo.","C":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela tipicamente lesões ulceradas, não entremeadas de\náreas com mucosa normal, acometimento generalizado, simétrico e descontínuo.","D":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela raramente lesões ulceradas, e nunca entremeadas\nde áreas com mucosa normal, acometimento focal, assimétrico e contínuo."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-231356","number":"231356","sourceNumber":"231356","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa correta: De acordo com o Consenso Roma IV, o período em que\nos sintomas devem estar ocorrendo para que se\nfaça o diagnostico de Dispepsia Funcional é:","options":{"A":"Sintomas tenham iniciado a pelo menos 12 meses e ativos nos últimos 3 meses","B":"Seis meses com sintomas presentes e que tenham melhorados nos últimos 3 meses.","C":"Sintomas tenham iniciado há pelo menos 6 meses do diagnostico e presentes nos últimos 3\nmeses.","D":"Sintomas tenham iniciado há 12 meses e presentes nos últimos 2 meses.","E":"Nenhuma das alternativas acima."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249236","number":"249236","sourceNumber":"249236","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 8 anos, trazido pela mãe com queixas de perda ponderal e dor abdominal\ndifusa há 7 meses. Queixa-se também de\nepisódios esporádicos e auto-limitados de diarreia, sem\nfebre, sem eliminação de muco, pus ou sangue. AO exame físico: emagrecido, descorado, abdome\nlevemente distendido, doloroso difusamente, sem sinais de peritonite, com presença de abscesso\nperianal. A principal hipótese diagnóstica é:","options":{"A":"Doença de Crohn.","B":"Alergia a proteína do leite de vaca.","C":"Doença de Hirchsprung.","D":"Pancreatite crônica auto-imune juvenil."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216236","number":"216236","sourceNumber":"216236","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"São vermes que apresentam passagem pelo pulmão no seu ciclo vital todos os abaixo,\nEXCETO","options":{"A":"Ascaris lumbricoides.","B":"Necator americanos.","C":"Ancylostoma duodenalis.","D":"Giardia Lamblia."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216248","number":"216248","sourceNumber":"216248","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre os tumores carcinoides é INCORRETO que","options":{"A":"é a neoplasia neuroendócrina mais comum do trato digestório.","B":"a localização gástrica é muito frequente.","C":"a síndrome carcinoide é mediada pela serotonina e caracterizada por flush cutâneo,\nbroncoespasmo e taquicardia.","D":"os carcinoides gástricos provocam poucas metástases."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-181368","number":"181368","sourceNumber":"181368","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 32 anos, com diagnóstico de retocolite ulcerativa há 6 anos, em tratamento\nirregular e sem seguimento ambulatorial\nnos últimos 2 anos. Admitido em pronto-atendimento por\ndor abdominal e diarreia. Ao exame, ruim estado geral, taquicárdico e hipocorado. O abdome é\npouco distendido, doloroso e sem descompressão negativa, sem cicatrizes cirúrgicas. Hemograma\nrevela hemoglobina de 6, leucocitose de 17000, 3% bastões, PCR 120, VHS 60. Em relação ao\ncaso e à doença, é correto afirmar:","options":{"A":"o uso de corticoides sistêmicos não é benéfico nessa fase da doença.","B":"o tratamento inicial deve ser hidratação vigorosa, dieta oral hipercalórica e hipoproteica.","C":"esse paciente deve ser submetido à colectomia subtotal com ileostomia terminal de urgência.","D":"o tratamento inicial deve ser hidratação venosa vigorosa, antibioticoterapia e imunobiológico.","E":"os pacientes que apresentam coprocultura positiva para C. difficile podem beneficiar-se de\ntransplante fecal em algumas situações."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183084","number":"183084","sourceNumber":"183084","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A síndrome de Loeffler representa uma pneumonite eosinofílica transitória, por reação\nde hipersensibilidade imediata, decorrente da\nmigração pulmonar das larvas de parasitas. Os\nprincipais agentes causadores da síndrome de Loeffler são, EXCETO:","options":{"A":"Ascaris lumbricoides.","B":"Ancylostoma duodenale.","C":"Enterobius vermiculares.","D":"Necator americanus."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183043","number":"183043","sourceNumber":"183043","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Marque a afirmativa CORRETA em relação às verminoses.","options":{"A":"A teníase, conhecida popularmente como ?solitária?, é causada pelos cestódeosTaeniasolium e\nTaeniasaginata. A T. solium é adquirida pelo consumo da carne de porco mal cozida e a T.saginata\npelo consumo da carne de boi contaminada.","B":"A esquistossomose é considerada uma doença de difícil transmissão, sendo baixo o risco de\nadquiri-la em um único contato com focos de contaminação.","C":"A Entamoebahistolytica é o agente etiológico da amebíase, parasita do intestino grosso, que tem\na transmissão apenas por meio do contato sexual.","D":"A giardíase é causada por um protozoário e acomete principalmente a região gástrica, causando\nfortes dores na criança."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183601","number":"183601","sourceNumber":"183601","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença inflamatória intestinal de origem não\nconhecida, caracterizada pelo acometimento focal,\nassimétrico e transmural de qualquer porção do\ntubo digestivo, da boca ao ânus. Sendo INADEQUADO, apenas, o seguinte item:","options":{"A":"Apresenta-se sob três formas principais: inflamatória, fistulosa e fibroestenosante. Os segmentos\ndo tubo digestivo mais acometidos são: íleo,\ncólon e região perianal.","B":"Além das manifestações no sistema digestório, a DC pode ter manifestações extraintestinais,\nsendo as mais frequentes as oftalmológicas, as\ndermatológicas e as reumatológicas.","C":"A DC tem início mais frequentemente na segunda e terceira décadas de vida, mas não pode\nafetar qualquer faixa etária.","D":"Em países desenvolvidos, a prevalência e a incidência situam-se em torno de 50:100.000 e\n5:100.000, respectivamente."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183562","number":"183562","sourceNumber":"183562","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn DC não é curável clínica ou cirurgicamente, e sua história natural é\nmarcada por agudizações e remissões. A diferenciação entre doença ativa e em remissão pode ser\nfeita com base no Índice de Harvey-Bradshaw. Sendo INADEQUADO, apenas, que","options":{"A":"pacientes sem sintomas (IHB igual ou inferior a 4) e sem uso de corticosteroide são\nconsiderados em remissão sintomática.","B":"pacientes que necessitam de corticosteroide para permanecer assintomáticos não são\nclassificados como corticodependentes, sendo considerados em remissão, devido ao risco de\ntoxicidade do tratamento prolongado.","C":"pacientes com doença leve a moderada (IHB igual a 5, 6 ou 7) costumam ser atendidos\nambulatoriamente, toleram bem a alimentação, estão bem hidratados, não apresentam perda de\npeso superior a 10%, sinais de toxicidade, massas dolorosas à palpação ou sinais de obstrução\nintestinal.","D":"pacientes com doença moderada a grave (IHB igual ou superior a 8), usualmente, estão com o\nestado geral bastante comprometido e apresentam, ainda, um ou mais dos seguinte sintomas:\nfebre, perda de peso, dor abdominal acentuada, anemia ou diarreia frequente (3-4 evacuações ou\nmais por dia)."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183603","number":"183603","sourceNumber":"183603","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O diagnóstico pode ser difícil devido à heterogeneidade das manifestações e à sua\nsobreposição com as da retocolite ulcerativa, bem como a ocasional ausência de sintomas\ngastrointestinais relevantes. Sendo INCORRETO, apenas, que","options":{"A":"o sintoma mais comum no momento do diagnóstico é diarreia, seguida por sangramento\n(40%-50%), perda de peso (60%) e dor abdominal\n(70%).","B":"os sinais mais comuns são febre, palidez, caquexia, massas abdominais, fístulas e fissuras\nperianais.","C":"a endoscopia mostra tipicamente lesões ulceradas, entremeadas de áreas com mucosa normal,\nacometimento focal, simétrico e contínuo, podendo, também, ser útil para a coleta de material para\nanálise histopatológica.","D":"mais de 6 semanas de diarreia é o critério sugerido como prazo útil para diferenciação com\ndiarreia aguda infecciosa."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183641","number":"183641","sourceNumber":"183641","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O diagnóstico pode ser difícil devido à heterogeneidade das manifestações e à sua\nsobreposição com as da retocolite ulcerativa, sendo que endoscopia mostra tipicamente lesões\nulceradas, entremeadas de áreas com mucosa normal, acometimento focal para a coleta de\nmaterial para análise histopatológica. Sendo ADEQUADO, apenas, que a análise histológica","options":{"A":"nunca pode indicar acometimento transmural (quando da análise de ressecções cirúrgicas),\npadrão segmentar e presença de\n\ngranulomas não caseosos.","B":"pode indicar acometimento transmural (quando da análise de ressecções cirúrgicas), padrão\nsegmentar e presença de\n\ngranulomas não caseosos.","C":"pode indicar acometimento transmural (quando da análise de ressecções cirúrgicas), padrão\nsegmentar e presença de\n\ngranulomas caseosos.","D":"pode indicar acometimento transmural (quando da análise de ressecções cirúrgicas), padrão\nsegmentar e ausência de\n\ngranulomas não caseosos."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183620","number":"183620","sourceNumber":"183620","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Durante a gestação, a atividade da doença está relacionada a abortamento, sendo que\na sulfassalazina apresenta diversas interações.\nIndique, das abaixo, qual está ERRADA.","options":{"A":"A sulfassalazina não interfere no metabolismo normal do ácido fólico, não sendo necessário ser\nsuplementado no período preconcepção.","B":"É seguro sulfassalazina durante os dois primeiros trimestres da gestação.","C":"No último trimestre, a sulfassalazina pode com seu uso, aumentar o risco de Kernicterus.","D":"Mesalazina é considerada segura durante a gestação em doses de até 3 g/dia, não tendo sido\ntestadas doses maiores."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-161118","number":"161118","sourceNumber":"161118","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação à doença inflamatória intestinal, assinale a alternativa INCORRETA.","options":{"A":"Doença de Crohn é uma doença inflamatória crônica, transmural do trato gastrointestinal de\ncausa desconhecida. Afeta mais comumente o\nintestino delgado. O risco de desenvolver Crohn é\nduas vezes mais elevado em fumantes do que em não fumantes.","B":"São manifestações extraintestinais da doença de Crohn: eritema multiforme, eritema nodoso,\npioderma gangrenoso, irite, uveíte, conjuntivite, artrite, espondilite anquilosante, anemia,\ntrombocitose, colangite esclerosante, amiloidose e pancreatite.","C":"Os corticosteroides, particularmente a prednisona, são benéficos na indução da remissão, porém\nsão ineficazes na manutenção da remissão.","D":"As operações decorrentes à doença de Crohn são na maioria das vezes curativas, com taxas de\nrecorrência muito baixas."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-158810","number":"158810","sourceNumber":"158810","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher, 18 anos, procura serviço médico, pois há 1 ano vem apresentando rubor facial\n(flushing), cólicas abdominais, náuseas, vômitos, diarreia e episódios de broncoespasmos.\n\nTomografia de abdômen e pelve mostrou massa sólida hipervascularizada mesentérica em\ncontinuidade com jejuno associada a múltiplas lesões hepáticas compatíveis com lesões\nsecundárias. Qual o diagnóstico mais provável?","options":{"A":"Síndrome de Felty.","B":"Doença de Addison.","C":"Síndrome carcinoide.","D":"Síndrome de Ogilvie.","E":"Síndrome de Zollinger-Ellison."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-158752","number":"158752","sourceNumber":"158752","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente portadora de pênfigo vulgar com indicação de uso de corticosteroide em dose\nimunossupressora, antes do início da corticoterapia, realizou exame de fezes, no qual foram\nobservadas larvas de Strongyloides stercoralis. Sobre a infecção causada pelo parasita, qual a\nalternativa correta?","options":{"A":"Ivermectina, albendazol, secnidazol e tiabendazol são opções terapêuticas para o tratamento da\nparasitose intestinal em questão.","B":"O uso de metronidazol, em dose dupla, é indicado nos pacientes imunocomprometidos que\napresentem estrongiloidíase.","C":"Do ponto de vista do exame coprológico, o método recomendado para confirmar o diagnóstico\nda referida parasitose intestinal é o de\nKato-Katz.","D":"O paciente em questão apresenta risco de desenvolver estrongiloidíase disseminada, também\nchamada de hiperinfecção, cuja principal manifestação é a meningite asséptica.","E":"As manifestações clínicas mais frequentes que ocorrem em pacientes infectados pelo parasita\nsão as gastrintestinais, nas quais\npredominam: distensão abdominal, flatulência, dor em cólica ou\nem queimação em epigástrio, anorexia, náusea, vômitos, diarreia secretora ou esteatorreia e\ndesnutrição proteico-calórica."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-134848","number":"134848","sourceNumber":"134848","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente refere intensa cefaleia durante avaliação inicial, refere que o quadro se\niniciou após estresse emocional por discussão familiar. Não apresenta perdas segmentares\nou irritação meníngea, seu Glasgow está em 15. Porém, ao aferir sua pressão, encontramos\no valor de 190 X 110 mmHg. Assim, consideramos ADEQUADO","options":{"A":"Realizar TC de crânio de urgência, provavelmente se trata de HSA.","B":"Iniciar Nitroprussiato de Sódio por se tratar de Encefalopatia Hipertensiva.","C":"Medicar com analgésicos e ansiolíticos e, posteriormente, avaliar novamente PA.","D":"Abordagem como Urgência Hipertensiva com Nifedipina 10 mg de ação rápida."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-134831","number":"134831","sourceNumber":"134831","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Menina de 13 anos passa em consulta médica com história de 3 meses de dor\nabdominal difusa, febre, perda de peso, dores\narticulares e sangramento retal intermitente. Nesse\ncaso, qual é o diagnóstico MAIS provável?","options":{"A":"Intolerância à Lactose.","B":"Doença de Crohn.","C":"Divertículo de Meckel.","D":"Síndrome do Intestino Irritável."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-110547","number":"110547","sourceNumber":"110547","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher com 30 anos, portadora de retocolite ulcerativa inespecífica, após uso de\nopioides para controle de diarreia, chega ao pronto-socorro com febre e dor abdominal. Ao\nexame é constatado taquicardia, timpanismo abdominal e leucocitose. O exame complementar\nmais adequado para confirmar o diagnóstico é:","options":{"A":"Enema opaco.","B":"Tomografia computadorizada de abdome total.","C":"Colonoscopia.","D":"Radiografia simples de abdome.","E":"Trânsito intestinal com cápsula endoscópica."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-86842","number":"86842","sourceNumber":"86842","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Marque a alternativa que contém a parasitose que pode causar anemia severa.","options":{"A":"Giardíase;","B":"Tricuríase;","C":"Enterobíase;","D":"Amebíase;","E":"Teníase."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-108615","number":"108615","sourceNumber":"108615","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação ao tratamento da giardíase, qual destas medicações não indicada:","options":{"A":"Albendazol.","B":"Tinidazol.","C":"Secnidazol.","D":"Metronidazol.","E":"Prazinquantel."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-327292","number":"327292","sourceNumber":"327292","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Escolar, 7 anos, foi ao atendimento médico com quadro de febre persistente há quatro\nsemanas. Os pais informaram que a menina já tinha ido várias vezes ao médico sem diagnóstico e\nque em 2 consultas foi medicada com antibióticos sem melhora. Fala ainda que, apesar da febre, a\npaciente apresentava bom estado geral e que em casa tinha 2 filhotes de cães. Exame físico:\nmenor, bom estado geral, leucocitose, eosinofilia, hepatomegalia, febre e sibilância. Assinale a\nalternativa CORRETA.","options":{"A":"Leucemia eosinofílica.","B":"Enterobíase.","C":"Ascariadíase.","D":"Toxocariase."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-298260","number":"298260","sourceNumber":"298260","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mãe traz sua filha de 2 anos à consulta com queixas de prurido perianal e perineal. Ela\ndiz que o prurido ocorre mais à noite, mas nega febre, diarreia ou vômitos. A menina frequenta\ncreche e é sempre muito ativa. Ao exame físico, a região perianal está bem hiperemiada e irritada,\ntônus do esfíncter anal normal, sem indícios de trauma por penetração. A região perineal também\nestá avermelhada e escoriada. Exceto pela secreção vaginal esbranquiçada, a região da fralda está\nlimpa. O tratamento mais adequado para o diagnóstico em questão seria:","options":{"A":"Praziquantel.","B":"Albendazol.","C":"Metronidazol.","D":"Secnidazol."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-362487","number":"362487","sourceNumber":"362487","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual a manifestação extra-intestinal mais comum na doença de Crohn?","options":{"A":"Artrite.","B":"Uveíte.","C":"Pioderma gangrenoso.","D":"Eritema nodoso."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-362502","number":"362502","sourceNumber":"362502","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo masculino, 32 anos, portador de Retocolite Ulcerativa procura\natendimento médico por dor abdominal. Teve o\ndiagnóstico fechado após crises de diarreia\nsanguinolenta, sendo submetido a colonoscopia na época. Desde então vem sendo tratado por\naminossalicilatos orais, porém refere uso irregular da medicação. A crise atual iniciou há 3 dias,\ncom cólica abdominal difusa progressiva associada a quadro de diarreia com sangue. Evoluiu com\npiora do estado geral, iniciando febre diária, piora da frequência e volume sanguinolento da\ndiarreia\n(cerca de 10 episódios ao dia), anorexia e queda do estado geral. Ao exame físico, encontra-se em\nREG, pálido, taquicárdico, levemente dispneico e normotenso. Seu abdome é algo distendido,\ndoloroso à palpação profunda difusamente, sem irritação peritoneal. Sua investigação laboratorial\nevidenciou Leucograma: 16.000, Hb: 9g/dl, Proteína C reativa: 68mg/dl e VHS: 75mm/h. Sobre o\ncaso descrito, assinale a alternativa CORRETA:","options":{"A":"Há indicação de internação hospitalar para ressuscitação volêmica, monitorização e início do\ntratamento clínico com opióides para a dor e loperamida para o quadro diarreico.","B":"O tratamento da crise aguda com ciclosporina e infliximabe podem evitar a evolução para\ntratamento cirúrgico de urgência.","C":"Evolução para megacólon tóxico piora bastante o prognóstico deste paciente, estando indicado\no enema opaco baritado para confirmação do seu\ndiagnóstico.","D":"O risco iminente de sepse contraindica o uso de corticoides neste caso."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-327291","number":"327291","sourceNumber":"327291","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mãe de uma criança de 5 anos, telefona para seu Pediatra, pois foi trocar a fralda da\nfilha, encontrou pequenos vermes brancos, lembrando linhas grossas, em grande quantidade no\nânus e alguns na vulva da menina. A transmissão e o ciclo deste parasita se fazem através do\nseguinte mecanismo:","options":{"A":"Larva - pele - corrente sanguínea - intestino delgado.","B":"Cesticerco - pele - eclosão - desenvolvimento - intestino grosso.","C":"Ovo - deglutição - eclosão desenvolvimento - intestino grosso.","D":"Ovo - deglutição - eclosão - ciclo pulmonar - intestino delgado."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-286708","number":"286708","sourceNumber":"286708","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 30 anos, sem comorbidades prévias, apresentando quadro de dor\nabdominal e diarreia aquosa há 6 semanas, com\nmuco, pus e sangue. Submetido a colonoscopia\nque evidenciou múltiplas úlceras em íleo terminal, cólon direito e transverso, com áreas\nentremeadas de mucosa sã. Exame proctológico identificando fístula perianal. O diagnóstico mais\nprovável é:","options":{"A":"Tuberculose intestinal.","B":"Amebíase.","C":"Doença de Crohn.","D":"Retocolite ulcerativa."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-286709","number":"286709","sourceNumber":"286709","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente com diagnóstico de RCUI (retocolite ulcerativa) que evoluiu para a forma\ngrave da doença, sem melhoras após corticoterapia venosa habitual, tem como melhor opção\nterapêutica:","options":{"A":"Metotrexate.","B":"Ciclosporina venosa.","C":"Corticoide em doses imunossupressoras.","D":"Mesalazina."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-286732","number":"286732","sourceNumber":"286732","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, é trazida por familiares para avaliação médica\ndevido a quadro de diarreia com muco e\nsangue há 2 semanas, com piora progressiva, associada a\ntenesmo e cólica em Fossa Ilíaca Esquerda (FIE) e Flanco Esquerdo (FE) de leve intensidade que\nmelhorava após a defecação. Nega vômitos e febre. Nega episódios anteriores. Encontrava-se\nbastante pálida e desidratada, taquicárdica, eupneica e normotensa. Seu abdome era plano,\nflácido, indolor à palpação. Toque retal discretamente doloroso, com sangue em dedo de luva, sem\nmassas ou nodulações palpáveis. A paciente foi então internada para investigação. Ao hemograma:\nhemoglobina 9g/dl e hematócrito 28%. Foi submetida a colonoscopia que evidenciou reto e cólon\nsigmóide com mucosas circunferencialmente acometidas, bastante hiperemiadas e friáveis,\ncontendo múltiplas úlceras rasas. Assinale a alternativa INCORRETA:","options":{"A":"Leucocitose discreta, elevados níveis de Proteína C Reativa e de Calprotectina fecal são\nesperados no perfil laboratorial desta paciente.","B":"Caso não seja tratada adequadamente, esta paciente pode evoluir com múltiplas fístulas\nperianais complexas.","C":"O tratamento inicial desta paciente possivelmente envolverá Mesalazina oral e retal e\ncorticoides.","D":"O uso de Infliximabe não está indicado neste momento do tratamento desta paciente."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-252276","number":"252276","sourceNumber":"252276","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Menino de 4 anos, proveniente de uma comunidade rural, há 7 dias iniciou quadro de\nfebre, que durou 4 dias, tosse com expectoração hialina e diarreia, com fezes líquidas de cor\namarelo-esverdeada, odor fétido, 5 vezes ao dia, sem muco ou sangue. Apresenta-se com\nadinamia e recusa alimentar. Ao exame: regular estado geral, acianótico, anictérico, afebril,\nhidratado, hipocorado (1+/4+), ausculta cardíaca sem alterações, ausculta pulmonar com roncos e\nsibilos difusos. Abdome normotenso, globoso, hipertimpânico, indolor, fígado palpável a 3 cm do\nRCD, parenquimatoso. Exames laboratoriais: hemograma com Hb: 8,5 g/dl; Leucócitos: 12.000\n(25% de eosinófilo), RX tórax com infiltrado peri-hilar e hilar difuso. Qual o provável agente\nresponsável pela associação deste quadro intestinal com manifestação pulmonar e a opção\nterapêutica?","options":{"A":"Strongyloides stercolaris, tiabendazol.","B":"Enterobius vermicularis, pamoato de pirantel.","C":"Trichuris trichiura, albendazol.","D":"Entamoeba hystolitica, metronidazol."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-252280","number":"252280","sourceNumber":"252280","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um profissional de saúde está trabalhando numa unidade básica de saúde, como\nmédico pediatra do Programa Saúde da Família. O\nagente comunitário de saúde solicita que ele\nfaça uma palestra sobre parasitose intestinal numa escola da comunidade, onde há vários casos de\nancilostomíase. Pede que fale sobre suas complicações para sensibilizar a adesão ao tratamento\nda parasitose. Durante a palestra deve-se ressaltar que uma complicação importante deste parasita\né:","options":{"A":"Abcesso hepático.","B":"Pancreatite aguda.","C":"Colecistite crônica.","D":"Anemia e desnutrição."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-252287","number":"252287","sourceNumber":"252287","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Escolar de 5 anos, apresenta episódios de doença diarreica aguda, com fezes\nvolumosas, por vezes com alimentos mal\ndigeridos. A mãe refere hiporexia, e distensão abdominal\napós alimentação, às vezes com náuseas, vômitos. No gráfico de crescimento, observamos\ndesaceleração do ganho ponderal. A parasitose intestinal que frequentemente associa-se a esse\nquadro é:","options":{"A":"Giardiase","B":"Ascaridiase","C":"Teniase","D":"Amebiase"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-208307","number":"208307","sourceNumber":"208307","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Criança com 6 anos de vida está em investigação para diarreia crônica. Coletamos\nexame de fezes onde foi observada a presença\nde giárdia em grande quantidade. Qual a droga\nmais adequada para o tratamento?","options":{"A":"Albendazol ou mebendazol.","B":"Tinidazol ou nitazoxanida.","C":"Paromomicina ou mebendazol.","D":"Mebendazol ou tinidazol."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-176069","number":"176069","sourceNumber":"176069","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo feminino, 72 anos, internada há 7 dias devido ao quadro de diarreia\nmucossanguinolenta (cerca de 3 episódios ao dia), acompanhada de leve dor abdominal difusa,\ntipo cólica, tontura e astenia. Não apresentou febre no período. Nega diabetes e outras\ncomorbidades. Deu entrada com sinais de hipovolemia leve que melhoraram após expansão com\ncristaloides. Seus exames laboratoriais evidenciam leucograma = 14.000; hematócrito = 32%;\nhemoglobina = 11 g/dl; VHS = 10 mm/h e albumina sérica normal. Foi submetida à colonoscopia\nque evidenciou múltiplas úlceras rasas, coalescentes, friáveis, que acometiam cólon descendente,\nsigmoide e reto, circunferencialmente, poupando a região anal. Assinale a alternativa CORRETA:","options":{"A":"Há indicação de investigação tomográfica para avaliar a possibilidade de metástases hepáticas.","B":"Há indicação de retossigmoidectomia de urgência devido ao quadro de megacólon tóxico com\npossível evolução para perfuração e peritonite.","C":"O exame histopatológico provavelmente evidenciará glândulas da mucosa de arquitetura\naberrante, com atipia celular, infiltrado\nneutrofílico ausente e padrão invasivo de camadas\nprofundas da parede do cólon.","D":"A mesalazina e corticoides provavelmente farão parte do tratamento desta paciente."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-176058","number":"176058","sourceNumber":"176058","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa CORRETA sobre tumores carcinoides:","options":{"A":"A maioria dos pacientes com esses tumores apresentam a síndrome carcinoide, que inclui\nmanifestações vasomotoras, cardíacas e gastrointestinais.","B":"Quando ocorrem no intestino delgado, o duodeno é o local mais acometido.","C":"Não apresentam potencial de malignidade.","D":"No trato gastrointestinal, o local mais afetado é o apêndice."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-176057","number":"176057","sourceNumber":"176057","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Você é médico em uma comunidade carente de Manaus e está consultando Ângela de\n3 anos. O motivo da consulta é pedir remédio\npara verme, pois a menina está ?coçando o\nbumbum?. Seu cartão de vacinas está atualizado, ela não apresenta doenças prévias, nunca foi\ninternada. Mora em casa de madeira, às margens de um igarapé no qual os dejetos são lançados,\ne bebe água sem tratamento do poço que há na comunidade. Em relação ao possível quadro de\nverminose relatado, podemos afirmar:","options":{"A":"O quadro descrito é condizente com parasitose por Enterobius vermicularis (enterobíase ou\noxiuríase).","B":"Para podermos tratar esta criança, é necessário fazer exame de fezes seriado (3 amostras).","C":"O quadro clínico descrito é condizente com parasitose por Ancylostoma, de transmissão\noral-fecal.","D":"O tratamento prescrito para oxiuríase é metronidazol 20 mg/kq/dia 3 vezes ao dia por 5 dias."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-151877","number":"151877","sourceNumber":"151877","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual a localização mais frequente dos tumores carcinoides?","options":{"A":"Intestino Delgado.","B":"Trato respiratório.","C":"Pâncreas.","D":"Reto."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-151886","number":"151886","sourceNumber":"151886","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a doença celíaca, podemos afirmar que:","options":{"A":"São fatores de risco para doença celíaca os indivíduos com diabete melito tipo I e II, doença\nautoimune da tireoide, cirrose biliar primária, síndrome de Turner e síndrome de Down.","B":"A amamentação e o tempo de introdução do trigo na dieta podem reduzir o risco ou atrasar o\naparecimento da doença celíaca em crianças sob risco.","C":"O tratamento da doença celíaca previne a progressão da doença, porém não há remissão com\nmelhora do padrão histológico.","D":"O tratamento é realizado com corticoide, seguido de manutenção com azatioprina."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-151906","number":"151906","sourceNumber":"151906","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Escolar com 4 anos queixa-se de dor abdominal há mais de 1 mês, às vezes, apresenta\nepisódios de diarreia sem muco, pus ou sangue. Exame parasitológico com presença de Ascaris\nlumbricoides - ovos, Strongyloides - larvas e Giardia lambia - cisto. Respectivamente, qual o melhor\nesquema para tratamento?","options":{"A":"Albendazol - ivermectina - tinidazol.","B":"Tinidazol - ivermectina -albendazol.","C":"Levamizole -tinidazol -ivermectina.","D":"Ivermectina -levamizole -metronidazol."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-129742","number":"129742","sourceNumber":"129742","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O achado de leucócitos fecais em uma amostra de fezes ou de muco retal é compatível\ncom todas as causas de diarreia, EXCETO:","options":{"A":"Shigella sonnei.","B":"Giardia lamblia.","C":"Colite ulcerativa.","D":"Entamoeba histolytica."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-129739","number":"129739","sourceNumber":"129739","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"As doenças inflamatórias intestinais vêm se tornando uma preocupação entre os\nprofissionais da área da saúde, pelas\ncaracterísticas similares entre si. Porém, a doença\ninflamatória que afeta transmuralmente qualquer parte do trato gastrointestinal da boca ao ânus,\napresenta características endoscópicas caracterizada por úlceras serpiginosas e com aparência de\n\n?pedra de calçamento? caracteriza a:","options":{"A":"Retocolite ulcerativa inespecífica.","B":"Colite aguda por Shigella.","C":"Doença de Crohn.","D":"Colite amebiana."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-107868","number":"107868","sourceNumber":"107868","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No diagnóstico de diarréia aguda por Clostridium difficile, qual o melhor método\ndiagnóstico?","options":{"A":"Coprocultura.","B":"Exame parasitológico de fezes.","C":"Pesquisa de toxinas A e B nas fezes.","D":"Colonoscopia."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-103805","number":"103805","sourceNumber":"103805","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre o tratamento da doença inflamatória intestinal, é CORRETO afirmar:","options":{"A":"O corticoide é utilizado para induzir o tratamento, mas não mantê-lo.","B":"A mesalazina é a melhor medicação para tratamento da doença de Crohn.","C":"A colite ulcerativa pode acometer partes do jejuno eventualmente, por isso as medicações\nsistêmicas são melhores.","D":"O corticoide em baixa dose é bem-vindo em pacientes refratários aos derivados de\n5-aminossalicilato no tratamento em longo prazo."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-107870","number":"107870","sourceNumber":"107870","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo masculino, 58 anos, deu entrada no pronto atendimento queixando\ndor tipo cólica periumbilical que migrou\npara fossa ilíaca esquerda há cerca de 12 horas, associada\na tenesmo. Nega febre, vômitos e sintomas urinários. Refere constipação crônica, chegando a\npassar mais de 7 dias sem defecar. Seu estado geral é bom, normocorado, eupneico, afebril e\nnormotenso. Seu abdome é algo distendido, flácido, doloroso à palpação em fossa ilíaca esquerda\ncom discreta irritação peritoneal. Ruídos hidroaéreos diminuídos. Toque retal sem alterações.\n\nHemograma EAS e radiografias sem alterações. Assinale a alternativa CORRETA:","options":{"A":"Por tratar-se de provável sub-oclusão de cólon distal, o próximo passo da investigação é a\ncolonoscopia.","B":"A tomografia computadorizada é dispensável na decisão da conduta deste paciente.","C":"A conduta inicial deve ser clínica, com internação hospitalar, prescrição de antibióticos com\ncobertura para bactérias gram negativas e\nanaeróbios, avaliação complementar e observação por\n48 horas.","D":"O melhor tratamento cirúrgico para o paciente acima neste momento, caso indicado, seria a\nhemicolectomia esquerda com anastomose colorretal término-terminal."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-103784","number":"103784","sourceNumber":"103784","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Os vermes adultos de Ascaris lumbricoides habitam no:","options":{"A":"Intestino grosso.","B":"Intestino delgado.","C":"Ceco e cólon ascendente.","D":"Ceco e cólon descendente."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-81997","number":"81997","sourceNumber":"81997","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher, 20 anos, com diarreia líquida há 03 meses, com restos alimentares, quatro\nvezes ao dia, sem outros achados nas fezes.\nHá 01 mês vem apresentando dor na fossa ilíaca\ndireita e parestesia nas mãos. Perdeu 10 kg (atualmente com 65 kg) desde o início do quadro.\nParasitológicos de fezes repetidamente negativos. Sobre o caso, marque a alternativa verdadeira:","options":{"A":"O trânsito e morfologia de delgado é o mais indicado para concluir o diagnóstico, já que ele\navalia todo o jejuno e íleo.","B":"Doença celíaca é o diagnóstico mais provável e a endoscopia digestiva alta com biópsia de\nsegunda porção do duodeno, o padrão-ouro.","C":"Os sintomas devem ser devidos à doença ileal, sendo a colonoscopia o melhor exame para\nconcluir o caso.","D":"Deve ser internada para investigar neoplasia.","E":"Pela ausência de contato anterior com bacilo de Koch, a tuberculose está afastada."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-81930","number":"81930","sourceNumber":"81930","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A melhor opção para tratamento de Strongyloides stercoralis é:","options":{"A":"Ivermectina.","B":"Mebendazol.","C":"Cloranfenicol.","D":"Metronidazol.","E":"Cetoconazol."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-60884","number":"60884","sourceNumber":"60884","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo feminino, 25 anos, com diarreia líquida, 5 a 6 vezes ao dia,\nocasionalmente com sangue, iniciada há 07 meses.\nRefere perda de 07 kg no período (atualmente\ncom 56 kg). Já foi em vários médicos, mas recebeu apenas tratamento para verminose, mesmo\ncom exames negativos. Sobre o caso, é CORRETO afirmar que:","options":{"A":"Íleo terminal normal não afasta Crohn","B":"Exames radiológicos não auxiliariam no diagnóstico","C":"Colonoscopia está contraindicada pela perda ponderal","D":"Uma biópsia do cólon sem granuloma afasta doença de Crohn","E":"Uma retossigmoidoscopia mostrando inflamação no reto e sigmoide afasta doença de Crohn"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-60824","number":"60824","sourceNumber":"60824","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre colite de Crohn, todas as alternativas abaixo são corretas, EXCETO:","options":{"A":"Processo patológico é contínuo, estendendo-se do reto ao colon descendente.","B":"Apresenta característica macroscópica de pedra em pavimentação de rua (cobblestoning).","C":"Diferente da colite ulcerativa, o achado de fissura, fístula e abcessos anais é comum.","D":"Apresenta acometimento ileal em mais de 50% das vezes.","E":"Doença é transmural."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-60813","number":"60813","sourceNumber":"60813","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual o local de infecção da Taenia saginata e Taenia solium:","options":{"A":"Ceco.","B":"Cólon.","C":"Jejuno.","D":"Intestino grosso.","E":"Intestino delgado."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-60814","number":"60814","sourceNumber":"60814","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual o método diagnóstico laboratorial: estrongiloidíase?","options":{"A":"Faust.","B":"Kato-katz.","C":"Tamisação.","D":"Fita gomada.","E":"Baermann-Moraes."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-46677","number":"46677","sourceNumber":"46677","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a diarreia crônica é correto afirmar que:","options":{"A":"A doença de Crohn não é granulomatosa, enquanto a TB sim.","B":"É comum o comprometimento do ileoterminal na retocolite ulcerativa.","C":"O uso prolongado de laxantes osmóticos pode causar síndrome do intestino irritável.","D":"O anticorpo antimitocondrial é marcador da doença celíaca.","E":"A Tropheryma whippelii, além de má absorção, pode causar também febre, artralgia ou\nmanifestações neurológicas."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-46676","number":"46676","sourceNumber":"46676","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Os microrganismos multiplicam e disseminam-se lateralmente abaixo do epitélio\nintestinal, produzindo as características de ÚLCERA \"em forma de botão de camisa\". Qual o\nparasita que produz isso?","options":{"A":"Entamoeba coli.","B":"Giardia lamblia.","C":"Giardia duodenalis.","D":"Entamoeba hartmanni.","E":"Entamoeba histolytica."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-46650","number":"46650","sourceNumber":"46650","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Pré-escolar de cinco anos tem histórico de pica e exposição a filhotes de animais\ndomésticos. Os achados clínicos incluem: anemia, febre, sibilância, broncopneumonia,\nhepatomegalia, leucocitose, importante eosinofilia. O diagnóstico provável é:","options":{"A":"Toxocaríase.","B":"Histoplasmose.","C":"Giardiase.","D":"Amebiase.","E":"Brucelose."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-46646","number":"46646","sourceNumber":"46646","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Foram encontrados nas fezes de um escolar de quatro anos, trofozoitos de Giardia\nlamblia e Entamoeba histolytica. Qual o tratamento?","options":{"A":"Ivermectina.","B":"Praziquantel.","C":"Tiabendazol.","D":"Mebendazol.","E":"Metronidazol."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-34183","number":"34183","sourceNumber":"34183","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual o helminto que habita o CECO?","options":{"A":"Ancylostoma.","B":"Necator americanus.","C":"Trichuris trichiura.","D":"Ascaris lumbricoides.","E":"Strongylodes Stercoralis."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-26600","number":"26600","sourceNumber":"26600","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Enteropatia crônica, genética de fundo imunológico, em que a mucosa intestinal de\ncrianças suscetíveis é gravemente lesada por alimentos contendo glúten (trigo, centeio, cevada e\naveia) levando à má absorção. Assinale a alternativa correta:","options":{"A":"Espru tropical","B":"Doença de Whipple","C":"Doença celíaca","D":"Doença de Wolman","E":"Abetalipoproteinemia"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-26659","number":"26659","sourceNumber":"26659","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual o principal agente etiológico da colite associada a antibióticos?","options":{"A":"Clostridium difficile","B":"Cândidas","C":"Staphylococcus aureus","D":"Streptococcus do grupo A","E":"Proteus"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-294454","number":"294454","sourceNumber":"294454","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional injetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5 g/dl, ferritina: 25 ng/ml,\nvitamina D: 11 ng/dl. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, com relação às alterações\nesperadas para confirmação do diagnóstico mais provável, é CORRETO afirmar:","options":{"A":"As lesões acometem mais o íleo, mas podem ocorrer em todo o tubo digestivo.","B":"Os anticorpos são úteis para o diagnóstico, sendo a biópsia gástrica o padrão-ouro.","C":"A realização de uma colonoscopia é essencial para avaliação, pois as alterações são mais\nfrequentes no cólon.","D":"No anatomopatológico, observa-se redução da relação vilo/cripta e infiltração de linfócitos na\nmucosa."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-354384","number":"354384","sourceNumber":"354384","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma família que reside na periferia urbana recebe a visita de médico que constata que\nas crianças (menina de 8 anos e menino de 1\nano) e sua mãe estão apresentando diarreia\nesverdeada, explosiva, aquosa, fétida, com fezes em grande quantidade e com restos alimentares;\nsem febre, sendo esses episódios repetidos nos últimos seis meses. Referem cólicas e aumento do\nvolume abdominal, tendo a criança menor apresentado sintomas no dia da consulta. As crianças\npararam de beber leite pois aumentava os sintomas. Já haviam comparecido na UBS onde exames\nforam solicitados, mas não realizados. Apresentam regular estado geral, hidratados, afebris e\ncorados. O menino cursa com discreta distensão abdominal nesta data. Diante do quadro, indique o\ndiagnóstico mais provável para o caso:","options":{"A":"Giardíase.","B":"Ascaridíase.","C":"Diarreia por rotavírus.","D":"Doença celíaca."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-354385","number":"354385","sourceNumber":"354385","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma família que reside na periferia urbana recebe a visita de médico que constata que\nas crianças (menina de 8 anos e menino de 1\nano) e sua mãe estão apresentando diarreia\nesverdeada, explosiva, aquosa, fétida, com fezes em grande quantidade e com restos alimentares;\nsem febre, sendo esses episódios repetidos nos últimos seis meses. Referem cólicas e aumento do\nvolume abdominal, tendo a criança menor apresentado sintomas no dia da consulta. As crianças\npararam de beber leite pois aumentava os sintomas. Já haviam comparecido na UBS onde exames\nforam solicitados, mas não realizados. Apresentam regular estado geral, hidratados, afebris e\ncorados. O menino cursa com discreta distensão abdominal nesta data. Com base nas\ninformações, classifique a diarreia quanto ao mecanismo fisiopatológico:","options":{"A":"Funcional.","B":"Secretória.","C":"Por hipermotilidade.","D":"Por malabsorção."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-354386","number":"354386","sourceNumber":"354386","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma família que reside na periferia urbana recebe a visita de médico que constata que\nas crianças (menina de 8 anos e menino de 1\nano) e sua mãe estão apresentando diarreia\nesverdeada, explosiva, aquosa, fétida, com fezes em grande quantidade e com restos alimentares;\nsem febre, sendo esses episódios repetidos nos últimos seis meses. Referem cólicas e aumento do\nvolume abdominal, tendo a criança menor apresentado sintomas no dia da consulta. As crianças\npararam de beber leite pois aumentava os sintomas. Já haviam comparecido na UBS onde exames\nforam solicitados, mas não realizados. Apresentam regular estado geral, hidratados, afebris e\ncorados. O menino cursa com discreta distensão abdominal nesta data. Considerando o\ndiagnóstico mais provável, é importante obter informações na visita domiciliar sobre","options":{"A":"o consumo de glúten pela família.","B":"a presença de água encanada na residência.","C":"a visualização de parasitas nas fezes.","D":"as alergias alimentares na família."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-294455","number":"294455","sourceNumber":"294455","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional\ninjetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5g/dL, ferritina 25ng/mL,\nvitamina D 11ng/dL. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, Identifique o anticorpo associado\nao diagnóstico mais provável.","options":{"A":"Anticélula parietal.","B":"Antitransglutaminase tecidual.","C":"Anti-Saccharomyces cerevisae (ASCA).","D":"Anticitoplasma de neutrófilo (ANCA)."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-294456","number":"294456","sourceNumber":"294456","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher, 21 anos de idade, procura atendimento ambulatorial para investigação de\ndiarreia crônica. Faz uso de anticoncepcional injetável. Ao exame, apresenta-se em bom estado\ngeral, descorada +/4+. Realizados exames laboratoriais, com Hb: 10,5g/dL, ferritina 25ng/mL,\nvitamina D 11ng/dL. Solicitada endoscopia digestiva alta, com achado de redução do pregueado\nmucoso em segunda porção duodenal. Diante do quadro clínico, Indique a conduta terapêutica\ninicial mais adequada.","options":{"A":"Suspender o metódo contraceptivo.","B":"Adotar dieta isenta de glúten.","C":"Realizar corticoterapia.","D":"Fazer uso de Imunobiológico."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-62844","number":"62844","sourceNumber":"62844","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente, sexo feminino, 65 anos de idade, hipertensa e diabética, com história de\ninternamento há cerca de dois meses, causado por pneumonia comunitária, evolui com diarreia há\ntrês dias. Relata quatro a seis dejeções por dia com muco e sangue. Em uso regular de captopril e\ninsulina. A melhor opção terapêutica para esse quadro é:","options":{"A":"Metronidazol.","B":"Corticoide.","C":"Dieta pobre em glúten.","D":"Omeprazol.","E":"Enzima pancreática."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-34975","number":"34975","sourceNumber":"34975","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente,13 anos de idade, é internado com queixa de dor abdominal em região lombar\nhá 15 dias; iniciou com dormência e\nfraqueza muscular nos membros inferiores. Posteriormente,\ndificuldade para deambular e parada dos movimentos. Nos antecedentes pessoais, tinha hábito de\nbanhar-se em rio. Ao exame, a força muscular do tronco e membros superiores, bem como as\nsensibilidades, estavam preservadas; força muscular ausente nos membros inferiores (grau O) com\narreflexia e diminuição de sensibilidade tátil, da térmica e da álgica, compatível com nível L2.\n\nHemograma sem leucocitose, com anemia normocrômica e normocítica. O estudo do LCR revelou\n67 céls./mm³ (80% de linfócitos, 2% de\nneutrófilos), glicose de 45 mg/dl, cloretos de 766 mEq/L,\nhiperproteinorraquia (140 mg/dl), estudo bacteriológico e micológico negativos. A Ressonância\nMagnética (RNM) mostrou aspecto sugestivo de mielite transversa com extensão do processo\ninflamatório para as raízes da cauda equina. O diagnóstico mais provável é:","options":{"A":"neuroesquistossomose.","B":"poliomielite aguda.","C":"linfoma medular.","D":"intoxicação medicamentosa.","E":"meningite."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-11130","number":"11130","sourceNumber":"11130","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Dos parasitas relacionados a seguir, o que não é adquirido através da ingesta de água\nou de alimentos é:","options":{"A":"Tenia Solium.","B":"Entamoeba Histolytica.","C":"Enterobius Vermicularis.","D":"Necator Americanus.","E":"Giardia Lamblia."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-314289","number":"314289","sourceNumber":"314289","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo masculino, 22 anos de idade, proveniente do interior da Bahia com\nqueixa de diarreia aquosa, três dejeções ao dia, há dois meses, por vezes associada a esteatorréia\ne astenia. A alternativa que contém agentes infecciosos causadores de diarreia disabsortiva é","options":{"A":"Entamoeba coli e Taenia glabrata","B":"Ascaris lumbricoides e Endolimax nana","C":"Strongyloides stercoralis e Giardia lamblia","D":"Clostridioide (Clostridium) difficile e Salmonella","E":"Schistosoma mansoni e Entamoeba histolytica"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249977","number":"249977","sourceNumber":"249977","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na Doença de Crohn (DC) os pacientes com infecções ou abscessos devem receber\nantibioticoterapia apropriada com drenagem cirúrgica ou percutânea, sendo correto que:","options":{"A":"Conforme o mais apropriado, considerando as condições assistenciais do local de atendimento.","B":"Conforme o mais apropriado, independente das condições assistenciais do local de atendimento.","C":"Independentemente de ser o mais apropriado, considerando as condições assistenciais do local\nde atendimento.","D":"Conforme o menos apropriado, considerando as condições assistenciais e não do local de\natendimento."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249985","number":"249985","sourceNumber":"249985","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a terapia da doença de Crohn assinale a alternativa correta:","options":{"A":"O corticoide é útil para induzir a remissão da doença e mantê-la.","B":"A azatioprina é útil para induzir a remissão da doença e mantê-la.","C":"A azatioprina é útil para manter a remissão da doença.","D":"O corticoide é útil para manter a remissão da doença."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249986","number":"249986","sourceNumber":"249986","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A aterapia biológica com anti-TNF, infliximabe ou adalimumabe é útil na doença de\nCrohn para:","options":{"A":"Induzir a remissão da doença e mantê-la.","B":"Curar a doença.","C":"Induzir a remissão da doença sem mantê-la.","D":"Manter a remissão da doença sem induzi-la."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-215581","number":"215581","sourceNumber":"215581","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Levando-se em consideração o diagnóstico das verminoses, assinale a alternativa\nCORRETA.","options":{"A":"A giardíase é causada por um protozoário e acomete principalmente a região gástrica, causando\nfortes dores na criança.","B":"A teníase, conhecida popularmente como ?solitária?, é causada pelos cestódeos Taenia solium\ne Taenia saginata. A T. solium é adquirida pelo\nconsumo da carne de porco mal cozida e a T.\nsaginata pelo consumo da carne de boi contaminada.","C":"A esquistossomose é considerada uma doença de difícil transmissão, sendo baixo o risco de\nadquiri-la em um único contato com focos de contaminação.","D":"A Entamoeba histolytica é o agente etiológico da amebíase, parasita do intestino grosso, que\ntem a transmissão apenas através do contato sexual."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-139791","number":"139791","sourceNumber":"139791","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em crianças com doença celíaca, o tratamento dietético está baseado em:","options":{"A":"Evitar ingestão de arroz e milho.","B":"Evitar ingestão de alimentos que contenham cevada, trigo, centeio e aveia.","C":"Suspender o leite de vaca e seus produtos da alimentação habitual da criança.","D":"Evitar ingestão de alimentos que contenham cacau."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-139790","number":"139790","sourceNumber":"139790","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Criança, 2 anos de idade, apresenta quadro diarreico há 1 ano com episódios\nesporádicos de vômitos, hiporexia,\nirritabilidade, déficit de crescimento, distensão abdominal,\ndiminuição do tecido celular subcutâneo e atrofia da musculatura glútea. A mãe relata que as\nfezes são volumosas, fétidas e gordurosas. Acerca desse caso clínico, assinale a alternativa que\napresenta a PRINCIPAL hipótese diagnóstica.","options":{"A":"Doença celíaca.","B":"Má rotação intestinal.","C":"Megacólon congênito.","D":"Giardíase."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111820","number":"111820","sourceNumber":"111820","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A indicação de nutrição parenteral nos pacientes portadores da síndrome do intestino\ncurto, secundária às ressecções extensas do\nintestino delgado, é:","options":{"A":"relativa.","B":"prioritária.","C":"irrelevante.","D":"indiferente."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111849","number":"111849","sourceNumber":"111849","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Tumores carcinoides são uns dos tumores endócrinos mais comuns do trato\ngastrodigestivo. Qual é a sua PRINCIPAL localização primária?","options":{"A":"Apêndice e íleo terminal.","B":"Duodeno e íleo terminal.","C":"Íleo terminal e pâncreas.","D":"Apêndice e duodeno."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-259739","number":"259739","sourceNumber":"259739","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 3 anos é atendido no ambulatório com quadro de diarreia crônica,\nacompanhada de distensão abdominal, perda de\npeso, inapetência, alteração de humor com\nirritabilidade e vômitos esporádicos. O paciente também se apresentava emagrecido, com\ndiminuição do tecido celular subcutâneo e atrofia da musculatura glútea. Mãe trouxe um\nhemograma que apresentava anemia. Dentre as opções a seguir, a conduta mais adequada para a\nconfirmação diagnóstica dessa criança e o tratamento indicado é:","options":{"A":"A pesquisa de anticorpos IgE específicos para o leite de vaca, teste de puntura ou prick test e\ndieta de exclusão de proteína do leite de vaca.","B":"A pesquisa de anticorpos IgG específicos para o leite de vaca, teste de puntura ou prick test e\ndieta de exclusão de proteína do leite de vaca.","C":"Anticorpo Antitransglutaminase IgA (AAT)/histopatológico da biópsia de intestino delgado, se\nanticorpo ATT positivo, e dieta de exclusão de glúten.","D":"Anticorpo Antigliadina Deaminada (AAGD)/tipagem HLA-DQ2 e DQ8, se anticorpo AAGD\npositivo, e dieta de exclusão de glúten e contaminantes."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-350867","number":"350867","sourceNumber":"350867","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma paciente de 37 anos é submetida a ressecção extensa de intestino: dois terços\ndistais do delgado e ressecção do colon\nascendente, devido a vasculite lúpica com isquemia\naguda. Ao final da cirurgia, restaram 1,2 metros de delgado proximal e cólon a partir do ângulo\nhepático. Uma anastomose entre delgado e cólon é realizada. porém a paciente estará com\nintestino bastante encurtado. Qual a principal deficiência alimentar esperada para essa paciente?","options":{"A":"Anemia megaloblástica.","B":"Distúrbio eletrolítico.","C":"Deficiência proteica.","D":"Desidratação."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-350860","number":"350860","sourceNumber":"350860","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 35 anos, previamente saudável, compareceu à consulta com história de 3\nmeses de episódios de rubor facial intermitente que se tornou mais frequente e intenso no último\nmês, e ainda associado a diarreia profusa. Ao exame: intensa hiperemia facial e tronco superior.\nPA: 110x50mmHg, sem história de hipertensão. Uma ultrassonografia do abdome identificou\ndiversos nódulos hepáticos. Qual exame deve ser solicitado para confirmação diagnóstica?","options":{"A":"Gastrina sérica.","B":"Cortisol sérico e urinário.","C":"Metanefrinas sérica e urinária.","D":"5 hidroxiindolacético urinário."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-350852","number":"350852","sourceNumber":"350852","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Pré-escolar, sexo feminino, 4 anos, é levada à Unidade Básica de Saúde devido à\nqueixa de secreção vaginal esbranquiçada há 5 dias associada a prurido intenso, principalmente\nnoturno, que faz a criança despertar. Seu irmão mais velho teve sintoma de prurido anal há 1\nsemana, tendo cedido após tratamento medicamentoso. Exame físico: presença de hiperemia\nvulvar. Dentre as seguintes alternativas, qual é o tratamento mais adequado nesse caso?","options":{"A":"Levamizol.","B":"Tiabendazol.","C":"Metronidazol.","D":"Pamoato de pirvínio."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-350820","number":"350820","sourceNumber":"350820","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um adolescente de 13 anos de idade vem ao ambulatório com queixas de longa\nduração de diarreia, dor abdominal e perda de\npeso. Em consulta anterior, o médico comentou a\nparada no crescimento e a presença de anemia. Também apresenta picos febris e lesões de pele.\nNão há sangue nas fezes nem sangramento retal. Qual a principal hipótese diagnóstica?","options":{"A":"Colite ulcerativa.","B":"Doença de Crohn.","C":"Alergia Alimentar Múltipla.","D":"Distúrbios funcionais de defecação."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-321322","number":"321322","sourceNumber":"321322","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No ambulatório, a mãe de uma criança de 3 anos de idade revela que seu filho vem\napresentando diarreia crônica, às vezes com sangue, dor abdominal inespecífica. Um hemograma\nrecente revelou anemia ferropriva. Em duas ocasiões, esteve na Emergência e foi diagnosticado\ncom prolapso retal. Qual a hipótese diagnóstica mais provável?","options":{"A":"Tricuríase.","B":"Giardíase.","C":"Amebíase.","D":"Ancilostomíase."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-292837","number":"292837","sourceNumber":"292837","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um rapaz de 16 anos que vive numa favela com precárias condições, sem instalações\nsanitárias, é atendido na unidade básica de saúde. Seus pais relatam um episódio de crise\nconvulsiva sem outros sintomas. Negam casos de epilepsia na família. Qual das opções a seguir\napresenta o diagnóstico mais provável e compatível com esse caso?","options":{"A":"Neurocisticercose.","B":"Abscesso cerebral.","C":"Encefalite aguda.","D":"Meningite bacteriana."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-234006","number":"234006","sourceNumber":"234006","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente, sexo masculino, 30 anos, acompanhado em ambulato?rio especializado em\ndoenc?a inflamato?ria intestinal por doenc?a de\nCrohn, com diagno?stico ha? 10 anos e em uso de\nimunobiolo?gico. Submetido a duas cirurgias pre?vias com enterectomias. Chegou ao\n\npronto-socorro com queixa de distensa?o e dor abdominal em co?lica, vo?mitos amarelados e\ndiminuic?a?o da eliminac?a?o de flatos. Foi passada uma sonda nasoga?strica descompressiva e\nreferido a um servic?o tercia?rio. Foi institui?do tratamento cli?nico e solicitada entero\ntomografia\nque evidenciou mu?ltiplas estenoses curtas (< 10 cm) sugestivas de fibrose cro?nica em\nsegmentos de intestino delgado, sem alterac?o?es no co?lon. Mediante melhora apenas parcial\ndos sintomas, foi solicitada avaliac?a?o ciru?rgica. Com base na situac?a?o cli?nica exposta, qual\na estrate?gia ciru?rgica ideal?","options":{"A":"Realizar plastias das estenoses (estenoplastias ou estricturoplastias).","B":"Realizar cirurgia para derivac?a?o interna (\"by-pass\" i?leo transverso).","C":"Ressecar as estenoses com margem livre de doenc?a e anastomosar.","D":"Ressecar as estenoses sem margem livre de doenc?a e anastomosar."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-199823","number":"199823","sourceNumber":"199823","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um homem de 29 anos apresenta diarreia com fezes pastosas misturadas com sangue\nvivo, 4?5 vezes ao dia, há dois anos. No\ninício do quadro, realizou colonoscopia com biópsias do\nsigmoide que mostrou infiltrado misto difuso, linfoplasmocitose basal, atrofia e irregularidade de\ncriptas, e erosões superficiais. Há 6 meses, iniciou dor lombar persistente, que o desperta do sono,\npiora ao acordar, e que melhora 2 horas após iniciar suas atividades. Apresenta hematócrito de\n32%, hemoglobina de 10,5 g/dl, proteína C-reativa elevada, antígeno HLA-B27 reagente.\n\nRessonância magnética mostra sinais de inflamação sacroilíacas intra-articular com edema\nimportante da medula óssea justa-articular.\nQual tratamento medicamentoso traz mais benefício\npara este doente?","options":{"A":"Budesonida oral.","B":"Infliximabe e azatioprina.","C":"Mesalazina e tacrolimus.","D":"Sulfassalazina e prednisona."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-172944","number":"172944","sourceNumber":"172944","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma mulher de 25 anos apresenta diarreia aquosa, sem sangue e sem gordura, 5 a 6\nvezes ao dia, há 5 semanas. Refere\ndistensão abdominal e piora da diarreia após a ingestão de\npizza, queijo, leite, suco de maçã. Nega febre e relata perda ponderal de 6 kg no período da\ndoença (peso habitual = 67 kg). Faz uso de fluoxetina 20 mg/dia. Foi colecistectomizada há 4\nmeses e tem diagnóstico de fibromialgia. A avaliação ginecológica é normal. Traz os seguintes\nexames: hematócrito, hemoglobina e glicemia de jejum normais, VHS = 60 mm (VR = até 16 mm);\nferritina = 10 µg/L (VR = 10-150 µg/L); vitamina B12 = 86 pmol/L (VR = 206-735 pmol/L); vitamina D\n\n= 27 pmol/L (VR = 36-180 pmol/L). O exame físico é normal. Legenda: VR = valor de referência.\nVHS = velocidade de hemossedimentação. O seu\nobjetivo é chegar a um diagnóstico mais\nprovável. Qual dos procedimentos a seguir é o mais eficaz neste momento?","options":{"A":"Colonoscopia.","B":"Antitransglutaminase IgA.","C":"Teste de tolerância a lactose.","D":"Pesquisa de toxina para Clostridium difficile."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-150868","number":"150868","sourceNumber":"150868","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher, 30 anos, com história de episódios frequentes de diarreia com sangue,\nevoluindo com astenia, dor abdominal em\ncólica localizada na fossa ilíaca direita e febre diária há 2\nmeses, não tendo sido essa aferida por termômetro. Tem bom nível socioeconômico e ingere água\nfiltrada. Procurou o ambulatório de gastroenterologia para acompanhamento, tendo sido detectada\numa massa na região da fossa ilíaca direita. Realizou colonoscopia que mostrou uma colite erosiva\nsegmentar de sigmoide, não sendo possível avaliar o íleo terminal. A biópsia do cólon foi\ncompatível com colite crônica inespecífica e a pesquisa de anticorpo contra Saccharomyces\ncerevisiae foi negativa. O diagnóstico mais provável para o caso acima é colite associada a:","options":{"A":"Retocolite ulcerativa.","B":"Infecção bacteriana.","C":"Infecção por ameba.","D":"Doença de Crohn."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-126999","number":"126999","sourceNumber":"126999","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Você é chamado para avaliar idoso que está em observação na emergência com\nquadro de diarreia há 48h. Seu peso é 50 kg\ne tem antecedentes de hipertensão arterial sistêmica e\netilismo. No momento, ele queixa-se de sede. Nas últimas 6h, seu débito urinário foi de 100 ml. Ao\nexame físico, é emagrecido, tem mucosas secas, frequência cardíaca de 108 bpm e pressão\narterial de 110 x 60 mmHg. Avaliação laboratorial mostrou ureia de 40 mg/dl, creatinina de 1,0\nmg/dl, potássio de 3,0 mEq/L, tempo de protrombina 40% e albumina 2,5 g/dl. Qual dos itens\nabaixo contém o melhor fluido para ser administrado por via endovenosa, no momento atual desse\npaciente?","options":{"A":"Albumina.","B":"Hidroxietilamido.","C":"Solução de Ringer lactato.","D":"Plasma fresco congelado."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-126930","number":"126930","sourceNumber":"126930","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher de 35 anos refere que há 2 anos apresenta diarreia líquida, dor abdominal na\nfossa ilíaca direita, associada à perda de peso de 10%. Procurou atendimento médico sendo\norientada a utilizar antiespasmódicos para dor e retirar o leite da dieta. Informa que mesmo\ncom essas medidas apresentou apenas melhora parcial. Ao exame físico, apresentava dor à\npalpação profunda na fossa ilíaca direita. Os exames mostraram uma anemia leve hipocrômica,\nmicrocítica, pesquisa positiva de hemoglobina nas fezes e pesquisa de anticorpos antiendomísio\nnegativa (IgA e IgG). Com o quadro, foi solicitada colonoscopia que mostrou úlceras\nserpiginosas no íleo terminal e um enantema discreto no reto, com a biópsia evidenciando\nileíte e retite crônica inespecífica, sem granulomas. Qual o diagnóstico mais compatível com o\nquadro?","options":{"A":"Doença celíaca.","B":"Doença de Crohn.","C":"Retocolite ulcerativa.","D":"Intolerância à lactose."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-126959","number":"126959","sourceNumber":"126959","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Menina de 6 anos comparece à Unidade Básica de Saúde por apresentar\nquadros de diarreia alternados com períodos\nde eliminação de fezes normais ou ressecadas. Os\npais referem também episódios de dor e leve distensão abdominal, perda de peso e eventualmente\nfezes gordurosas e com restos alimentares. Esse quadro clínico é fortemente sugestivo de qual\nparasita intestinal?","options":{"A":"Giardia lamblia.","B":"Ascaris lumbricoides.","C":"Entamoeba histolytica.","D":"Strongyloides stercoralis."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-102135","number":"102135","sourceNumber":"102135","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente feminina, 48 anos, procurou um gastroenterologista com queixas de diarreia,\ndor abdominal em cólicas, além de rubor facial e\nsudorese. Refere que suas queixas se iniciaram\nhá mais de um ano, de forma leve, com os sintomas se intensificando progressivamente. O\nprofissional investigou as causas mais comuns de diarreia, inclusive realizou ileocolonoscopia e\nesofagogastroduodenoscopia que foram normais. Mas desde o atendimento inicial que o\nprofissional tinha em mente a possibilidade de tratar-se de síndrome carcinoide, principalmente\npelas queixas de associação da diarreia ao rubor facial. Diante dessa possibilidade, qual a conduta\nmais adequada na busca da confirmação diagnóstica e qual o tratamento mais indicado?","options":{"A":"Pesquisa na urina do 5-HIA (ácido 5-hidroxiindolacético), ultrassonografia abdominal total e\napendicectomia se o tumor for de base apendicular independente do tamanho.","B":"Pesquisa na urina do 5-HIAA (ácido 5-hidroxiindolacético), dosagem no sangue do 5-HT\n\n(5-hidroxitriptamina), enteróclise e apendicectomia para tumores até 1,5 cm da ponta apendicular.","C":"Pesquisa na urina do 5-HIAA (ácido 5-hidroxiindolacético), dosagem no sangue do 5-HT\n\n(5-hidroxitriptamina), tomografia computadorizada do abdome, colectomia direita se o tumor for de\nbase apendicular com 2 cm de diâmetro.","D":"Pesquisa na urina do 5-HIAA (ácido 5-hidroxiindolacético), dosagem no sangue do 5-HT\n\n(5-hidroxitriptamina), enteróclise, cintilografia para receptor \"in vivo? com octreotida marcado com\niodo 131 e colectomia direita para tumor de 2 cm na base apendicular."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-102170","number":"102170","sourceNumber":"102170","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente, 50 anos, epiléptico, há um mês em tratamento hospitalar por abscesso\npulmonar. Evoluiu com febre, dor abdominal e\ndiarreia aquosa, fétida, cerca de 10 evacuações por\ndia, sem sangue ou muco, que perdurou por três dias. Passou então a apresentar distensão\nabdominal, queda do estado geral e toxemia. Houve piora do leucograma que chegou a\n20.000/mm³. Nesse contexto, o achado laboratorial mais adequado para confirmar a principal\nhipótese diagnóstica é:","options":{"A":"Teste de lactoferrina em amostra fecal.","B":"Teste de citotoxina em coprocultura.","C":"Pesquisa de trofozoítos em amostra fecal.","D":"Pesquisa de leucócitos em amostra fecal."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-102160","number":"102160","sourceNumber":"102160","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma criança de seis anos de idade, com retardo mental, apresenta diarreia, dor\nabdominal epigástrica de forte intensidade e flatulência. Há uma semana apresenta rash\neritematopapular pruriginoso e sintomas asmatiformes. Qual a parasitose mais provável e o\ntratamento correspondente associado a esse quadro?","options":{"A":"Amebíase; etofamida.","B":"Ancilostomíase; albendazol.","C":"Esquistossomose; praziquantel.","D":"Estrongiloidíase; ivermectina."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-81233","number":"81233","sourceNumber":"81233","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma criança de 3 anos de idade vem apresentando episódios semanais de diarreia\nlíquida, associados à perda de peso, distensão\nabdominal e esteatorreia. Não há geofagia. Ao\nexame físico, a criança está eutrófica e com bom estado geral e não apresenta evidências de\nalterações em nenhum outro sistema orgânico. Investigação clínica revela ausência de sinais de\nalerta para imunodeficiência primária. Qual a principal hipótese diagnóstica?","options":{"A":"Giardíase.","B":"Amebíase.","C":"Ancilostomíase.","D":"Estrongiloidíase."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-65701","number":"65701","sourceNumber":"65701","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 61 anos, sexo feminino, comparece à Unidade Básica de Saúde com\nqueixa de diarreia recorrente iniciada há 2 anos. Refere 3 a 4 evacuações ao dia, sem sangue,\npós-prandial, alternando com períodos de evacuações normais. Nega perda de peso. Refere\n\ncólicas abdominais difusas que aliviam com a evacuação. A diarreia não se associa com a ingestão\nde leite ou derivados. Refere antecedente de\nconstipação crônica na infância. Aposentou-se\nrecentemente. Exame físico normal. O médico de família solicitou exames que revelaram\nhematócrito 42%, hemoglobina 14 g/dl, VHS 15 mm/h, PCR 0,05 mg/dl, TSH 2,3 µU/ml, albumina\n4,0 g/dl, hemoglobina glicada 5%, parasitológico de fezes negativo para protozoários e helmintos,\npesquisa de leucócitos nas fezes negativa. Ileocolonoscopia normal. US de abdome normal. Qual o\nmelhor diagnóstico?","options":{"A":"Intestino irritável.","B":"Colopatia diabética.","C":"Dispepsia funcional.","D":"Intolerância à lactose.","E":"Síndrome mal absortiva."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-51184","number":"51184","sourceNumber":"51184","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher de 37 anos procurou emergência médica por dor intensa, em cólica, no\nquadrante inferior esquerdo do abdome há dois\ndias. As fezes eram fluidas e com muco, 2 a 4\nvezes ao dia. Esses sintomas eram recorrentes, 2 a 3 vezes ao mês, há 18 meses, piorando no\nperíodo menstrual e por ocasião da ingestão de certos alimentos, como queijo, massas ou frituras.\nUsa enalapril e fluoxetina. Exames: hematócrito 37%, hemoglobina 12 g/dl, VHS 10 mm,\nretossigmoidoscopia: normal. Histologia do sigmoide: infiltrado linfomononuclear leve. Qual o\ndiagnóstico mais provável?","options":{"A":"Colite microscópica.","B":"Intolerância à lactose.","C":"Síndrome do intestino irritável.","D":"Retocolite ulcerativa idiopática."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-51200","number":"51200","sourceNumber":"51200","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 55 anos, com flatulência e diarreia intermitente há 20 anos, relata piora há 5\nanos. Nega perda de peso. Antitransglutaminase tecidual normal, biópsia do duodeno distal:\ninfiltrado linfomononuclear, com vilosidades e criptas preservadas. Hematócrito 45%, glicemia 92\nmg/dl. Colonoscopia normal. Parasitológicos e sorologia para Giardia negativos. Glicemia 86 mg/dl.\nTem dieta rica em leguminosas, frutas, lacticínios e cereais ricos em fibras. Que deficiência melhor\nexplica este quadro?","options":{"A":"Amilase pancreática e salivar.","B":"Imunoglobulina A tecidual.","C":"Dissacaridase na borda em escova intestinal.","D":"Transportador de membrana GLUT-5 da frutose."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-51240","number":"51240","sourceNumber":"51240","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher de 32 anos queixa-se de dor no quadrante inferior esquerdo do abdome, uma\nvez por semana, há 4 meses, associada a\nfezes liquefeitas, sem sangue. Melhora com a\nevacuação e piora no período menstrual. Usou amoxicilina há duas semanas para faringite. Está\ndesempregada há 8 meses. Exames: Hematócrito 37%, hemoglobina 12 g/dl, VHS 5 mm,\nleucócitos 7.000/mm³, hormônios tireoidianos normais, glicemia de jejum 86 mg/dl.\n\nRetossigmoidoscopia sem lesões. Dentre as alternativas abaixo, qual o mecanismo fisiopatológico\nque melhor e mais frequentemente explica esta\ncondição clínica?","options":{"A":"Implante endometrial no sigmoide.","B":"Distúrbio da modulação central da dor.","C":"Disabsorção de carboidratos por giardíase.","D":"Colite pseudomembranosa por Clostridium difficile."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-32515","number":"32515","sourceNumber":"32515","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um pré-escolar, de 4 anos, desnutrido grau II, é trazido ao hospital com tosse seca,\nirritativa intensa e dificuldade respiratória.\nAo exame, encontrava-se subfebril e com sibilos difusos.\nHá 3 dias realizou radiografia de tórax que evidenciou uma condensação reticulonodular em terço\nmédio direito. A radiografia atual mostra imagem semelhante em ápice esquerdo. O diagnóstico\nmais provável é:","options":{"A":"Pneumonia viral.","B":"Pneumonia bacteriana.","C":"Síndrome de Löeffler.","D":"Pneumonia por Pneumocystis carinii.","E":"Pneumonia por Mycoplasma pneumoniae."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-37418","number":"37418","sourceNumber":"37418","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um jovem de 19 anos com história de diarreia há cerca de 3 anos, perda de peso e\ncrises de dor abdominal recorrente apresenta?se na emergência com um quadro sugestivo de\napendicite aguda. O cirurgião de plantão indica e realiza uma apendicectomia nesse jovem e ele\nevolui com abscesso intracavitário e fístula colocutânea. A fístula era de baixo débito e o trânsito\nintestinal era pérveo, foi indicada conduta conservadora com dieta pobre em fibras e observação\nambulatorial por oito semanas. O laudo histopatológico revelou a presença de inflamação\ntransmural e de granulomas sarcoides. Com base nos fatos descritos acima, assinale a alternativa\nmais correta.","options":{"A":"A presença de infecção crônica granulomatosa sugere diagnóstico de tuberculose intestinal.","B":"A presença de infecção crônica com granulomas\nsarcoides sugere diagnóstico de sarcoidose.","C":"Diante do não fechamento da fístula com o tratamento clínico proposto, o próximo passo é\nindicar a nutrição parenteral total.","D":"Diante do não fechamento da fístula com o tratamento clínico proposto, o próximo passo é\nindicar a terapêutica cirúrgica.","E":"O tratamento clínico deveria incluir o uso de anticorpos monoclonais anti-TNF e corticoides."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-22955","number":"22955","sourceNumber":"22955","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação à colite de Crohn e a colite ulcerativa, escolha a opção correta.","options":{"A":"Fissura, fístula e abscesso anal são comuns na colite ulcerativa","B":"O sangramento retal é mais frequente na colite ulcerativa","C":"Colite ulcerativa geralmente poupa o reto","D":"A diarreia só acontece na colite de Crohn","E":"O íleo terminal quase na totalidade das vezes está acometido na colite ulcerativa"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-27734","number":"27734","sourceNumber":"27734","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher 28 anos, com queixa de episódios de dor tipo cólica, na metade inferior do\nabdome, que melhora com a defecação. Refere ainda alternância de fezes pouco consistentes,\ncom aumento do intervalo entre as evacuações e sensação de plenitude retal após a defecção.\nNega uso de medicamentos. A principal hipótese diagnóstica a ser considerada é:","options":{"A":"neoplasia colorretal","B":"hipotereoidismo","C":"distúrbio psiquiátrico","D":"síndrome do intestino irritável","E":"doença inflamatória intestinal"},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-24321","number":"24321","sourceNumber":"24321","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Edgarzinho, 3 anos, e seu pai, Sr. Edgar, comeram um hambúrguer em um restaurante\ncom baixo padrão de higiene. Posteriormente, o\ngaroto iniciou quadro agudo de cólica, febre baixa,\ndiarreia aquosa, a qual, em seguida, tornou-se sanguinolenta. Seu pai apresentou sintomas\nsemelhantes. A criança evoluiu com diminuição da diurese e palidez acentuada, enquanto Sr.\n\nEdgar fez um quadro de púrpura trombocitopênica trombótica. Por favor, marque a opção com o\nprovável agente etiológico da patologia manifestada pelos dois pacientes.","options":{"A":"Rotavírus.","B":"Giárdia lamblia.","C":"E. coli entero-hemorrágica.","D":"Salmonela typhi."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-27759","number":"27759","sourceNumber":"27759","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação à colite de Crohn e a colite ulcerativa, identifique a opção correta.","options":{"A":"O sangramento retal ocorre quase sempre na colite ulcerativa.","B":"O acometimento do íleo é usual na colite ulcerativa.","C":"Fissura, fístula, abscessos anais são os primeiros achados na colite ulcerativa.","D":"A diarreia só ocorre na colite de Crohn.","E":"A ulceração na mucosa colônica é mais profunda na colite ulcerativa."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-25380","number":"25380","sourceNumber":"25380","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Lactente, 1 ano e 6 meses de idade, apresenta diarreia sanguinolenta há 6 dias.\nEvolutivamente passa a apresentar palidez,\nicterícia leve e petéquias, oligúria e hipertensão arterial.\nOs exames revelam anemia com presença de esquizócitos no esfregaço sanguíneo,\ntrombocitopenia e hematúria. O agente etiológico mais comumente envolvido na gênese desse\nquadro é:","options":{"A":"Adenovírus","B":"E. histolytica","C":"E. coli O157:H7","D":"Y.enterocolitica","E":"S. typhi"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-25362","number":"25362","sourceNumber":"25362","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 23 anos procura atendimento por lesões cutâneas compatíveis com\ndermatite herpetiforme. Avaliação laboratorial\nevidenciou hemoglobina de 9 g/dL, VCM = 67 fL.\nSem outros achados alterados. Dos exames abaixo, selecione o melhor teste inicial para a provável\npatologia deste paciente:","options":{"A":"Pesquisa de anticorpo antigliadina","B":"PCR para Herpes vírus","C":"PCR para Varicela-zóster vírus","D":"Pesquisa de anticorpo IgA antitransglutaminase","E":"Pesquisa de anticorpo IgG antiendomísio"},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-9046","number":"9046","sourceNumber":"9046","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Narinha, 3 anos, encontrava-se apresentando prurido anal e presença de Enterobius\nvermicularis ao exame. Já havia feito uso de mebendazol. Seu médico poderia medicá-la com:","options":{"A":"Enxofre a 5%","B":"Pamoato de Pirvínio","C":"Sulfametoxazol + trimetoprim","D":"Deltametrina"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-6942","number":"6942","sourceNumber":"6942","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O desenho abaixo ilustra a representação de doença que afeta a mucosa do intestino\ndelgado. São alimentos proibidos nessa doença, EXCETO: (VER IMAGEM)","options":{"A":"Aveia.","B":"Trigo.","C":"Cevada.","D":"Centeio.","E":"Polvilho."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-322127","number":"322127","sourceNumber":"322127","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa correta quanto às características das doenças inflamatórias\nintestinais ? doença de Crohn e retocolite\nulcerativa.","options":{"A":"A retocolite ulcerativa tem sua maior incidência em pacientes de 50 anos.","B":"A retocolite ulcerativa é uma doença que geralmente acomete mucosa, submucosa e muscular\ndo cólon.","C":"A retocolite ulcerativa pode estar associada a manifestações extraintestinais, como a colangite\nesclerosante, e geralmente é agravada pelo tabagismo.","D":"Tanto a retocolite ulcerativa como a doença de Crohn são mais comuns entre mulheres que\nusam contraceptivos orais em comparação com aquelas\nque não usam.","E":"O tabagismo atua como efeito protetor na doença de Crohn."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-343460","number":"343460","sourceNumber":"343460","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A giardíase e a amebíase são doenças causadas por protozoários e que possuem a\nseguinte característica em comum:","options":{"A":"São doenças que podem ser prevenidas através de vacinação.","B":"São doenças transmitidas pela via fecal-oral.","C":"São doenças de notificação compulsória nacional.","D":"São doenças incuráveis e de difícil prevenção."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-349749","number":"349749","sourceNumber":"349749","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre doença de Crohn e colite ulcerativa, informe se é verdadeiro (V) ou falso (F) o\nque se afirma a seguir e assinale a\nalternativa com a sequência correta. ( ) O tabagismo parece\nconferir um efeito protetor na colite ulcerativa. ( ) A lesão mais característica da colite\nulcerativa é o\nabscesso das criptas de Lieberkühn. ( ) Uma característica histológica importante da doença de\nCrohn é o granuloma não caseoso, um agregado de histiócitos epitelioides circundados por\nneutrófilos e células gigantes. ( ) O paciente com doença de Crohn pode desenvolver fístulas entre\no intestino e qualquer outro órgão intra-abdominal, a maioria delas envolve o intestino delgado.","options":{"A":"V - V - F - V.","B":"F - V - F - V.","C":"V - V - V - V.","D":"V - V - F - F","E":"F - V - V - F."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-365582","number":"365582","sourceNumber":"365582","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A presença de eosinofilia no hemograma pode ter inúmeras causas, mas, em geral,\nchama a atenção para doenças alérgicas e parasitoses. Entretanto, em algumas parasitoses\nintestinais, a eosinofilia no sangue periférico é incomum, como, por exemplo, na","options":{"A":"toxocaríase.","B":"estrongiloidíase.","C":"enteroblase.","D":"ancilostomíase."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-284302","number":"284302","sourceNumber":"284302","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma menina de quatro anos de idade, que mora na área rural, foi levada à consulta\ncom o médico de família, por apresentar dor\nabdominal, tosse expectorativa e falta de ar há cerca\nde uma semana. Ao exame físico, o médico observou lesão cutânea serpiginosa eritematocrostosa\nno pé direito, em fase de cicatrização. A mãe informou que a lesão aparecera há,\naproximadamente, quinze dias e era muito pruriginosa. O médico perguntou sobre os hábitos da\npaciente e sobre o ambiente e a mãe informou que a criança tinha o costume de brincar descalça\nao ar livre e que a moradia carecia de instalação sanitária. O hemograma solicitado demonstrou\neosinófilos de 18%. Com base nesse caso hipotético, julgue o item a seguir. A estrongiloidíase é o\ndiagnóstico mais provável.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-274395","number":"274395","sourceNumber":"274395","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"As parasitoses intestinais costumam ser oligossintomáticas ou, até mesmo,\nsintomáticas. Entretanto há sinais clínicos mais\nespecíficos que ajudam a direcionar para um ou\noutro agente etiológico. Referente ao tema, informe se é Verdadeiro (V) ou Falso (F) o que se\nafirma a seguir e assinale a alternativa com a sequência CORRETA. ( ) Tricuríase está relacionada\ncom prolapso retal. ( ) Anemia importante por expoliação aumenta a suspeita para estrongiloidíase\ne tricuríase. ( ) Em pacientes imunossuprimidos, pode haver disseminação séptica da\nestrongiloidíase. ( ) Teníases, em geral, estão relacionadas com o sintoma de tenesmo. ( )\nSíndrome de Loeffler ocorre mais comumente na tricuríase.","options":{"A":"V ? F ? V ? V ? F.","B":"V ? V ? F ? V ? V.","C":"V ? F ? V ? F ? F.","D":"F ? V ? V ? F ? F.","E":"F ? F ? F ? F ? V."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-212012","number":"212012","sourceNumber":"212012","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em uma visita rural domiciliar, a mãe se queixou ao médico de família que a respectiva\nfilha de 5 anos de idade estava muito\ndesanimada, pálida, sem apetite, com pernas um pouco\ninchadas e com hábito de comer terra. Ao exame físico, o médico observou edema frouxo de MMII,\npalidez 3+/4+, abdome globoso e presença de sopro protossistólico à ausculta. A mãe referiu ainda\nque, há cerca de dois meses, a criança apresentou tosse e chiado no peito por uma semana. O\nhistórico pessoal e familiar é negativo para asma. No que tange a esse caso clínico, assinale a\nalternativa correta.","options":{"A":"A hipótese diagnóstica mais adequada ao caso é a enterobíase, que se relaciona com anemia\nem razão da espoliação sanguínea que causa.","B":"A giardíase é uma hipótese diagnóstica para o caso, pois pode desencadear tosse e chiado no\npeito quando migra pelos pulmões.","C":"Considerando os sinais e sintomas apresentados, a hipótese diagnóstica mais adequada é a\ninfestação por Entamoeba coli.","D":"A palidez associada à falta de apetite leva à hipótese de oxiuríase.","E":"A ancilostomíase é uma importante hipótese diagnóstica nesse caso, por ser causada pelo\nparasita que mais provoca espoliação\nsanguínea, além de fazer migração pelos pulmões em sua\nfase larvária."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-154319","number":"154319","sourceNumber":"154319","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente, 32 anos de idade, apresenta quadro de diarreia intensa há três dias, sem\nmelhora com hidratação intensa prescrita em consulta médica no serviço de atendimento de\nemergência, próximo à respectiva casa. Refere uso de antibiótico há 30 dias em internação\npregressa, porém relata também apresentar outros episódios de diarreia em ocasião distinta,\nquanto havia sido despedida do emprego anterior. Como antecedente de tratamento em\nandamento, atualmente faz uso de ansiolítico especifico. Mediante esse quadro, o médico levanta\nas hipóteses de doença intestinal inflamatória e de colite pseudomembranosa. Com relação a esse\ncaso clínico, assinale a alternativa correta:","options":{"A":"Se constatada a doença pseudomembranosa, a hipótese de doença intestinal inflamatória\ndeverá ser momentaneamente descartada, em razão\ndo critério de Roma IIIA.","B":"A presença de toxina A ou B confirma o diagnóstico de doença intestinal inflamatória.","C":"Os antidiarreicos estão proscritos na doença intestinal inflamatória.","D":"Pseudomembranosa são encontradas em 70% das endoscopias de casos de colite\npseudomembranosa.","E":"O uso de ansiolíticos permite a fisiopatogenia da colite pseudomembranosa."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-131824","number":"131824","sourceNumber":"131824","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Acerca dos cuidados com determinado paciente que apresenta sintomas de diarreia,\nassinale a alternativa correta.","options":{"A":"A diarreia causada pela Salmonella é de origem osmótica.","B":"O fecaloma pode causar diarreia aparente, uma vez que apenas os líquidos conseguem passar\npela obstrução parcial do reto.","C":"Exames de sangue são dispensáveis, mesmo quando se tratar de diarreia persistente.","D":"Febre e hipersensibilidade à palpação no exame físico confirmam uma causa viral do sintoma.","E":"O teste de Schilling deve ser feito para detectar se a causa do sintoma é a má absorção de\ncarboidratos."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-135086","number":"135086","sourceNumber":"135086","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Acerca dos gastrinomas, julgue o item que se segue. Os gastrinomas, também\nchamados de apudomas, estão relacionados ao\naumento da produção de gastrina, podendo ser\nlocalizados, em sua maioria, na submucosa do duodeno, menos frequentemente, no pâncreas e,\nraramente, no antro gástrico e ovário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-135092","number":"135092","sourceNumber":"135092","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No que se refere ao câncer de esôfago, cirrose e doença de Crohn, julgue o item\nsubsecutivo: são indicações para o tratamento cirúrgico da doença de Crohn falha no tratamento\nclínico, perfuração, obstrução, processo inflamatório com perfuração bloqueada do intestino\ndelgado, hemorragia intestinal refratária e neoplasia intestinal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-134965","number":"134965","sourceNumber":"134965","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A respeito de doenças infectocontagiosas, julgue o item a seguir. Bactéria causadora\nda parasitose amebíase, a Entamoeba histolítica\npode infectar indivíduos de qualquer sexo e idade.\nSeu ciclo de vida se inicia com a ingesta de cistos por meio de água ou de alimentos contaminados\ncom fezes. Esse parasita sobrevive à luz do intestino delgado, mas pode invadir os tecidos e\ndisseminar-se.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-105577","number":"105577","sourceNumber":"105577","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa que apresenta o agente causador e os sintomas da colite\ndisentérica aguda.","options":{"A":"Entamoeba histolytica: dor abdominal, diarreia com fezes líquidas contendo sangue e muco, às\nvezes tenesmo e febre ausente ou baixa.","B":"Giardíase: dor abdominal e diarreia com fezes líquidas com muco e sem sangue, às vezes\ntenesmo e febre ausente ou baixa.","C":"Escherichia coli enteropatogênica: dor abdominal e diarreia com fezes líquidas contendo muco e\nsangue e febre ausente ou baixa.","D":"Ancilostomíase: diarreia com muco, dores abdominais, febre baixa e vômitos.","E":"Estrongiloidíase: diarreia com muco, sangue e, às vezes, tenesmo. Pode ocorrer febre\nmoderada."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-108147","number":"108147","sourceNumber":"108147","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma paciente de vinte e cinco anos de idade compareceu a um ambulatório de clínica\nmédica relatando que, periodicamente, há um ano, apresenta quadro clínico constituído por dor\nabdominal difusa (que melhora com a evacuação) associada à alteração do hábito intestinal,\npodendo ocorrer diarreia ou constipação intestinal. A resolução dos sintomas é espontânea, os\nquais duram no máximo dois dias. O exame físico realizado na paciente não apresentou alterações\ndignas de nota. Com relação ao caso clínico acima apresentado, julgue o próximo item: Deve-se\nrecomendar à paciente a adoção de dieta hipograxa com baixo teor de açúcares.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-108155","number":"108155","sourceNumber":"108155","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A respeito das doenças infecciosas, julgue o item seguinte. A síndrome de Loeffler, que\nocorre em pacientes com helmintoses como ascaridíase e ancilostomíase, é caracterizada por\ntosse e crises asmatiformes, sendo diagnóstico diferencial de asma e pneumonia bacteriana de\nrepetição.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-79666","number":"79666","sourceNumber":"79666","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"M.A.S., 5 anos, moradora de área desprovida de saneamento básico, teve exame\nparasitológico de fezes solicitado como profilaxia. Os dados laboratoriais apresentam abundância\nde ovos operculados com as características apresentadas na figura abaixo (VER IMAGEM). De\nacordo com a característica da forma diagnosticada em laboratório, pode-se presumir um caso de","options":{"A":"ascaridíase.","B":"esquistossomose.","C":"ancilostomíase.","D":"teníase.","E":"tricuríase."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-02/79666.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-79675","number":"79675","sourceNumber":"79675","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"M.A.S., 5 anos, moradora de área desprovida de saneamento básico, teve exame\nparasitológico de fezes solicitado como profilaxia. Os dados laboratoriais apresentam abundância\nde ovos operculados com as características apresentadas na figura abaixo (VER IMAGEM).\n\nExames hematológicos complementares desse quadro devem indicar também:","options":{"A":"elevação de macrófagos.","B":"diminuição de macrófagos.","C":"eosinofilia intensa.","D":"eosinopenia.","E":"pancitopenia."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-02/79675.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-88678","number":"88678","sourceNumber":"88678","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Acerca de doenças crônicas, julgue o item subsequente. Quando entra em remissão, a\ndoença de Crohn propicia à maioria dos\npacientes uma vida praticamente normal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-88666","number":"88666","sourceNumber":"88666","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Acerca de intercorrências gastrointestinais, julgue o item subsecutivo. Nas diarreias\nbaixas, as cólicas são produzidas por espasmos do jejuno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-82035","number":"82035","sourceNumber":"82035","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente de trinta e cinco anos de idade procura uma Unidade de Pronto\nAtendimento (UPA) com relato de diarreia,\niniciada havia um dia, com frequência de dez\nevacuações ao dia, associadas à dor e urgência para evacuar, com eliminação de fezes em\npequenas quantidades e com sangue. Ele negou uso de bebidas alcoólicas e de drogas. O exame\nfísico mostrou pressão arterial de 90 mmHg x 50 mmHg, frequência respiratória de 25 irpm, pulso\nde 100 bpm e temperatura axilar de 37,5°C. Observou-se que as mucosas estavam secas. Os\nexames de laboratório revelaram glicemia de 300 mg/dL, com sódio e potássio em níveis séricos\nnormais. Foi realizada punção da artéria radial para coleta de gasometria arterial (paciente\nrespirando ar ambiente). Com base nesse caso clínico, julgue o item a seguir. Fatores como febre,\no sangue nas fezes e a desidratação são manifestações que indicam que a diarreia exige\ninvestigação mais aprofundada de seus fatores etiológicos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-88691","number":"88691","sourceNumber":"88691","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A propósito da doença celíaca, julgue o item que se segue. Por ser uma doença\nautoimune geneticamente determinada e desencadeada\npela exposição do epitélio intestinal ao\nglúten, a doença celíaca manifesta-se, obrigatoriamente, entre seis e doze meses de idade, após a\nintrodução do glúten na dieta.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-64304","number":"64304","sourceNumber":"64304","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Desde de março de 2005, a Secretaria de Vigilância em Saúde do Ministério da Saúde\ntem sido notificada da ocorrência de casos\nconfirmados de doença parasitária causada pela tênia\ndo peixe. Os primeiros casos foram notificados pela Secretaria Estadual de Saúde de São Paulo;\nposteriormente, a Secretaria Estadual de Saúde do Distrito Federal notificou um caso confirmado.\nInternet: www_sindnutridf.org.br (com adaptações). No que se refere às informações do texto\nacima, julgue o item. A doença parasitária a que o texto se refere é a difilobotríase, causada pelo\nDiphyllobothrium sp. Essa doença é associada à ingestão de pescados crus ou mal cozidos,\npodendo se manifestar clinicamente com tonturas, apetite por sal, diarreia, desconforto abdominal\ne, em alguns casos, com obstrução intestinal ou biliar e anemia megaloblástica (por deficiência da\nvitamina B12). Os medicamentos recomendados para o tratamento dessa doença são a\nniclosamina ou o praziquantel.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-52597","number":"52597","sourceNumber":"52597","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação às parasitoses intestinais que apresentam significativa prevalência entre\nas crianças brasileiras, razão porque é\nimportante conhecer o comportamento clínico dessas\nenfermidades para o estabelecimento do correto diagnóstico, julgue o item a seguir: alta carga de\nancilostomídeos em crianças determina, comumente, baixo rendimento escolar, atraso no\ndesenvolvimento psíquico e déficit nutricional.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-52598","number":"52598","sourceNumber":"52598","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação às parasitoses intestinais, que apresentam significativa prevalência entre\nas crianças brasileiras, razão porque é\nimportante conhecer o comportamento clínico dessas\nenfermidades para o estabelecimento do correto diagnóstico, julgue o item a seguir. Tosse e\nurticária são manifestações clínicas comuns nas formas agudas da estrongiloidíase.","options":{"A":"Certo","B":"Errado"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-52602","number":"52602","sourceNumber":"52602","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação às parasitoses intestinais que apresentam significativa prevalência entre\nas crianças brasileiras, razão porque é\nimportante conhecer o comportamento clínico dessas\nenfermidades para o estabelecimento do correto diagnóstico, julgue o item a seguir: na fase larvar\nda ascaridíase predominam sintomas respiratórios como pneumonia e insuficiência respiratória.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-27570","number":"27570","sourceNumber":"27570","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na doença celíaca, pode-se afirmar que ocorre:","options":{"A":"aumento da capacidade absortiva.","B":"redução do processo de esfoliação celular.","C":"aumento de exsudação e secreção.","D":"aumento da ativação de enzimas proteolíticas pancreáticas, aumentando a digestão luminal.","E":"aumento das secreções digestórias, estimulando a pululação bacteriana."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-7547","number":"7547","sourceNumber":"7547","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A ancilostomíase é uma parasitose intestinal causada por nematódeo, podendo levar\nnas formas graves a retardo no desenvolvimento\nfísico e mental das crianças infectadas. Com\nrelação a essa parasitose intestinal, julgue os itens a seguir. I - O agente etiológico é o Ascaris\nlumbricoides. II - Durante a migração da larva do parasito pelo pulmão, podem ocorrer hemorragia\npulmonar e pneumonite. III - Complicação frequente é a anemia, que depende da intensidade da\ninfestação. IV - O tratamento de escolha dessa parasitose é o ivermectin.","options":{"A":"Todos os itens estão errados.","B":"Há apenas um item certo.","C":"Há apenas dois itens certos.","D":"Há apenas três itens certos.","E":"Todos os itens estão certos."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-301247","number":"301247","sourceNumber":"301247","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente de 38 anos de idade procurou atendimento médico com queixas de\nsensação de plenitude, dor epigástrica e\nhiporexia há quatro meses. Relatou ainda episódios\ndiarreicos e, por vezes, disenteriformes, intercalados com constipação intestinal crônica. Ao exame\nfísico, detectou-se fígado de consistência endurecida e aumentado de volume. Na ultrassonografia,\nverificou-se, além da hepatomegalia, a presença de fibrose hepática moderada, sem\nesplenomegalia. O paciente mora em zona endêmica de esquistossomose mansônica. Foram,\nentão, solicitados exames complementares para confirmação do diagnóstico. Com relação ao caso\nclínico apresentado e de acordo com as publicações do Ministério da Saúde, julgue o item a seguir.\nCerca de 10% a 15% dos indivíduos com esquistossomose mansônica, com a mesma forma clínica\ndesse paciente, podem apresentar síndrome nefrótica que, geralmente, melhora após o uso de\nesquistossomicidas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-301248","number":"301248","sourceNumber":"301248","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente de 38 anos de idade procurou atendimento médico com queixas de\nsensação de plenitude, dor epigástrica e\nhiporexia há quatro meses. Relatou ainda episódios\ndiarreicos e, por vezes, disenteriformes, intercalados com constipação intestinal crônica. Ao exame\nfísico, detectou-se fígado de consistência endurecida e aumentado de volume. Na ultrassonografia,\nverificou-se, além da hepatomegalia, a presença de fibrose hepática moderada, sem\nesplenomegalia. O paciente mora em zona endêmica de esquistossomose mansônica. Foram,\nentão, solicitados exames complementares para confirmação do diagnóstico. Com relação ao caso\nclínico apresentado e de acordo com as publicações do Ministério da Saúde, julgue o item a seguir.\nCaso haja mais de 25% de positividade da doença na localidade de moradia do paciente descrito, a\nestratégia será tratar toda a população local.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-301249","number":"301249","sourceNumber":"301249","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente de 38 anos de idade procurou atendimento médico com queixas de\nsensação de plenitude, dor epigástrica e\nhiporexia há quatro meses. Relatou ainda episódios\ndiarreicos e, por vezes, disenteriformes, intercalados com constipação intestinal crônica. Ao exame\nfísico, detectou-se fígado de consistência endurecida e aumentado de volume. Na ultrassonografia,\nverificou-se, além da hepatomegalia, a presença de fibrose hepática moderada, sem\nesplenomegalia. O paciente mora em zona endêmica de esquistossomose mansônica. Foram,\nentão, solicitados exames complementares para confirmação do diagnóstico. Com relação ao caso\nclínico apresentado e de acordo com as publicações do Ministério da Saúde, julgue o item a seguir.\nO diagnóstico do paciente pode ser confirmado pela técnica de sedimentação espontânea, também\nconhecida por Hoffman, Pons e Janer, que permite a quantificação da intensidade da infecção pela\ncontagem dos ovos nas fezes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-301250","number":"301250","sourceNumber":"301250","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente de 38 anos de idade procurou atendimento médico com queixas de\nsensação de plenitude, dor epigástrica e\nhiporexia há quatro meses. Relatou ainda episódios\ndiarreicos e, por vezes, disenteriformes, intercalados com constipação intestinal crônica. Ao exame\nfísico, detectou-se fígado de consistência endurecida e aumentado de volume. Na ultrassonografia,\nverificou-se, além da hepatomegalia, a presença de fibrose hepática moderada, sem\nesplenomegalia. O paciente mora em zona endêmica de esquistossomose mansônica. Foram,\nentão, solicitados exames complementares para confirmação do diagnóstico. Com relação ao caso\nclínico apresentado e de acordo com as publicações do Ministério da Saúde, julgue o item a seguir.\nCom a confirmação diagnóstica, a droga de primeira escolha, para o tratamento do paciente, é o\npraziquantel, medicamento que tem menos efeitos adversos, eficácia terapêutica semelhante e\nmenor custo, quando comparado à oxamniquina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-266440","number":"266440","sourceNumber":"266440","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um jovem de 20 anos de idade procurou atendimento médico com queixa de diarreia\n(10 episódios por dia), persistente havia seis\nmeses, com perda de muco e sangue. O paciente\nafirmou que havia perdido 10Kg de peso nesse período. Por meio de uma colonoscopia, chegou-se\nao diagnóstico de retocolite ulcerativa idiopática (RCUI). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à patologia mencionada, julgue o item subsequente. No caso\nem apreço, o diagnóstico confirmatório depende, necessariamente, de um teste PPD (tuberculose)\ncom resultado positivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-266441","number":"266441","sourceNumber":"266441","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um jovem de 20 anos de idade procurou atendimento médico com queixa de diarreia\n(10 episódios por dia), persistente havia seis\nmeses, com perda de muco e sangue. O paciente\nafirmou que havia perdido 10 kg de peso nesse período. Por meio de uma colonoscopia, chegou-se\nao diagnóstico de Retocolite Ulcerativa Idiopática (RCUI). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à patologia mencionada, julgue o item subsequente. Na fase\nde moderada atividade da RCUI, o tratamento é feito com o uso de mesalazina oral e corticoides.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-291501","number":"291501","sourceNumber":"291501","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um menino de 6 anos de idade, desnutrido, procedente de zona rural sem saneamento\nbásico, apresenta-se no pronto atendimento com\ndor abdominal e diarreia intermitente com muco\nhá 4 meses, algumas vezes associada a sangue e tenesmo. Refere piora do quadro há 1 dia. Ao\nrealizar exame, evidenciou-se descorado ++/+4, prolapso retal e presença de vários vermes\ncilíndricos de 4 cm de comprimento na mucosa retal. Assinale a alternativa CORRETA que aponta\no parasita encontrado e seu respectivo tratamento.","options":{"A":"Ascaris lumbricoides; pamoato de pirantel.","B":"Trichiuris trichiura; mebendazol.","C":"Ascaris lumbricoides; metronidazol.","D":"Trichiuris trichiura; secnidazol."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-274663","number":"274663","sourceNumber":"274663","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Considerando o tema doença inflamatória intestinal no período fértil e a possibilidade\nde complicações na gestação e no parto, é CORRETO\nafirmar:","options":{"A":"A Doença de Crohn pode causar cicatriz perineal, o que torna o parto difícil.","B":"O tratamento geralmente é feito com corticosteroides que podem interferir na absorção de folato.","C":"Devido ao uso dos corticosteroides, deve-se atrasar a amamentação após 1 hora da tomada da\nmedicação.","D":"A intervenção cirúrgica é indicada para complicações médias ou graves decorrentes da doença."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-291542","number":"291542","sourceNumber":"291542","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma mulher de 22 anos de idade foi encaminhada ao serviço de oftalmologia devido a\nepisódio de olho vermelho, em que o médico oftalmologista diagnosticou uma uveíte anterior\naguda. Questionando a paciente, o médico identificou história de aftas orais recorrentes e\ndolorosas há pelo menos 1 ano para as quais não foi realizada nenhuma investigação, fazendo uso\napenas de corticoides tópicos, com alívio fugaz. Relata, ainda, que apresenta dor abdominal e\ndiarreia, mais ou menos, no mesmo período. Refere que as evacuações são frequentes, cerca de 5\na 6 vezes por dia, em pequeno volume e com sangue e muco visíveis em algumas ocasiões.\n\nVisando ao esclarecimento diagnóstico, o procedimento a ser adotado e o achado esperado,\ndevem ser:","options":{"A":"Teste de Patergia; pústula visualizável no local de punção após 7 dias.","B":"Parasitológico das fezes pelo MIF (mercúrio, iodo e formol); cistos e trofozoítos.","C":"Pesquisa de autoanticorpos (FAN); positivo com padrão nuclear pontilhado fino denso.","D":"Colonoscopia com biopsia; histopatológico com granuloma não caseoso."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-244466","number":"244466","sourceNumber":"244466","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No que concerne à síndrome inflamatória intestinal, assinale a alternativa correta.","options":{"A":"A doença de Crohn pode manifestar-se como quadro de abdome agudo, apresentando\nperfurações intestinais, e simular quadros de\napendicite ou de diverticulite.","B":"A doença de Crohn está associada a sintomas extraintestinais, entre eles, eritema nodoso e\ncolangite esclerosante primária.","C":"A doença de Crohn e a retocolite ulcerativa são sempre bem distinguíveis, e ambas devem ser\nacompanhadas pelo risco de neoplasias intestinais.","D":"A retocolite ulcerativa caracteriza-se por inflamação transmural do cólon e do sigmoide.","E":"Diferentemente da doença de Crohn, a perítonite não está entre as principais causas de\nobstrução intestinal."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-227398","number":"227398","sourceNumber":"227398","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de quarenta e cinco anos de idade queixa-se de diarreia persistente há 6\nmeses, com 5 a 10 episódios de fezes\nlíquidas por dia, sem produtos patológicos, associada à dor\nabdominal e flatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como\nreferência, julgue os itens subsecutivos. No tratamento da diarreia crônica, a dieta prescrita deve\nser pobre em resíduos, com restrição de leite e derivados e com incremento de hidratação oral.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-227399","number":"227399","sourceNumber":"227399","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de quarenta e cinco anos de idade queixa-se de diarreia persistente há 6\nmeses, com 5 a 10 episódios de fezes\nlíquidas por dia, sem produtos patológicos, associada a dor\nabdominal e flatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como\nreferência, julgue os itens subsecutivos. A Entamoeba histolytica e a Giardia lamblia são os\nprincipais agentes parasitários causadores de diarreia crônica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-227400","number":"227400","sourceNumber":"227400","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 45 anos de idade queixa-se de diarreia persistente há 6 meses, com 5 a 10\nepisódios de fezes líquidas por dia, sem produtos patológicos, associada a dor abdominal e\nflatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como referência, julgue\nos itens subsecutivos. O exame parasitológico de fezes tem alta sensibilidade quando coletadas\ntrês amostras de fezes.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-227401","number":"227401","sourceNumber":"227401","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de quarenta e cinco anos de idade queixa-se de diarreia persistente há 6\nmeses, com 5 a 10 episódios de fezes\nlíquidas por dia, sem produtos patológicos, associada a dor\nabdominal e flatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como\nreferência, julgue os itens subsecutivos. Nos casos de diarreia crônica, a pesquisa de doença\ncelíaca mediante pesquisa de antigliadina com resultado positivo confirma o diagnóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-227402","number":"227402","sourceNumber":"227402","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de quarenta e cinco anos de idade queixa-se de diarreia persistente há 6\nmeses, com 5 a 10 episódios de fezes\nlíquidas por dia, sem produtos patológicos, associada a dor\nabdominal e flatulência, mas sem febre e sem perda de peso. Tendo esse caso clínico como\nreferência, julgue os itens subsecutivos. Nos casos de diarreia crônica com suspeita de doença\ninflamatória intestinal, o anticorpo anti Saccharomyces cerevisiae (ASCA) tem alta sensibilidade\npara retocolite ulcerativa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-230593","number":"230593","sourceNumber":"230593","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O intestino delgado é responsável por uma importante parte da digestão alimentar. É\ncomposto por duodeno, jejuno e íleo. No intra-operatório, algumas características são mais\nevidentes em cada segmento. O achado anatômico MAIS característico de jejuno é:","options":{"A":"presenças de apêndices epiplóicos.","B":"mesentério com várias arcadas vasculares e vasos retos curtos.","C":"mesentério com poucas arcadas vasculares com vasos retos longos.","D":"mesentério com única arcada vascular e vasos retos longos."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-212117","number":"212117","sourceNumber":"212117","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No que se refere ao tratamento das parasitoses intestinais em adultos (não gestantes),\njulgue o item que se segue. Atualmente, a\noxamniquina representa o tratamento de primeira\nescolha para pacientes com ascaridíase.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-212113","number":"212113","sourceNumber":"212113","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No que se refere ao tratamento das parasitoses intestinais em adultos (não gestantes),\njulgue o item que se segue. Enterobíase pode\nser tratada com pamoato de pirantel ou mebendazol\nou albendazol, em dose única. Recomenda-se que, após duas semanas, seja administrada nova\ndose do anti-helmíntico escolhido, pois esses medicamentos não matam os ovos ou larvas em\ndesenvolvimento.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-206131","number":"206131","sourceNumber":"206131","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre os tumores carcinoides gastrointestinais assinale a alternativa INCORRETA:","options":{"A":"Surgem das células enterocromafins encontradas nas criptas de Lieberkühn.","B":"A síndrome carcinoide maligna ocorre em mais de 50% dos pacientes portadores de tumor\ncarcinoide.","C":"Após o apêndice, o intestino delgado é a região mais afetada.","D":"São compostas por células multipotenciais com capacidade de secretar numerosos agentes\nhumorais."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183862","number":"183862","sourceNumber":"183862","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No que se refere às enfermidades gastrointestinais, julgue o item que se segue.\nComplicações intestinais comuns da doença de\nCrohn, tais como obstrução, abscessos, fístulas e\nlesões anorretais, são consideradas parte do quadro clínico característico da enfermidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183916","number":"183916","sourceNumber":"183916","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Acerca das infecções e suas implicações clínico-cirúrgicas, julgue o próximo item. Em\npacientes com síndrome de Loeffler, há acúmulo de eosinófilos no tecido pulmonar, em resposta à\ninfecção por alguns tipos de parasitas, como, por exemplo, o Ascaris lumbricoides.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183960","number":"183960","sourceNumber":"183960","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A respeito das doenças infecciosas e parasitárias, julgue o item subsequente. Ao\npenetrar na pele, o Ancylostoma duodenale\nprovoca prurido e uma dermatite caracteristica: a larva\nmigrans.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183964","number":"183964","sourceNumber":"183964","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A respeito das doenças infecciosas e parasitárias, julgue o item subsequente. A Taenia\nsaginata tem como reservátório o suino, em cujos tecidos se desenvolve a forma larvária que\nprovoca no ser humano a neurocisticercose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183852","number":"183852","sourceNumber":"183852","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A respeito de doenças infecciosas e parasitárias, julgue o item subsequente.\nStrongyloides stercoralis, Entamoeba histolytica,\nAscaris lumbricoides, Ancylostoma duodenale e o\nNecator americanus são parasitas de ciclo pulmonar no ser humano e provocam a síndrome de\nLoeffler.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-157973","number":"157973","sourceNumber":"157973","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No ambulatório de pediatria, é atendida uma paciente do sexo feminino, de 3 anos de\nidade, com quadro diarreico com restos alimentares, flatulência e dor abdominal. Mãe nega\npresença de sangue nas fezes. Após anamnese detalhada e exame físico minucioso, é levantada a\nhipótese de parasitose intestinal. Com base nesse caso clínico, assinale a alternativa que melhor\nreflete, respectivamente, a hipótese diagnóstica e o tratamento adequado:","options":{"A":"Giardíase e albendazol.","B":"Estrongiloidíase e cambendazol.","C":"Teníase e secnidazol.","D":"Enterobíase e pamoato de pirvínio.","E":"Amebíase e metronidazol."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-159601","number":"159601","sourceNumber":"159601","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo feminino, de trinta e cinco anos de idade, com baixa condição\nsocioeconômica, habitante de moradia sem\nsaneamento básico adequado, vinha evoluindo havia\ndez dias com anorexia, dor no quadrante superior direito do abdome, febre, adinamia e diarreia. Ao\nter sido admitida no serviço de pronto-socorro, realizou exames laboratoriais e de imagem.\n\nApresentava anemia, leucocitose (14.000/mL), bilirrubinas normais e elevação das transaminases e\nda fosfatase alcalina. O exame físico\ndemonstrou fígado aumentado de tamanho. A\nultrassonografia abdominal evidenciou a presença de abscesso hepático único de 7 cm x 8 cm no\nsegmento VI, com conteúdo homogêneo e hipoecoico, apresentando cápsula espessa. Com\nrelação ao caso clínico descrito, julgue o item subsecutivo. A abordagem inicial mais adequada\nseria a administração de antibioticoterapia. Na falha do tratamento clínico, uma opção seria\nrealizar\npunção guiada por ultrassonografia ou tomografia computadorizada de abdome.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-159612","number":"159612","sourceNumber":"159612","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo feminino, de trinta e cinco anos de idade, com baixa condição\nsocioeconômica, habitante de moradia sem\nsaneamento básico adequado, vinha evoluindo havia\ndez dias com anorexia, dor no quadrante superior direito do abdome, febre, adinamia e diarreia. Ao\nter sido admitida no serviço de pronto-socorro, realizou exames laboratoriais e de imagem.\n\nApresentava anemia, leucocitose (14.000/mL), bilirrubinas normais e elevação das transaminases e\nda fosfatase alcalina. O exame físico\ndemonstrou fígado aumentado de tamanho. A\nultrassonografia abdominal evidenciou a presença de abscesso hepático único de 7 cm x 8 cm no\nsegmento VI, com conteúdo homogêneo e hipoecoico, apresentando cápsula espessa. Com\nrelação ao caso clínico descrito, julgue o item subsecutivo. As manifestações clínicas, os exames\nlaboratoriais e o aspecto da ultrassonografia sugerem tratar-se de abscesso hepático piogênico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-158090","number":"158090","sourceNumber":"158090","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 22 anos de idade é levado pelo pai ao pronto-socorro com queixas de\ndores fortes na região lombar, com evolução\nde alguns anos e piora progressiva. O paciente refere\nque, há muito tempo, as respectivas fezes, frequentemente, diarreicas, eventualmente têm sangue.\nEle nunca investigou o quadro, pois mora no interior e não possui bom acesso aos serviços de\nsaúde. O pai está muito preocupado com o quadro do filho, que está \"emagrecendo e encolhendo\nde tão doente\". Considerando esse caso clínico e os conhecimentos médicos a ele relacionados,\nassinale a alternativa CORRETA.","options":{"A":"Trata-se de uma artrite reativa por infecção por Shigella.","B":"O comprometimento axial tem relação com a atividade da doença intestinal.","C":"Provavelmente haverá fator reumatoide positivo.","D":"O envolvimento articular no contexto das doenças inflamatórias intestinais é mais comum na\ndoença de Crohn.","E":"O padrão de envolvimento axial evolui de forma ascendente e contínua, mas não costuma ser\nsimétrico."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-168435","number":"168435","sourceNumber":"168435","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um homem com 18 anos de idade é encaminhado à consulta no ambulatório de\nmedicina interna por estar com diarreia há\nmais de 4 semanas acompanhada de dor abdominal,\nfebre intermitente, perda de peso e hematoquezia ocasional. Ao exame físico, o paciente mostra-se\nemagrecido e sente dor à palpação profunda de fossa ilíaca direita, onde uma massa abdominal é\npalpada. Apresenta resultado de hemograma realizado na unidade básica de saúde com\nhematócrito = 36% (valor de referência: 39 a 49%), sem leucocitose, sendo a velocidade de\nhemossedimentação = 30 mm na primeira hora. O resultado do exame parasitológico de fezes é\nnegativo. Nessa situação, qual deve ser o próximo exame a ser solicitado ao paciente?","options":{"A":"Colonoscopia.","B":"Enema baritado.","C":"Ultrassonografia de abdome.","D":"Pesquisa de anticorpos antiendomísio e antigliadina."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-133952","number":"133952","sourceNumber":"133952","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente feminina de 28 anos de idade queixa-se de episódios eventuais de\n\"constipação e diarreia, sempre que fico nervosa\", nos últimos meses. Com base nesse caso\nhipotético, é correto afirmar que, excluídas causas orgânicas, o diagnóstico de síndrome do\nintestino irritável, de acordo com os critérios de ROMA III, leva em consideração","options":{"A":"Alteração na frequência de evacuações nas últimas três semanas.","B":"Alteração da aparência de evacuações nos últimos dois meses.","C":"Dor abdominal recorrente por pelo menos três semanas nos últimos três meses.","D":"Dor abdominal recorrente por pelo menos dois dias nos últimos seis meses.","E":"Dor abdominal recorrente por pelo menos três dias nos últimos três meses."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-133989","number":"133989","sourceNumber":"133989","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"As parasitoses intestinais representam um grave problema de saúde pública no Brasil,\nprincipalmente nos estados mais pobres e nas periferias dos grandes centros urbanos,\nparticularmente na população pediátrica. A respeito das parasitoses intestinais, assinale a\nalternativa CORRETA:","options":{"A":"A Necator americanus, o Strongyloides stercoralis e o Ascaris lumbricoides possuem ciclo\npulmonar.","B":"O prolapso retal é um achado típico da enterobíase.","C":"A infecção do homem na estrongiloidiase decorre da ingestão de alimentos contaminados com\novos dos estrongilóides e pode ser tratado\ncom tiabendazol por três dias.","D":"A giardíase pode apresentar-se como diarreia aguda autolimitada ou diarreia crônica com\npresença de esteatorreia. Uma forma de\nprevenir essa parasitose é estimular a higiene pessoal e a\ncloração da água.","E":"A amebíase pode-se apresentar de diversas formas, desde o espectro assintomático até a forma\nextraintestinal. Na forma extraintestinal, o achado de abscesso renal é muito comum."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111308","number":"111308","sourceNumber":"111308","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Considere um paciente de 38 anos de idade, sexo masculino, há trinta dias com\nquadro de prurido generalizado, fadiga,\ndesconforto abdominal no quadrante superior direito e\nperda ponderal. Os exames laboratoriais mostraram elevação dos níveis séricos de fosfatase\nalcalina, gama glutamiltransferase e, em menor escala, das aminotransferases. Os valores das\nbilirrubinas séricas eram normais. A ecografia hepática não mostrou anormalidades. A\ncolangiorressonância mostrou estreitamentos e irregularidades em vários pontos da via biliar, com\naspecto de ?colar de contas?. Na situação, qual doença deve ser investigada por coexistir entre\n60% e 80% dos casos?","options":{"A":"Síndrome de Sjögren.","B":"Doença inflamatória intestinal.","C":"Hepatite C.","D":"Hepatite B.","E":"Pancreatite crônica."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-104760","number":"104760","sourceNumber":"104760","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma criança de nove anos de idade apresentou quadro de diarreia com eliminação de\nfezes líquidas, explosivas, fétidas, com muco e sem sangue, às vezes com resíduos de alimentos,\nassociando-se à anorexia, náuseas, dor tipo cólica, distensão abdominal e à flatulência.\n\nConsiderando esse caso hipotético, assinale a alternativa que apresenta o diagnóstico mais\nprovável:","options":{"A":"Infecção por rotavírus.","B":"Giardíase.","C":"Estrongiloidíase.","D":"Escherichia coli.","E":"Amebíase."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-104756","number":"104756","sourceNumber":"104756","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação às doenças inflamatórias intestinais inespecíficas, assinale a alternativa\ncorreta.","options":{"A":"Não há correlação entre câncer dos cólons e colite ulcerativa.","B":"A retocolite ulcerativa acomete primordialmente a camada mucosa do intestino grosso.","C":"As fístulas perianais relacionadas com a doença de Crohn devem sempre ser tratadas com\nfistulotomias.","D":"A doença de Crohn nos cólons é de tratamento cirúrgico exclusivo.","E":"A presença de lesões anais e perianais exclui a possibilidade de retocolite ulcerativa."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111270","number":"111270","sourceNumber":"111270","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) e a Retocolite Ulcerativa (RCU) são as principais doenças\ninflamatórias intestinais. São causadas pela interação de fatores genéticos, microbiota intestinal e\nimunorregulação da mucosa. Em relação à abordagem cirúrgica eletiva em pacientes que sofrem\nde RCU, são indicações, EXCETO:","options":{"A":"Atraso no crescimento em crianças.","B":"Manifestações intestinais (pioderma gangrenoso).","C":"Presença de displasia de alto grau.","D":"Presença de adenocarcinoma no segmento colorretal.","E":"Megacólon tóxico."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111282","number":"111282","sourceNumber":"111282","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em lactentes, o quadro clínico clássico da Doença Diarreica Aguda (DDA) causada pelo\nrotavírus é:","options":{"A":"Febre, vômitos e diarreia aquosa.","B":"Diarreia aquosa sem vômitos ou febre.","C":"Vômitos e diarreia aquosa.","D":"Febre e diarreia aquosa.","E":"Febre, vômitos e diarreia sanguinolenta."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111265","number":"111265","sourceNumber":"111265","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Para diagnosticar definitivamente a doença celíaca (intolerância permanente às\nproteínas do glúten) em crianças menores de\ndois anos, além da história clínica, epidemiológica, do\nexame físico e dos testes sorológicos direcionados contra estas frações proteicas ou seus\nhomólogos, necessita-se de:","options":{"A":"Análise histopatológica da biópsia da mucosa\nintestinal.","B":"Dosagem de gordura fecal.","C":"Teste de absorção intestinal de D?xilose.","D":"Dosagem de alfa-1-antitripsina fecal.","E":"Teste de Lundh."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-80697","number":"80697","sourceNumber":"80697","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa que apresenta um fator que aumenta o risco para o\ndesenvolvimento de câncer colorretal em um paciente com retocolite ulcerativa.","options":{"A":"Gravidade da doença.","B":"Uso de drogas imunossupressoras.","C":"Extensão da doença.","D":"Uso prolongado de esteroides.","E":"Acometimento exclusivo do reto."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-97735","number":"97735","sourceNumber":"97735","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma criança com seis anos de idade, natural e procedente da região Norte do Brasil, é\ninternada em hospital com história de febre há seis meses, de caráter intermitente. Não apresenta\ndiarreia. Perda de 3 kg de peso desde o início do quadro. Ao exame físico apresenta-se eupneica;\nhidratada; murmúrio vesicular presente bilateralmente, com sibilos esparsos; bulhas cardíacas\nrítmicas e normofonéticas; fígado a 4 cm do rebordo costal direito e a 4 cm do apêndice xifoide;\nbaço a 3 cm do rebordo costal esquerdo; sem edemas. Exames laboratoriais: hemoglobina = 10\ng/dl (valor de referência = 11,5-13,5 g/dl); hematócrito = 36% (valor de referência = 34-40%);\nleucócitos = 15.000/mm³ (valor de referência = 5.500-14.500/mm³); neutrófilos = 38%; eosinófilos =\n42%; monócitos = 1%; linfócitos = 19%; plaquetas = 160.000/mm³ (valor de referência =\n\n150.000-350.000/mm³); proteínas totais = 6,2 g/dl (valor de referência = 6,0-8 g/dl); albumina = 2,5\ng/dl (valor de referência = 2,9-4,7 g/dl); globulina = 3,7 g/dl (valor de referência = 1,4-3,2\ng/dl). A\nhipótese diagnóstica e a investigação complementar necessária para confirmação diagnóstica são:","options":{"A":"Febre tifoide; solicitar reação de Widal.","B":"Leishmaniose visceral; solicitar mielograma.","C":"Toxocaríase; solicitar IgE sérica e sorologia específica.","D":"Esquistossomose mansônica; solicitar parasitológico de fezes."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-97749","number":"97749","sourceNumber":"97749","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente com 35 anos de idade, controlador de voo, retorna à consulta na unidade\nbásica de saúde apresentando resultados\nnegativos de exame protoparasitológico de fezes e de\nteste de tolerância à lactose. Relata que desde a adolescência tem episódios de evacuações\nexplosivas com fezes amolecidas. Atualmente, queixa-se de alteração de hábito intestinal há seis\nmeses, quando passou a apresentar desconforto abdominal em andar inferior do abdome, que dura\nem média dois a três dias por semana, alternando quadros de obstipação com diarreia e urgência\nfecal, com a presença de muco de cor clara, quase transparente. O quadro de desconforto\nabdominal piora em situação de estresse e melhora quando evacua ou elimina flatos. Em relação\nao quadro clínico apresentado, qual das alternativas abaixo representa critério para o diagnóstico?","options":{"A":"Melhora do desconforto abdominal após evacuação.","B":"Sensação recorrente de empachamento.","C":"Urgência fecal com muco e sangue.","D":"Presença de muco nas fezes."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-97828","number":"97828","sourceNumber":"97828","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente com 25 anos de idade é encaminhado pela Unidade de Saúde da Família\ndo seu bairro para avaliação no Ambulatório\nde Clínica Médica por apresentar quadro de diarreia\nnão acompanhada de cólicas há 5 meses, com três a quatro evacuações ao dia, em grande\nquantidade, sem presença de muco ou sangue. O paciente refere perda de 15 kg nesse período,\nsem que tenha modificado a sua dieta ou apresentado mudança de apetite. O paciente trouxe à\nconsulta cinco exames protoparasitológicos das fezes realizados nesse período, sendo que o\nprimeiro demonstrou a presença de tricocéfalos, o que motivou tratamento, por duas vezes, com\nalbendazol durante 3 dias, sem melhora do quadro. O paciente apresentou igualmente\nhemogramas que demonstravam anemia hipocrômica, microcítica, com anisocitose, sem alteração\nnas séries branca ou megacariocítica. A investigação complementar indicada e o diagnóstico são:","options":{"A":"realizar pesquisa (dosagem) de gordura fecal e, se anormal, considerar a realização de biópsia\nde intestino delgado pela possibilidade de\ndoença celíaca.","B":"realizar tomografia computadorizada de abdome para avaliar a ocorrência de calcificações\npancreáticas e determinar o diagnóstico de pancreatite crônica.","C":"realizar colonoscopia com biópsias de intestino devido à possibilidade de doença inflamatória\nintestinal, como a retocolite ulcerativa.","D":"realizar dosagens de hormônio estimulador da tireoide (TSH) e de T4 livre para avaliar a\npossibilidade de hipertireoidismo."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-97789","number":"97789","sourceNumber":"97789","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um escolar com 7 anos de idade, peso = 14 kg, proveniente de uma instituição para\nmenores abandonados, apresenta dor abdominal\ndifusa, tipo cólica, recusa à alimentação e\ntambém palidez, náuseas e vômitos. A informante nega a ocorrência de febre. Ao exame físico\napresenta fácies de dor, afebril, hidratado, pálido (++/4+), frequência respiratória = 34 irpm,\nfrequência cardíaca = 115 bpm, auscultas pulmonar e cardíaca normais. Pulsos cheios. Tempo de\nenchimento capilar < 2 segundos, pressão arterial = 100 x 60 mmHg. Abdome globoso, com\nperistalse aumentada, palpando-se massas arredondadas, móveis, de consistência elástica, em\nflanco e fossa ilíaca, à esquerda. Ausência de sinais de dor à descompressão brusca do abdome.\nObservaram-se formações esféricas na radiografia de abdome em anteroposterior, com densidade\nde líquido, projetando-se em meio ao conteúdo gasoso de cólon e reto (?imagem em miolo de\npão?) e distensão difusa de alças intestinais. Baseando-se no diagnóstico desse paciente, além da\nanalgesia e da hidratação venosa, a medicação específica de escolha é:","options":{"A":"albendazol, 400 mg, dose única.","B":"mebendazol, 100 mg/kg, 2 vezes ao dia, durante 1 dia.","C":"levamisole 150 mg, dose única.","D":"piperazina 100 mg/kg, 1 vez ao dia, durante 4 dias."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-97770","number":"97770","sourceNumber":"97770","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um pré-escolar, com dois anos e nove meses de idade, é trazido à unidade de saúde\nde sua cidade com os resultados dos exames\nanteriormente solicitados. Naquela ocasião, a mãe\nrelatou que a criança apresentava cansaço e falta de apetite, além de dor abdominal e episódios de\ndiarreia e vômitos esporádicos. Há algumas semanas apresentou vesículas e prurido intenso nos\npés. Exame físico: regular estado geral, emagrecido e pálido; com distensão abdominal.\n\nHemograma: hemoglobina = 9,9 g/dl (valor de referência = 11,5-13,5 g/dl); hematócrito = 33% (valor\nde referência = 34-40%); volume corpuscular\nmédio = 72 fl (valor de referência = 70-86 fl);\nhemoglobina corpuscular média = 22 pg/cél (valor de referência = 22-31 pg/cél); leucócitos =\n9.200/mm³ (valor de referência = 5.500-14.500/mm³); basófilos = 0%; eosinófilos = 10%; bastões =\n1%; segmentados = 40%; linfócitos = 50%; monócitos = 0%. O diagnóstico CORRETO e tratamento\nindicado para essa criança são:","options":{"A":"Giardíase; metronidazol.","B":"Ascaridíase; cambendazol.","C":"Ancilostomíase; mebendazol.","D":"Larva migrans cutânea; tiabendazol."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-97791","number":"97791","sourceNumber":"97791","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma criança, do sexo feminino, com 2 anos de idade foi internada na enfermaria de um\nhospital com história de diarreia há 4 meses, com 7 a 8 evacuações por dia, caracterizadas por\nfezes volumosas e de odor fétido. Ao exame físico: estado geral comprometido, palidez cutânea,\nemagrecimento, hipotrofia muscular mais evidente em região glútea e distensão abdominal. Não há\noutros achados significativos. O diagnóstico CORRETO e a sequência da investigação diagnóstica\nsão:","options":{"A":"Diarreia funcional; dosagem de eletrólitos séricos e pesquisa da gordura fecal.","B":"Doença celíaca; dosagem de anticorpos antiendomísio e antitransglutaminase e biópsia\nintestinal.","C":"Doença de Crohn; dosagem do ASCA (Anticorpo Antissaccharomyces Cerevisiae) e enema\nopaco.","D":"Retocolite ulcerativa; dosagem do p-ANCA (anticorpo perinuclear contra estruturas\ncitoplasmáticas do neutrófilo) e biópsia de cólon."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-75491","number":"75491","sourceNumber":"75491","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher com 22 anos de idade vem à consulta ambulatorial com diarreia há seis meses.\nApresenta cerca de seis evacuações ao dia, com fezes pastosas volumosas, de odor fétido,\namareladas e espumosas, sem muco ou sangue. Nega tenesmo ou febre. Piora com a ingestão de\nleite. Tem cólicas eventuais e distensão abdominal gasosa. Teve perda ponderal de 5 kg desde o\ninício do quadro. É solteira, sem atividade sexual. Nega uso de drogas ou álcool. Nega cirurgias\nprévias.\n\nAo exame físico, apresenta-se com índice de massa corpórea de 22 kg/m². Mucosas hipocrômicas.\nEvidente perda de massa muscular. Abdome\ndiscretamente distendido por gases, sem ascite,\nvisceromegalias ou tumorações. Presença de lesões de pele, de aspecto herpetiforme, em tronco.\nNo relatório, para justificar o encaminhamento da paciente para o especialista, deverá ser\nespecificada a necessidade de que a paciente seja submetida a:","options":{"A":"Tomografia computadorizada de abdome total.","B":"Retossigmoidoscopia com biópsia de mucosa retal.","C":"Colonoscopia com biópsia de mucosa de sigmoide.","D":"Estudo radiológico de trânsito do intestino delgado.","E":"Endoscopia digestiva alta com biópsia de duodeno."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-64453","number":"64453","sourceNumber":"64453","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É agente etiológico da colite pseudomembranosa:","options":{"A":"Clostridium difficile.","B":"Staphylococcus aureus.","C":"Pseudomonas.","D":"Streptococcus pyogenes.","E":"Salmonella."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-75480","number":"75480","sourceNumber":"75480","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Criança com 4 anos de idade foi levada pela mãe à unidade básica de saúde com\nqueixa de distensão abdominal, hiporexia,\npalidez cutânea e referência ao \"hábito de comer terra\"\n(sic). Foram realizados exames laboratoriais e observados os seguintes resultados: Hb: 8,4 g/dl;\nHtc: 28%; VCM: 64 fl; HCM: 17 pg; leucócitos totais: 6.400/mm³; eosinófilos: 13%; ferro sérico: 18\nµg/dl. Tendo por base a prevalência das doenças parasitárias em nosso meio, os sintomas\napresentados pela criança e os resultados de exames registrados, deve-se considerar o diagnóstico\nde:","options":{"A":"Teníase.","B":"Giardíase.","C":"Amebíase.","D":"Enterobíase.","E":"Ancilostomíase."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-75497","number":"75497","sourceNumber":"75497","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Jovem com 17 anos de idade, refere que há cerca de seis meses tem apresentado\ndiarreia (quatro a seis evacuações/dia) com\nmuco e sangue, precedida de dor abdominal em cólica.\nRelata ainda tenesmo. Há cerca de um mês, vem apresentando dor anal e reparou que a roupa\níntima tem ficado suja com sangue. Descreve perda de cerca de 12% do peso habitual, com piora\nnos últimos quinze dias. Ao exame, apresenta-se emagrecido, com mucosas hipocoradas (++\nem++++), com discreta distensão abdominal e dor abdominal à palpação, principalmente no trajeto\ndos cólons, sem sinais de irritação peritoneal. Exame perianal mostra várias fissuras anais:\nanterior,\nposterolateral direita e posterolateral esquerda. Não foi realizado toque retal. Sem outros achados\nao exame físico. A hipótese diagnóstica e a conduta para este paciente são, respectivamente:","options":{"A":"doença de Crohn; prescrever corticoesteroides.","B":"diarreia bacteriana; prescrever metronidazol.","C":"linfoma intestinal; solicitar trânsito intestinal.","D":"retocolite ulcerativa; realizar colonoscopia.","E":"estrongiloidíase; prescrever tiabendazol."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-137551","number":"137551","sourceNumber":"137551","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um menino de dois anos de idade é levado à Unidade Básica de Saúde (UBS) próxima\nao assentamento onde sua família reside, com\nqueixa de diarreia intermitente, com restos\nalimentares em alguns episódios, sem sangue ou muco, associada a dor epigástrica e hiporexia,\niniciada há 15 dias. No último ano, a criança foi levada à UBS duas vezes pelo mesmo motivo. A\ngenitora relata que, há dois meses, a criança também apresentou lesões de pele muito\npruriginososas, seguidas de tosse, com resolução espontânea em 3 dias. O padrão alimentar\n\ninclui alimentos da família e leite de vaca engrossado com farináceos desde que foi suspenso o\naleitamento materno aos 3 meses de vida. A situação vacinal está adequada à idade. O médico\nobservou: peso = 11 kg (percentil 15); turgor e elasticidade da pele um pouco diminuídos, mucosas\nhipocoradas, distensão abdominal moderada, com dolorimento discreto e difuso e ausência de\nedema, de lesões de pele significativas ou de sinais de instabilidade respiratória\n\nou hemodinâmica. Para esse paciente, foram prescritas reidratação oral e orientação\n\nhigiênico-sanitária. Qual a hipótese diagnóstica que melhor explica o quadro descrito acima e qual a\nconduta que deve ser aplicada?","options":{"A":"Enteropatia ambiental; solicitar parasitológico de fezes e tratar com antiparasitário adequado ao\nagente identificado.","B":"Enteropatia dependente do glúten; solicitar anticorpo antigliadina e antiendomísio e excluir da\ndieta glúten e farináceos em geral.","C":"Enteropatia por alergia ao leite de vaca; solicitar dosagem de IgA\n\nsecretora, excluir leite de vaca da dieta e prescrever fórmula isenta de proteínas do leite","D":"Enteropatia infecciosa aguda; solicitar coprocultura, iniciar sulfametexazol-trimetoprim ou\ncefalosporina de primeira geração durante 7 a 10 dias.","E":"Enteropatia dependente da lactose; excluir fontes de lactose da dieta, prescrever probióticos,\nprebióticos e usar\n\nleite de soja ou fórmula láctea isenta de lactose"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-137557","number":"137557","sourceNumber":"137557","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma mulher de 25 anos de idade procurou o ambulatório com queixa de febre e\ndiarreia há mais de um mês, com cerca de\nseis evacuações por dia, seguidas por sangramento, dor\nabdominal e perda de peso de aproximadamente 10 quilos. Ao exame físico, apresentava-se\nemagrecida, com pele e mucosas descoradas ++/4+ e temperatura = 38,5°C. Foi observada a\npresença de fissuras perianais. Exames laboratoriais mostraram Hb = 8,2 g/dL (valor de referência\n\n=11,3 a 16,3 g/dL), volume corpuscular médio = 70 fL (valor de referência = 79 a 93,3 fL),\nleucócitos\n\n= 15 000/mm³ (valor de referência = 3 800 a 10 600/mm³ ), plaquetas = 520 000/mm³ (valor de\nreferência = 165 000 a 415 000/mm³ ), velocidade de hemossedimentação = 70 mm/h (valor de\nreferência: < 20 mm/h). Imediatamente, o médico decidiu encaminhar a paciente para um serviço\nespecializado devido à suspeita diagnóstica de doença inflamatória intestinal grave. Os critérios de\ninclusão nessa categoria de gravidade devem considerar","options":{"A":"a leucocitose, o número de plaquetas, a perda de peso, a\nfebre e a anemia.","B":"o número de evacuações com sangue por dia, a febre, a anemia e a VHS elevada.","C":"o número de plaquetas, a febre, a perda de peso, as fissuras perianais e a anemia.","D":"a idade, o número de evacuações com sangue por dia, a\nleucocitose e a VHS elevada.","E":"a idade, a dor abdominal, o número de evacuações com\nsangue por dia e a VHS elevada."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-137573","number":"137573","sourceNumber":"137573","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente com 50 anos de idade, morador de zona rural, em condições precárias,\nsem banheiro na residência e sem rede de água e\nesgoto na localidade, procura a Unidade Básica\nde Saúde (UBS) por apresentar dor abdominal de leve intensidade em epigástrio, que piora com a\nalimentação, associada a náuseas. Refere também urticária. Realizou exame parasitológico de\nfezes, que foi negativo. Qual o diagnóstico mais provável nesse caso?","options":{"A":"Ancilostomíase.","B":"Ascaridíase.","C":"Giardíase.","D":"Estrongiloidíase.","E":"Esquistossomose."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-138402","number":"138402","sourceNumber":"138402","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um menino com cinco anos e oito meses foi levado pela mãe à Unidade Básica de\nSaúde. Há três semanas vem apresentando dor abdominal inespecífica, tosse, febre e hábito de\ncomer terra. Ao exame físico, o médico encontrou palidez cutânea moderada e hepatomegalia.\nForam solicitados alguns exames: 1) hemograma: hemoglobina 10 g/dL, hematócrito 30 %.\nleucocitose (16.000 /mm3), eosinofilia (12 %), plaquetas normais; 2) exame parasitológico das\nfezes (em andamento) e 3) exame ultrassonográfico do abdome que revelou imagens\nhipoecogênicas micronodulares no fígado. Com base na história clínica e nos exames\ncomplementares, o diagnóstico principal e o tratamento são","options":{"A":"ancilostomíase; utilizar mebendazol, 100 mg, duas\nvezes ao dia, durante três dias.","B":"giardíase; utilizar secnidazol, 30 mg/Kg, dose única","C":"toxocaríase; utilizar albendazol, 10 mg/Kg, uma vez ao dia, durante cinco dias.","D":"estrongiloidíase; utilizar secnidazol, 25 mg/Kg, uma vez ao dia, de cinco a sete dias.","E":"amebíase; utilizar secnidazol, 30 mg/Kg, dose única."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-138466","number":"138466","sourceNumber":"138466","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Garota, com 13 anos de idade, moradora de rua, procura atendimento na rede básica\nde saúde, relatando falta de apetite,\nperversão do hábito alimentar, com relato de ingestão\nfrequente de terra, epigastralgia, além de prurido anal e vaginal. Ao exame físico apresenta-se\nemagrecida e hipocorada. O exame parasitológico de fezes para pesquisa de ovos e larvas de\nhelmintos e cistos de protozoários pelos métodos de Faust, Lutz e Baerman Moraes, revela:\n\n?presença de ovos de Ascaris lumbricoides, Trichuris trichiura e Ancylostoma duodenale. Presença\nde cistos de Entamoeba coli. Presença de\nlarvas de Strongyloides stercoralis?. Assinale a\nalternativa que contém a prescrição que visa o tratamento das enteroparasitoses apresentadas pela\npaciente.","options":{"A":"albendazol em dose única e praziquantel em dose\núnica.","B":"levamizol em dose única e ivermectina em dose\núnica.","C":"metronidazol por sete dias e tiabendazol por dois\ndias.","D":"albendazol por quatro dias e tinidazol em dose única.","E":"albendazol em dose única e tiabendazol por dois\ndias."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-138534","number":"138534","sourceNumber":"138534","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Trinta e cinco indivíduos, adolescentes e adultos, alimentam-se em um restaurante com\nbuffet de comida ?por quilo?. Cerca de quatro horas depois, sete integrantes do grupo apresentam\ndiarreia com várias evacuações aquosas, sem febre, acompanhadas de cólicas abdominais e\nvômitos. Ao serem avaliados apresentam-se apiréticos, desidratados, alguns deles necessitando de\nhidratação venosa. Dois dias depois, três outros membros do grupo, que também haviam comido\nno mesmo buffet, apresentam quadro de diarreia, eliminação de fezes com muco, pus e sangue,\nacompanhado de febre e mal estar. Na avaliação clínica apresentam-se desidratados, febris e\ntoxemiados. Quais são os agentes etiológicos que melhor explicam a epidemiologia e as\ncaracterísticas clínicas dos quadros diarreicos descritos?","options":{"A":"Staphylococcus aureus e Salmonella enteritidis.","B":"Staphylococcus aureus e Escherichia coli\nenterotoxigênica.","C":"Staphylococcus aureus e Bacillus cereus.","D":"Salmonella enteritidis e Yersinia enterocolitica.","E":"Shigella flexneri e Escherichia coli enteropatogênica."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-304851","number":"304851","sourceNumber":"304851","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a assertiva INCORRETA com relação à Doença de Crohn.","options":{"A":"Considerando a avaliação macroscópica, as lesões podem afetar qualquer segmento do trato\ngastrointestinal, com inflamação transmural e propensão a fenótipos penetrantes.","B":"O intestino comprometido pela doença pode fistulizar para o intestino adjacente ou estruturas\nadjacentes normalmente não afetadas pela doença.","C":"Uma característica macroscópica observada nas abordagens cirúrgicas da doença é a serosite\ncom envolvimento e invasão da serosa pela gordura\nmesentérica.","D":"O clássico granuloma não caseoso é encontrado em menos de 15% das biópsias, sendo o\ndiagnóstico baseado na soma de achados clínicos, endoscópicos e de imagens."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-354122","number":"354122","sourceNumber":"354122","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma criança com 4 anos de idade, é atendida em consulta de puericultura, com queixa\nde dor abdominal associada a episódios de\ndiarreia, com evolução de aproximadamente 4 meses.\nA mãe da paciente relata que a família reside em bairro sem rede de esgoto. A criança brinca muito\nna rua com os irmãos de 6 e 8 anos, bebe água não tratada e anda descalça. Após orientar\ncorretamente a mãe acerca das condutas de higiene e prevenção das parasitoses, o pediatra\nsolicita exame parasitológico de fezes. O resultado do exame parasitológico indica infestação por\nAscaris lumbricoides, Giárdia lamblia e Necator americanus. Nessa situação, o tratamento\nterapêutico adequado deve ser feito com:","options":{"A":"metronidazol e mebendazol.","B":"metronidazol, apenas.","C":"tiabendazol e albendazol.","D":"mebendazol, apenas.","E":"tiabendazol e metronidazol."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-335079","number":"335079","sourceNumber":"335079","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Considere as afirmativas a seguir sobre os tumores do intestino delgado (jejuno-ileal).\nI.\nOs carcinoides intestinais pequenos surgem a partir de células endócrinas intraepiteliais. II. Os\npequenos tumores carcinoides intestinais são mais frequentemente localizados no íleo a 60 cm da\nválvula ileocecal. III. Os carcinoides de intestino delgado sempre se apresentam sintomáticos.\n\nEstão corretas as afirmativas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-337635","number":"337635","sourceNumber":"337635","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"As parasitoses intestinais ainda são um grave problema de saúde, principalmente nos\npaíses em desenvolvimento. Sobre as parasitoses intestinais, é CORRETO afirmar que:","options":{"A":"O Ascaris lumbricoides, causador da ascaridíase, geralmente gera sintomas inespecíficos, como\ndiarreia, náuseas, vômitos, dor abdominal inespecífica, distensão abdominal, má absorção e\ndesnutrição. Sobre essa desnutrição, seu mecanismo se deve as lesões que o parasita causa na\nmucosa intestinal, prejudicando a absorção de nutrientes.","B":"Um dos anti-helmínticos mais clássicos é o mebendazol. Além de baixo custo, ele tem o seu uso\nconsagrado de polivalência na maioria das helmintíases; porém, sem ação na estrongiloidíase.","C":"O método de exame direto das fezes a fresco pode determinar qualquer parasitose, mas com\nbaixos níveis de sensibilidade. Para\nresultados mais apurados, um exemplo de exame que pode ser\nsolicitado é o método de Kato Katz na suspeita de contaminação pela Entamoeba histolytica.","D":"Apesar de ser uma prática comum, a OMS desincentiva o uso profilático dos antiparasitários\npela alta toxicidade dos medicamentos utilizados."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-304879","number":"304879","sourceNumber":"304879","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Escolar, oito anos, é levado à Unidade Básica de Saúde apresentando há uma semana\nprurido anal diário, na madrugada, que o faz perder o sono. Seu irmão mais novo teve o mesmo\nsintoma, melhorando após o uso de medicação. Exame físico sem alterações. Os medicamentos\nque podem ser utilizados no tratamento dessa doença são:","options":{"A":"Levamizol e ivermectina.","B":"Tiabendazol e mebendazol.","C":"Pamoato de pirantel e secnidazol.","D":"Albendazol e pamoato de pirvínio."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-266362","number":"266362","sourceNumber":"266362","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"As parasitoses intestinais ainda são um grave problema de saúde, principalmente nos\npaíses em desenvolvimento. Segundo dados da Organização Mundial da Saúde (OMS), perfazem\no conjunto de doenças mais comuns do globo terrestre. Nas parasitoses podem ocorrer:","options":{"A":"Prolapso retal na ancilostomíase.","B":"Infestação com tendência à suboclusão e até obstrução intestinal na teníase.","C":"Síndrome de Loeffler na ancilostomíase, necatoríase, ascaridíase e giardíase.","D":"Anemias importantes por expoliação na ancilostomíase e necatoríase."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-266366","number":"266366","sourceNumber":"266366","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A doença celíaca (DC) é uma enteropatia imunomediada causada por sensibilidade\npermanente ao glúten em indivíduos geneticamente predispostos. Na DC é correto afirmar:","options":{"A":"A forma clássica da DC é caracterizada pela presença de constipação intestinal refratária ao\ntratamento, distensão abdominal, dor epigástrica e perda de peso.","B":"Os principais testes para o diagnóstico da doença celíaca são a calprotectina fecal e o anticorpo\nantiendomísio da classe IgG e IgM.","C":"Em pacientes com DC deve ser evitado trigo, milho, cevada e lentilha.","D":"Nas formas atípicas da DC pode ocorrer anemia por deficiência de ferro refratária à ferroterapia\noral, artralgias ou artrites e atraso puberal."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-287339","number":"287339","sourceNumber":"287339","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Estrongiloidíase, infestação pelo parasita Strongyloides stercoralis, é uma importante\nparasitose intestinal. Quanto a Estrongiloidíase podemos afirmar que? I) Em uma comunidade com\nalta infestação de Strongyloides stercoralis, a medida mais eficaz para o controle da infestação é o\ntratamento da água. II) O diagnóstico da doença é realizado pelo encontro das larvas rabditóides do\nparasita no exame de fezes, sendo raro o encontro de ovos. III) O medicamento Mebendazol é\neficaz no tratamento da Estrongiloidisse.","options":{"A":"As afirmativas I e II estão corretas.","B":"As afirmativas I e III estão corretas.","C":"Somente a afirmativa II está correta.","D":"Todas as afirmativas estão corretas."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-287858","number":"287858","sourceNumber":"287858","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) é um distúrbio de etiologia desconhecida, caracterizado por\ninflamação transmural do trato gastrointestinal. Em relação à DC, assinalar a alternativa CORRETA:","options":{"A":"A localização mais comum para a ulceração é a região anal.","B":"A maioria dos pacientes desenvolve DC no trato gastrointestinal superior.","C":"O aspecto de paralelepípedos à endoscopia é comum na colite ulcerativa, diagnóstico diferencial\nmais comum da DC.","D":"Distúrbios oculares, especialmente uveíte e episclerite, são as manifestações extraintestinais\nmais comuns.","E":"Aproximadamente 30% dos pacientes podem desenvolver fístulas."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-260696","number":"260696","sourceNumber":"260696","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual das seguintes afirmativas sobre o tratamento com glicocorticoides na retocolite\nulcerativa (RCUI) é VERDADEIRA?","options":{"A":"O glicocorticoide é indicado na indução e manutenção da remissão em pacientes com RCUI\nmoderada agrave.","B":"Doses acima do equivalente a 40?60mg/dia não são associadas a benefício clínico adicional.","C":"O hormônio adrenocorticotrófico é a alternativa mais segura ao tratamento convencional com\nglicocorticoides.","D":"A budesonida oral é uma alternativa igualmente eficaz e segura à terapia convencional com\nglicocorticoides.","E":"Os glicocorticoides tópicos (retal) são mais efetivos que a mesalazina tópica no tratamento da\ndoença distal."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-227079","number":"227079","sourceNumber":"227079","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 32 anos se queixa de dor abdominal periumbilical em cólica, que alivia após\na evacuação. Há diarreia em grande volume com\nfezes líquidas, algumas vezes contendo sangue,\nem 4 episódios ao dia, há 35 dias. Apresentou alguns episódios febris e perdeu 2 kg no período.\n\nDesconhece doenças prévias e nega o uso de medicamentos ou drogas ilícitas. O exame do\nabdômen revela dor à palpação profunda difusa,\nsem sinais de irritação peritoneal. O toque retal\nnão revela alterações. Sem outras anormalidades no restante do exame físico. Exames de\nlaboratório: hemoglobina 11,2 g/dl, leucócitos 5.460/mm³, plaquetas 230.000/mm³, proteína\n\nC-reativa 12 mg/dl, calprotectina fecal positiva. Colonoscopia: áreas de hiperemia e úlceras\nlongitudinais na mucosa do íleo terminal,\nângulo esplênico do cólon e sigmoide. Demais regiões\ncom mucosas de características normais. Considerando o caso descrito, assinale a alternativa que\napresenta o diagnóstico MAIS ADEQUADO para esse paciente:","options":{"A":"Colite isquêmica.","B":"Doença de Crohn.","C":"Retocolite ulcerativa.","D":"Síndrome do cólon irritável."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-246730","number":"246730","sourceNumber":"246730","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Dentre os abaixo, não é protozoário:","options":{"A":"Strongyloides stercoralis.","B":"Cyclospora cayetanensis.","C":"Isospora belli.","D":"Entamoeba histolytica.","E":"Giardia lamblia."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-246361","number":"246361","sourceNumber":"246361","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Menor de 7 anos, acompanhado de sua mãe, é levado à UBS com queixa de intenso\nprurido perianal diário causando irritabilidade e sono intranquilo à noite. Relato de irmão ter\napresentado o mesmo sintoma com melhora após uso de medicação. Sem anormalidades no\nexame físico. Os medicamentos que podem ser utilizados no tratamento desta patologia são:","options":{"A":"levamizol e ivermectina.","B":"tiabendazol e mebendazol.","C":"pamoato de pirantel e secnidazol.","D":"albendazol e pamoato de pirvínio."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-243036","number":"243036","sourceNumber":"243036","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Admitida na UTI geral de um hospital, paciente de 68 anos, sexo feminino, hipertensa\nhá mais de 20 anos, com quadro de queda do\nestado geral, sonolência, diarreia de início há 2 dias,\ncom grande volume e vários episódios de evacuação por dia. Pressão Arterial de 100/50 mmHgOs\nexames mostraram Na = 119; K=3,0; HTC = 38%; Hb = 13,0, Leucócitos = 12500 com 5% de\nBastões e plaquetas = 250.000 . Uréia = 75, Creatinina = 1,6 , glicose = 70 . Peso 60 Kg. Assinale a\nalternativa que melhor explica o distúrbio do sódio e a conduta para este paciente:","options":{"A":"trata-se de uma Hiponatremia Euvolêmica, sendo a melhor conduta para este paciente a\nreposição de sódio com solução salina hipertônica - NaCl a 3%.","B":"trata-se de uma Hiponatremia Euvolêmica, sendo a melhor conduta para este paciente, a\ncorreção do sódio com solução salina isotônica ? Soro Fisiológico 0,9%.","C":"trata-se de uma Hiponatremia Hipovolêmica, sendo a melhor conduta para este paciente, a\nreposição de sódio com solução salina hipertônica - NaCl a 3%.","D":"trata-se de uma Hiponatremia Hipovolêmica, sendo a melhor conduta para este paciente a\ncorreção do sódio inicialmente com solução salina isotônica ? Soro Fisiológico 0,9%.","E":"trata-se de uma Hiponatremia Hipervolêmica, sendo a melhor conduta para este paciente a\ncorreção do sódio inicialmente com solução salina isotônica ? Soro Fisiológico 0,9%."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-246793","number":"246793","sourceNumber":"246793","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Pré-escolar de 5 anos chega ao seu consultório com lesão pruriginosa, de trajeto linear\ne sinuoso, localizada em nádega. A mãe observou\nque a lesão surgiu uma semana após chegarem\ndas férias numa praia. Com base no diagnóstico mais provável, o tratamento é com:","options":{"A":"tiabendazol","B":"metronidazol","C":"anti-histamínico","D":"benzoato de benzila","E":"secnidazol"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-199508","number":"199508","sourceNumber":"199508","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação às parasitoses intestinais, assinale a alternativa INCORRETA:","options":{"A":"O Brasil, apresenta alta prevalência de parasitose, em torno de 50%, devido às más condições\nde habitação, residências sem água encanada, rede\nde esgotos e baixo nível educacional.","B":"A giardíase na sua maior parte é assintomática e o tratamento mais indicado seria o uso de\nmetronidazol ou albendazol.","C":"A anemia da ancilostomíase, o prolapso retal e a enterorragia da tricuríase, a\nhepatoesplenomegalia da esquistossomose e a\nobstrução intestinal da ascaridíase ocorrem com\nfrequência na faixa etária pediátrica.","D":"O início do uso contínuo de corticoides ou outros imunossupressores deve ser precedido de\nexames para diagnóstico de ascaridíase e de\nestrongiloidíase."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-196815","number":"196815","sourceNumber":"196815","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma paciente de 19 anos será submetida à pulsoterapia com metilprednisolona para\ntratamento de lúpus eritematoso sistêmico e não há tempo hábil para se realizar o exame\nparasitológico de fezes antes do pulso. Neste caso, qual deverá ser a medida adotada?","options":{"A":"Albendazol.","B":"Ivermectina.","C":"Nitazoxanida.","D":"Cambendazol."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-172744","number":"172744","sourceNumber":"172744","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 68 anos, hospitalizado para tratamento de pneumonia com ceftriaxone e\nclaritromicina, evoluiu com diarréia associada à antibioticoterapia, tendo sido associado\nmetronidazol ao esquema terapêutico com melhora do quadro. Três dias após a alta hospitalar o\npaciente retorna com diarréia, dor e distenção abdominal, desidratado, hipotenso, com leucocitose\ne neutrofilia ao hemograma. A tomografia computadorizada de abdome evidenciou espessamento\nda parede do reto e colon sigmóide e a retossigmoidoscopia mostrou eritema de mucosa. A\npesquisa de toxinas A e B do Clostridium difficile nas fezes foi negativa e a PCR para o mesmo\npatógeno foi positiva. Assinale o esquema de antibioticoterapia mais indicado para este caso.","options":{"A":"Piperacilina 4 g + tazobactam 0,5 g de 8 em 8 horas, por via endovenosa, durante 10 dias.","B":"Amoxicilina 500 mg + clavulanato 125 mg de 8 em 8 horas, por via oral, durante 10 dias.","C":"Vancomicina 250 mg de 6 em 6 horas, por via oral, durante 10 dias.","D":"Levofloxacino 500 mg por via oral a cada 24 horas, por 7 dias."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-188006","number":"188006","sourceNumber":"188006","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Mulher, 34 anos apresentando períodos de dor abdominal tipo cólica de leve a\nmoderada intensidade em hipogástrio associada a\ndiarreia intercalando períodos assintomáticos.\nEsse quadro surgiu há 4 meses e os sintomas estão mais frequentes e de maior intensidade. No\núltimo mês, apresentou perda ponderal, astenia e mal-estar. Hoje vem em consulta sem queixa\nálgica para nova avaliação e mostrar exames solicitados por outro médico. Exame físico abdominal\nnormal. Hemograma evidencia anemia sem leucocitose. Sorologia negativa para HIV, positiva para\nanticorpos anti-Saccharomyces cerevisiae (ASCA) e negativa para anticorpos perinuclear\n\nanti-citoplasma de neutrófilos (pANCA). Estudo radiológico com bário do intestino delgado revela\naparência de padrão de chão forrado com paralelepípedo em várias áreas de intestino delgado e\nsinais de úlceras lineares em íleo terminal. Tomografia computadorizada evidencia acentuado\nespessamento transmural de aspecto salteado em vários segmentos de intestino delgado. Qual é o\ndiagnóstico provável e a conduta indicada?","options":{"A":"Histoplasmose intestinal - Fluconazol oral.","B":"Infecção por Clostridium difficile - Vancomicina endovenoso ou metronidazol oral.","C":"Tuberculose intestinal - Ressecção intestinal e confecção de ileostomia.","D":"Síndrome de Peutz-Jeghers - Ressecção intestinal extensa.","E":"Doença inflamatória intestinal - Budesonida e metronidazol orais."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-172774","number":"172774","sourceNumber":"172774","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 25 anos, sexo masculino, há 4 meses apresentando quadro de dor\nabdominal, geralmente em quadrante inferior\ndireito, quase diária, associada à diarreia, cerca de 10\nepisódios por dia, com fezes líquidas, sem elementos anormais, fadiga e emagrecimento de 10 kg\nnesse período. Refere ainda saída de secreção fluida/purulenta por pequeno orifício em região\nperianal. Relata que na última semana vem apresentando piora da dor abdominal, associada à\nfebre (39-39,5°C). Ao exame físico apresenta dor importante à palpação em quadrante inferior\ndireito, com descompressão dolorosa. Diante do quadro clínico exposto, qual a principal hipótese\ndiagnóstica?","options":{"A":"Síndrome da imunodeficiência adquirida associada à tuberculose intestinal.","B":"Retocolite ulcerativa complicada com megacólon tóxico.","C":"Doença de Crohn complicada com abscesso em íleo terminal.","D":"Doença diverticular complicada com diverticulite aguda."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-187475","number":"187475","sourceNumber":"187475","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Dentre as alternativas abaixo, assinale a que apresenta somente parasitas com ciclo\npulmonar que podem levar a sintomatologia característica de Síndrome de Loefller:","options":{"A":"Ascaris lumbricoides e Giardia lamblia.","B":"Strongyloides Stercoralis e Isospora belli.","C":"Trichuris trichiura e Hymenolepis nana.","D":"Enterobius vermiculares e Entamoeba histolytica.","E":"Necator americanus e Ancylostoma duodenale."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-174390","number":"174390","sourceNumber":"174390","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem 25 anos, apresenta diarréia com sangue há 2 meses. Colonoscopia evidencia\nmucosa de reto e sigmoide distal de aspecto enentematoso e friável ao toque do aparelho, com\npequenas ulcerações rasas; cujas biópsias\n\ndemonstraram retite crônica com depleção de células caliciformes e formação de microabscessos\nde cripta. Em relação ao diagnóstico mais\nprovável neste doente, são apresentadas as seguintes\nafirmações: I- Avaliação complementar do intestino delgado é desnecessária neste caso.; II- A\ndroga de primeira escolha para o início do tratamento é a prednisona.; III- É necessário usar\nantibiótico no início do tratamento pelo achado histopatológico de retite e microabscessos de\ncripta.\nAssinale a alternativa correta:","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"Todas estão corretas."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-172837","number":"172837","sourceNumber":"172837","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Lactente de um ano e meio chegou ao pronto socorro desidratado e com história de ter\niniciado há dois dias diarreia, vômito e febre alta. A diarreia ocorre várias vezes por dia, com\nfezes\nlíquidas, volumosas, amareladas, com caráter explosivo e com grande perda hidroeletrolítica. Qual\né o provável agente etiológico e/ou a conduta a ser prescrita?","options":{"A":"Provavelmente a diarreia é viral e pela clínica, os adenovírus entéricos são a causa mais\nprovável.","B":"Provavelmente a diarreia é causada por agentes parasitários e o mais frequentemente envolvido\né a Entamoeba histolytica.","C":"Provavelmente a diarreia é por rotavírus, que é o principal responsável por episódios de diarreia\naguda, tanto nos países desenvolvidos como naqueles em desenvolvimento, representando 40%\ndos casos graves com hospitalização.","D":"Provavelmente a diarreia é por Shigella. Hidratação venosa e ceftriaxona devem ser prescritas\nimediatamente."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-162560","number":"162560","sourceNumber":"162560","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um indivíduo com doença hepática por Schistosoma mansoni está mais propenso a\ndesenvolver qual das seguintes características, usualmente presente nos cirróticos?","options":{"A":"Ascite.","B":"Varizes esofageanas.","C":"Varizes de fundo gástrico.","D":"Icterícia.","E":"Spiders (telangiectasias)."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-162594","number":"162594","sourceNumber":"162594","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa CORRETA em relação à doença celíaca:","options":{"A":"O HLA B27 é um importante fator de risco para a doença.","B":"A detecção dos anticorpos IgA antitransglutaminase é útil nos pacientes portadores de\ndeficiência seletiva\n\nde imunoglobulina A.","C":"Osteopenia é encontrada em mais da metade dos pacientes.","D":"Linfoma do manto intestinal é uma complicação comum de pacientes que não aderem à dieta\nsem glúten.","E":"A biópsia duodenal revela infiltração da lâmina própria por eosinófilos."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-155340","number":"155340","sourceNumber":"155340","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a frase errada sobre retocolite ulcerativa:","options":{"A":"O p-ANCA é um marcador sorológico frequente na doença.","B":"Fatores genéticos são importantes na origem da doença.","C":"É mais frequente em não fumantes.","D":"Um dos mecanismos de ação dos agentes biológicos usados no tratamento é a modulação ou\ninibição de citocinas.","E":"As células T na mucosa colônica não interferem no processo inflamatório."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-155452","number":"155452","sourceNumber":"155452","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem, 68 anos, internado na UTI há 2 semanas devido a DPOC exacerbada, com\nuso recente de antibióticos e\ncorticosteroides, apresenta quadro de febre, dor abdominal e diarréia\naquosa há 1 semana, com muco e sem sangue nas fezes. A principal hipótese diagnóstica e\npropedêutica investigativa a serem consideradas nesse momento são:","options":{"A":"Colite pseudomembranosa e solicitação das toxinas A e B do Clostridium nas fezes.","B":"Doença Inflamatória intestinal e solicitação de calprotectina fecal.","C":"Colite isquêmica e solicitação de colonoscopia.","D":"Colite por citomegalovírus e solicitação de sorologia.","E":"Estrongiloidíase disseminada e solicitação de EPF."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-148538","number":"148538","sourceNumber":"148538","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"As parasitoses intestinais constituem um importante problema de saúde pública, pois\ncontribuem para as taxas de morbidade e mortalidade de pessoas em todo o mundo,\nespecialmente em países em desenvolvimento. Leia as sentenças abaixo e marque a CORRETA:","options":{"A":"O Ancylostoma duodenale pode causar prolapso retal.","B":"Ascaris lumbricoides e o Strongyloides stercoralis têm manifestações pulmonares que se\nassemelham a síndrome de Loeffler.","C":"O Trichuris trichiura pode causar prurido anal e gastrite com dor epigástrica em cólica ou\nqueimação.","D":"O Enterobius vermicularis pode causar hipoalbuminemia e hepatoesplenomegalia.","E":"O Strongyloides stercoralis pode levar a obstrução intestinal aguda."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-148550","number":"148550","sourceNumber":"148550","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente submetido a apendicectomia laparoscopica, retornou ao ambulatório com\nexame anatomopatológico evidenciando neoplasia.\nPensando na maior incidência, qual o provável\ntipo histológico?","options":{"A":"Adenocarcinoma.","B":"Tumor carcinoide.","C":"Linfoma.","D":"Pseudomixoma.","E":"Hemangioma."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-148566","number":"148566","sourceNumber":"148566","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente 70 anos, feminino, internado em Unidade de Terapia Intensiva há 15 dias para\ntratamento de pneumonia comunitária grave, já em uso de antibiótico há 10 dias, evoluiu com\nquadro de distenção abdominal, diarreia e piora de leucocitose. A retossigmoidoscopia rígida foi\nidentificada mucosa inflamada coberta por pseudo membranas. Relativo ao caso afirma-se, exceto:","options":{"A":"O provável diagnóstico é colite pseudomembranosa.","B":"Exame de substânicas redutores nas fezes têm alta sensibilidade e especificidade no\ndiagnóstico da colite pseudomembranosa.","C":"A bactéria mais envolvida com a colite pseudomembranosa é o Clostridium difficile.","D":"O uso de vancomicina ou metronidazol está indicado quando diagnosticado colite\npseudomembranosa.","E":"A taxa de mortalidade está associada a mais de 50% dos casos de colite pseudomembranosa\nonde a cirurgia se fizer necessária."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-126880","number":"126880","sourceNumber":"126880","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"L.M.O.L., 34 anos, sexo feminino, apresenta história de diarreia com tenesmo, dor\nabdominal difusa, emagrecimento, anemia e febre diária. Realizado o exame de fezes este\napresenta presença de pus e sangue, e os exames laboratoriais evidenciam discreta leucocitose\n(sem desvio a esquerda), velocidade de hemossedimentação elevada, hematócrito baixo,\nhemoculturas negativas, p-ANCA positivo. Considerando o caso descrito, o diagnóstico CORRETO\na ser dado ao paciente é de:","options":{"A":"Retocolite ulcerativa.","B":"Doença intestinal de origem infecciosa.","C":"Vasculite do intestino delgado.","D":"Síndrome da imunodeficiência adquirida."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-127157","number":"127157","sourceNumber":"127157","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A tríade clássica \"dermatite, diarreia e demência\", define uma doença carencial\ndecorrente da deficiência de:","options":{"A":"Tiamina.","B":"Piridoxina.","C":"Cobalamina.","D":"Niacina.","E":"Biotina."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-131620","number":"131620","sourceNumber":"131620","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa errada:","options":{"A":"Carcinoma colorretal que invade a submucosa e apresenta 2 ganglios positivos e nehuma\nmetástase à distância é classificado como T1N1M0, e portanto com estadiamento III.","B":"O risco de câncer é maior em adenomas vilosos que em adenomas tubulares.","C":"O fígado é um local frequente de manifestação extraintestinal de doença inflamatória intestinal.","D":"Apendicite aguda é a causa mais frequente de abdômen agudo cirúrgico no idoso.","E":"Síndrome de Ogilvie é um distúrbio funcional em que o cólon se apresenta extremamente\ndilatado na ausência de uma obstrução mecânica."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-127167","number":"127167","sourceNumber":"127167","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa em que está descrita uma característica anatomo-patológica da\nRetocolite Ulcerativa Idiopática:","options":{"A":"Lesões em salto.","B":"Pseudopólipos.","C":"Aspecto de cobblestone.","D":"Granuloma epitelióide não caseoso.","E":"Lesão restrita a mucosa."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-137839","number":"137839","sourceNumber":"137839","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação as doenças inflamatórias intestinais podemos afirmar que:","options":{"A":"A doença de Crohn é mais prevalente no sexo feminino.","B":"A doença de Crohn é mais comum na raça negra.","C":"Não há fatores genéticos envolvidos com a maior ocorrência da das doenças intestinais.","D":"A idade ao diagnóstico da retocolite ulcerativa idiopática é entre 40 ? 60 anos.","E":"O fumo reduz o risco de desenvolvimento da Doença de Crohn."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-131691","number":"131691","sourceNumber":"131691","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Pré-escolar de 5 anos chega em seu consultório com lesão em pé esquerdo\neritematosa, linear serpiginosa,\nprurigionosa, que se assemelha a um túnel elevado. A mãe relata\nque leva o filho à praia com frequência. Baseado no diagnóstico provável, você vai prescrever como\ntratamento:","options":{"A":"Eritromicina.","B":"Benzoato de Benzila.","C":"Penicelina.","D":"Metronidazol.","E":"Tiabenzadol."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-127246","number":"127246","sourceNumber":"127246","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A eosinofilia é provocada pelas seguintes helmintos, EXCETO:","options":{"A":"Strongyloides stercoralis.","B":"Enterobius vermicularis.","C":"Schistosoma mansoni.","D":"Ancylostoma duodenale.","E":"Ascaris lumbricoides."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111653","number":"111653","sourceNumber":"111653","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No diagnóstico da doença celíaca em indivíduos pertencentes a grupo de risco ou com\napresentação não clássica, deve ser realizado inicialmente","options":{"A":"dosagem de IgA total, IgA antiendomísio e antitransglutaminase.","B":"dosagem de IgG antigliadina, endomísio e trasglutaminase.","C":"dosagem de IgG antigliadina e biópsia de porção distal do duodeno.","D":"dosagem de IgA antigliadina desaminada e IgG antigliadina.","E":"dieta de exclusão de glúten por 12 semanas."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-77486","number":"77486","sourceNumber":"77486","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É INCORRETO afirmar sobre parasitoses:","options":{"A":"Uso de corticosteroides em doses elevadas constitui fator de risco para o desenvolvimento de\nestrongiloidíase disseminada.","B":"O quadro de esquistossomose aguda pode se apresentar com dermatite causada pela\npenetração de cercária na pele.","C":"O manejo clínico da neurocisticercose é baseado no uso de albendazol. Somente em casos de\nhipertensão intracraniana deve ser utilizada corticoterapia, já que a mesma pode provocar\ndisseminação do parasita no sistema nervoso central.","D":"A infestação do Ancylostoma duodenale pode se manifestar com o aparecimento de tosse seca,\numa vez que a mesma cursa com a passagem do\nparasita pelo pulmão durante seu ciclo de vida no\nhospedeiro.","E":"Pacientes homossexuais masculinos apresentam incidência mais elevada de colite amebiana em\nrelação à população geral."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-77500","number":"77500","sourceNumber":"77500","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação às doenças inflamatórias intestinais, é CORRETO afirmar que:","options":{"A":"O tabagismo está associado a maior risco de desenvolvimento de retocolite ulcerativa.","B":"O polimorfismo do gene NOD2/CARD15 confere maior susceptibilidade à doença de Crohn aos\nseus portadores.","C":"As manifestações reumatológicas são frequentes em pacientes com doença inflamatória\nintestinal e apresentam sempre relação com a\natividade da doença.","D":"O risco de desenvolvimento de adenocarcinoma colorretal em pacientes com retocolite ulcerativa\né significantemente maior que o da população em\ngeral, porém o câncer de cólon que ocorre na\nretocolite ulcerativa em geral tem evolução indolente.","E":"A detecção positiva do ASCA e do p-ANCA tem boa sensibilidade e especificidade para o\ndiagnóstico de doença de Crohn."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-88868","number":"88868","sourceNumber":"88868","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 21 anos apresenta há 2 anos poliartralgia, diarreia e emagrecimento. Exame\nfísico: micropoliadenopatia, descorado +\\+++. Ausência de visceromegalias. Fístula perianal.\n\nExames : HIV-ELISA: duvidoso, HB=11 g/dl, VCM= 102 , leucócitos = 3.000 (4 bastonetes, 65\nsegmentados, 20 linfócitos, 7 eosinófilos e 4 basófilos), Plaquetas 80.000, VHS= 40 mm (n < 12).\nTrânsito intestinal: edema em mosaico de delgado, dilatação de jejuno com estase; estreitamento e\nespessamento de íleo. Retossigmoidoscopia normal. A principal hipótese diagnóstico para o caso é:","options":{"A":"Tuberculose intestinal","B":"Doença de Crohn","C":"Imunodeficiência adquirida.","D":"Retocolite ulcerativa.","E":"Colite isquêmica"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-88859","number":"88859","sourceNumber":"88859","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O item abaixo que reúne as parasitoses intestinais com potencial de infestação\nextraintestinal é:","options":{"A":"Strongyloides stercoralis, Entamoeba histolytica e Enterobius vermicularis.","B":"Entamoeba histolytica, Strongyloides stercoralis e Ascaris lumbricoides.","C":"Taenia saginata, Ascaris lumbricoides e Strongyloides stercoralis.","D":"Necator americanus, Giardia lamblia e Enterobius vermicularis.","E":"Nenhuma das alternativas anteriores."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-59377","number":"59377","sourceNumber":"59377","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre as parasitoses intestinais marque a alternativa CORRETA:","options":{"A":"A anemia ocorre raramente na ancilostomíase.","B":"A ascaridíase é a parasitose que menos comumente cursa com a síndrome de Löeffler.","C":"A esquistossomose é endêmica no Rio Grande do Sul, na região de Lagoa dos Patos.","D":"A fibrose periportal ou de Symmers é uma característica peculiar da lesão hepática da\nesquistossomose.","E":"O tiabendazol é a droga de escolha para o tratamento da estrongiloidíase, administrado em dose\núnica e com repetição após 10 a 15 dias."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-59076","number":"59076","sourceNumber":"59076","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Quanto à Doença Celíaca (DC), assinale a afirmativa CORRETA.","options":{"A":"Os portadores de DC podem tomar cerveja.","B":"As crianças com manifestações precoces da DC terão pouca sintomatologia na vida adulta.","C":"Pacientes com DC podem apresentar-se clinicamente com Diabetes Mellitus e doenças da\ntireoide.","D":"Na DC a absorção de gordura é normal.","E":"Após o tratamento, com a negativação dos autoanticorpos, podemos reintroduzir gradativamente\no glúten na dieta do paciente celíaco."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-43960","number":"43960","sourceNumber":"43960","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a frase errada sobre Retocolite Ulcerativa Inespecífica (RCUI).","options":{"A":"Artralgia ou artrite é manifestação extraintestinal mais frequente em portadores de (RCUI).","B":"p-ANCA, um marcador para RCUI, pode ser encontrado em pessoas normais.","C":"Megacólon tóxico é mais comum na RCUI do que na doença de Crohn.","D":"O tumor de cólon que se desenvolve em portadores de RCUI tem baixa agressividade.","E":"Os pacientes mais jovens são aqueles em que as complicações da RCUI são mais frequentes e\ngraves."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-44011","number":"44011","sourceNumber":"44011","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Alguns helmintos parasitam o homem e têm ciclo pulmonar, com manifestações\nrespiratórias semelhantes a quadro de asma brônquica\nnas crianças, conhecidas como Síndrome\nde Löeffler. Qual dos helmintos abaixo não apresenta ciclo pulmonar?","options":{"A":"Ancylostoma duodenale.","B":"Necator americanus.","C":"Schistosoma mansoni.","D":"Trichuris trichiura.","E":"Ascaris lumbricoides."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-32411","number":"32411","sourceNumber":"32411","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente jovem, morador de zona urbana, com história de viagem para área rural e\nbanhos de rio há 30 dias, está apresentando\nquadro clínico de febre, sudorese, prostração,\ncalafrios, dor abdominal, diarreia, tosse, hepatomegalia e esplenomegalia. Os exames laboratoriais\nrevelam discreta elevação de transaminases e leucocitose com eosinofilia. O diagnóstico mais\nprovável é:","options":{"A":"Hepatite viral.","B":"Leptospirose.","C":"Leishmaniose visceral.","D":"Esquistossomose aguda.","E":"Febre tifoide."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-32487","number":"32487","sourceNumber":"32487","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Foi identificada uma comunidade com alta infestação de Strongyloides stercoralis. Qual\nmedida teria melhor repercussão para o controle desta infestação?","options":{"A":"Cuidado com a água.","B":"Melhor controle dos alimentos.","C":"Higiene das mãos.","D":"Tratamento de esgotos.","E":"Tratamento dos infectados."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-27404","number":"27404","sourceNumber":"27404","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente do sexo feminino, 16 anos foi encaminhada pelo dentista à consulta pediátrica\npor úlceras aftosas recorrentes. Relato de\nirregularidade do ciclo menstrual e dois abortos\nespontâneos. Ao verificar consultas anteriores, há relato de constipação intestinal refratária ao\ntratamento. Ao exame físico apresenta baixa estatura. Em relação ao caso clínico descrito, qual o\nexame padrão-ouro para o diagnóstico dessa doença?","options":{"A":"Anticorpo antiendomísio.","B":"Biópsia do intestino delgado.","C":"Ultrassonografia de abdome.","D":"Colonoscopia.","E":"Anticorpo antitransglutaminase."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-9393","number":"9393","sourceNumber":"9393","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É fator de risco para doença associada ao Clostridium difficile, em idosos internados em\nenfermaria de hospital geral, para tratamento com antibióticos.","options":{"A":"Uso de heparina profilática subcutânea.","B":"Uso de laxativos à base de óleo mineral.","C":"Uso de antagonistas dos receptores H2.","D":"Uso de bromoprida.","E":"Uso de metronidazol."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-9425","number":"9425","sourceNumber":"9425","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Quanto à transmissão dos parasitas intestinais é INCORRETO:","options":{"A":"Necator americanus: somente se adquire por via percutânea.","B":"Ancylostoma duodenale: pode ser adquirido por via oral.","C":"Strongyloides stercoralis: ocorre penetração ativa de larvas filarioides na pele.","D":"Tricocephalus trichiurus: a infecção ocorre pela ingestão de ovos embrionados.","E":"Tenia solium: a infecção ocorre pela ingestão de larvas e ovos."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-8110","number":"8110","sourceNumber":"8110","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Dos agentes abaixo assinale o causador de diarreia aguda inflamatória.","options":{"A":"Giardia.","B":"Rotavírus.","C":"E.coli enterotoxigênica.","D":"Shigella.","E":"Vibrião colérico."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-321606","number":"321606","sourceNumber":"321606","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Nos últimos 3 meses, uma mulher de 45 anos de idade relatou que sua pele se tornou\nprogressivamente amarela. No exame físico, ela estava febril e apresentava icterícia esclerótica e\ngeneralizada. As análises laboratoriais mostravam bilirrubina sérica total de 8,9 mg/dl; bilirrubina\ndireta de 6,8 mg/dl; AL sérica total de 125 U/L; e AST sérica de 108 U/L. A amostra da biópsia\nhepática mostrou características histológicas de colangite esclerosante. Qual é a doença do trato\ngastrintestinal mais provável de coexistir com a doença hepática?","options":{"A":"Pancreatite crônica.","B":"Diverticulose.","C":"Colite ulcerativa.","D":"Ulceração péptica."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-294260","number":"294260","sourceNumber":"294260","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Ao se avaliar um paciente com doença de Crohn moderada a grave, com proposta de\ntratamento com terapia biológica anti-TNF, há indicação absoluta da realização de exames\nlaboratoriais. No estadiamento desse paciente, qual exame é imprescindível?","options":{"A":"Teste alérgico cutâneo.","B":"PPD.","C":"Calprotectina fecal.","D":"Ferritina."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-353777","number":"353777","sourceNumber":"353777","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O protozoário que provoca manifestações clínicas de eritema, edema ou pápulas na\npele na fase inicial, dor epigástrica, alterações do apetite, náuseas, vômitos e flatulência na fase\naguda da infecção e anemia hipocrômica e microcítica, que costuma manifestar-se por lassidão,\ndispneia, taquicardia e cefaleia na fase crônica, é:","options":{"A":"Ascaris lumbricoides.","B":"Ancylostoma duodenale.","C":"Trichuris trichiura.","D":"Enterobius vermicularis."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-353843","number":"353843","sourceNumber":"353843","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No contexto de mecanismos causadores de diarreia, sobre o mecanismo osmótico, é\nCORRETO afirmar:","options":{"A":"É caracterizado por distúrbios no transporte eletrolítico, conduzindo principalmente à secreção\naumentada de eletrólitos e água.","B":"É primariamente causado por um aumento na secreção de eletrólitos e água na luz intestinal.","C":"É decorrente da falência na digestão enzimática de nutrientes ou em sua absorção e transporte.","D":"É caracterizado pela ingestão de substâncias mal absorvidas que são osmoticamente ativas,\nlevando à retenção de fluido intraluminal."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-353839","number":"353839","sourceNumber":"353839","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A alternativa que indica a parasitose intestinal responsável por causar anemia ferropriva\ndevido ao hematofagismo exercido pelos\nvermes adultos é:","options":{"A":"Enterobíase causada por Enterobius vermicularis.","B":"Ancilostomíase causada por Ancylostoma duodenale e Necator americanus.","C":"Giardíase causada por Giardia Lamblia.","D":"Estrongiloidíase causada por Strongyloides stercoralis."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-355628","number":"355628","sourceNumber":"355628","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação aos tumores carcinoides (TCs), está correto afirmar que:","options":{"A":"Tipicamente, os TCs do intestino médio produzem baixos teores de serotonina","B":"Os TCs do intestino delgado são multicêntricos em apenas 2% a 3% dos pacientes","C":"Os TCs do intestino inferior raramente produzem serotonina, mas podem produzir outros\nhormônios, como a somatostatina","D":"Apenas 5% dos TCs do íleo estão associados a metástases","E":"Os TCs do intestino anterior têm como característica a produção de altos níveis de serotonina"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-355605","number":"355605","sourceNumber":"355605","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma menina de onze anos de idade apresenta dor abdominal recorrente há três meses,\nacompanhada de febre, perda de peso e diarreia de pouco volume, com sangue e muco nas fezes,\nalém de tenesmo retal. Os exames revelam anemia microcítica e hipocrômica e leucocitose\ndiscreta. O VHS, a proteína C-reativa e a calprotectina fecal estão elevados. À colonoscopia, foram\nvisualizadas lesões ulceradas e aftoides entremeadas com áreas de mucosa normal, com aspecto\nde \"pedras de calçamento\". Em relação a esse caso hipotético, assinale a alternativa correta:","options":{"A":"Se forem encontrados granulomas não caseosos na biópsia, o diagnóstico de Doença de Crohn\nserá confirmado.","B":"A calprotectina fecal elevada já confirma doença inflamatória intestinal.","C":"A análise dos anticorpos Asca e p-Anca teriam eliminado a necessidade da colonoscopia.","D":"O tratamento deve ser iniciado com infliximabe.","E":"O tratamento com mesalazina deve ser reservado apenas para os casos mais graves."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-354831","number":"354831","sourceNumber":"354831","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Quanto ao tratamento de um paciente com diarreia aguda, o uso de","options":{"A":"agentes antidiarreicos são primeira linha no tratamento.","B":"probióticos para encurtar o tempo de diarreia são aceitáveis.","C":"antibióticos são indicados quando há presença de sangue e tem no sulfametoxazol associado ao\ntrimetoprim, a primeira linha.","D":"soro caseiro pode ser usado para tratar a desidratação, sendo uma opção custo-efetiva."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-366949","number":"366949","sourceNumber":"366949","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente de 45 anos procura atendimento médico por apresentar episódios\nrecorrentes de ruborização facial, diarreia e\ndispneia. Durante a investigação, é identificada uma\nlesão no íleo terminal. Qual é o diagnóstico mais provável?","options":{"A":"Tumor de GIST (Tumor do estroma gastrointestinal).","B":"Tumor carcinoide.","C":"Linfoma gastrointestinal.","D":"Pólipos adenomatosos."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-353855","number":"353855","sourceNumber":"353855","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A falência intestinal é definida como a redução da função intestinal abaixo do mínimo\nnecessário para a absorção de macronutrientes e/ou água e eletrólitos. Sobre falência intestinal: I.\nA causa mais frequente de falência intestinal é a síndrome do intestino curto. II. Estados\nmalabsortivos é uma das principais causas de falência intestinal. III. A maioria dos pacientes\ndesenvolve a síndrome do intestino curto no período neonatal. Das proposições acima:","options":{"A":"Apenas I e II estão corretas.","B":"Apenas I está correta.","C":"Apenas I e III estão incorretas.","D":"Todas estão corretas."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-342604","number":"342604","sourceNumber":"342604","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente portador de retocolite ulcerativa será submetido a laparotomia em virtude\nde perfuração intestinal. A antibioticoterapia\ninclui cobertura para germes Gram negativos e\nanaeróbios. Com relação a estes últimos, a principal bactéria relacionada à morbimortalidade pós-\noperatória e o antibiótico de escolha são:","options":{"A":"Clostridium perfringens; cloranfenicol","B":"Bifidobacterium; linezolida","C":"Bacteroides fragilis; metronidazol","D":"enterococo; vancomicina"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-330091","number":"330091","sourceNumber":"330091","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente, 3 anos, sexo feminino, com relato de prurido perineal e perianal há 2\nsemanas, mais comum à noite, não há relato de\nfebre, diarreia ou vômito. Exame físico constata\nregião perianal irritada e avermelhada, com tônus do esfíncter anal normal sem evidências de\ntrauma de penetração, região perineal avermelhada e escoriada e secreção vaginal esbranquiçada.\nSobre o caso, é INCORRETO afirmar:","options":{"A":"Paciente apresenta história típica de infecção por oxiúros.","B":"Há a possibilidade de abuso sexual, embora improvável pelo histórico colhido.","C":"Os sintomas podem ser causados por higiene precária.","D":"Os sintomas podem ser causados por limpeza exagerada."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-337430","number":"337430","sourceNumber":"337430","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente institucionalizado cronicamente apresentando diarreia invasiva, febre e dor\nabdominal. Histórico de uso de múltiplos antibióticos. Pesquisadas toxinas nas fezes com resultado\npositivo. O agente etiológico associado à colite acima descrita é:","options":{"A":"Escherichia coli","B":"Klebsiella pneumoniae","C":"Clostridium difficile","D":"Staphylococcus aureus"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-334143","number":"334143","sourceNumber":"334143","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O intestino delgado é responsável por uma importante parte da digestão alimentar. É\ncomposto por duodeno, jejuno e ileo. No intraoperatório, algumas características são mais\nevidentes em cada segmento. O achado anatômico mais característico de jejuno é:","options":{"A":"Presenças de apêndices epiplóicos.","B":"Mesentério com várias arcadas vasculares e vasos retos curtos.","C":"Mesentério com poucas arcadas vasculares com vasos retos longos.","D":"Mesentério com única arcada vascular e vasos retos longos."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-334817","number":"334817","sourceNumber":"334817","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Lactente 1 ano e 9 meses de idade, apresentando diarreia e perda de peso, fezes\nvolumosas, explosivas, sem muco ou sangue em\nmédia 6 vezes ao dia acompanhada de distensão\nabdominal e assadura perianal. Recebeu aleitamento materno exclusivo até 6 meses de vida e, a\npartir daí, iniciou com alimentação complementar. Atualmente está em uso de leite materno e dieta\nhabitual da família. Condições socioeconômicas e sanitárias adequadas. Ao exame físico\n\nencontra-se desnutrido, hipocorado e hipotrofia da região glútea. Considerando que, neste caso\nrelatado, o diagnóstico é de doença celíaca, qual é a abordagem clínica a ser adotada?","options":{"A":"Excluir o glúten da dieta e programar endoscopia com biópsia duodenal.","B":"Solicitar dosagem de IgA sérica e antitransglutaminase tecidual IgA e endoscopia com biópsia\nduodenal imediatamente.","C":"Abordagem sem biópsia é permitido para crianças com dosagem de IgA sérica normal e com\nvalores de antitransglutaminase tecidual IgA> 10X o LSN (limite superior da normalidade) e\nantiendomísio IgA positivo em uma segunda amostra de sangue.","D":"Retirar o glúten para o resto da vida, não sendo permitido o diagnóstico sem a realização de\nendoscopia com biópsia duodenal."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-334150","number":"334150","sourceNumber":"334150","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 85 anos, diabético e hipertenso, em tratamento de pneumonia hospitalar, foi\ninternado há 18 dias devido a uma fratura de fêmur. O médico assistente iniciou o Piperacilina com\nTazobactan e após 2 dias o paciente apresentou diarreia aquosa em grande quantidade, dor\nabdominal e febre. Nos exames laboratoriais, apresentou leucocitose e proteína C reativa\nultrassensível elevada. Solicitado novos exames, apresentava lipase, amilase e lactato normais.\n\nQual é o diagnóstico mais provável e tratamento?","options":{"A":"Colite pseudomembranosa / suspender antibiótico e iniciar probiótico.","B":"Colecistite alitiasica / ampliação do esquema antibiótico.","C":"Colite pseudomembranosa / iniciar metronidazol oral.","D":"Diarreia osmótica dos antibióticos / suspender antibiótico."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-313184","number":"313184","sourceNumber":"313184","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale (V) para Verdadeiro e (F) para Falso com relação ao diagnóstico diferencial\nentre a retocolite ulcerativa inespecífica\n(RCUI) e a Doença de Crohn (DC): ( ) A RCUI sempre\nacomete o reto, mas não causa doença perianal. ( ) A DC frequentemente acomete o reto e causa\ndoença perianal. ( ) A DC raramente promove acometimento transmural. ( ) A RCUI frequentemente\npromove acometimento transmural. ( ) Na RCUI não ocorrem úlceras aftosas na mucosa do trato\ndigestivo. Assinale a sequência correta:","options":{"A":"V, F, V, F, V","B":"V, V, F, F, V","C":"F, V, F, V, V","D":"V, V, F, V, F"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-317935","number":"317935","sourceNumber":"317935","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente portador de retocolite ulcerativa há cinco anos submetido a colonoscopia com\ndoença classificada como Mayo 3, apresentando\npiora clínica com presença de diarreia\nmucossanguinolenta e cólicas abdominais, em uso de mesalazina 4,8 g por dia. Nesse caso, a\nconduta que leva ao melhor resultado na indução de remissão da atividade de doença é:","options":{"A":"aumentar a dose de salicilato.","B":"iniciar imunossupressão com tiopurina.","C":"iniciar corticoterapia.","D":"não aguardar resposta ao tratamento clínico e indicar colectomia do segmento acometido."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-316313","number":"316313","sourceNumber":"316313","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação às doenças inflamatórias intestinais, retocolite ulcerativa e doença de\nCrohn, não é correto afirmar:","options":{"A":"Os pacientes com doença de Crohn estão predispostos à formação de cálculos biliares e nota-se\numa frequência aumentada de formação de\ncálculos de oxalato nas vias urinárias.","B":"A fertilidade das mulheres é normal na retocolite ulcerativa, porém pode estar comprometida na\ndoença de Crohn.","C":"Pacientes com retocolite ulcerativa p-ANCA positivos possuem frequentemente curso menos\nagressivo da doença.","D":"A incidência de pioderma grangrenoso é mais alta na retocolite ulcerativa comparada à doença\nde Crohn."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-317165","number":"317165","sourceNumber":"317165","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Maria de Lourdes 36 anos procura UBS com queixa de diarréia há 6 meses, fezes\nfétidas, com visualização de gotículas de gordura e restos alimentares. Teve emagrecimento\nimportante e vem se sentindo sem disposição, cansaço fácil e memória ruim. Os exames\nmostraram anemia hipocromica e microcítica e presença de gordura fecal. Anticorpos\nantitransglutaminase tecidual foram positivos, com relação ao caso acima podemos afirmar\ncorretamente exceto:","options":{"A":"Está indicada realização de EDA com biopsia de delgado;","B":"A presença de atrofia de vilosidades e hiperplasia de criptas confirma o diagnóstico de Doença\nCelíaca;","C":"A paciente apresenta uma doença disabsortiva;","D":"Se confirmado diagnóstico de Doença Celiaca esta indicada a prescrição de dieta totalmente\nisenta de glúten, por toda a vida."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-300826","number":"300826","sourceNumber":"300826","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A diarreia aguda é a perda de fluidos e eletrólitos pelas fezes, com presença de\nevacuações amolecidas mais que 3 vezes ao dia\ndentro de 24 horas. A investigação deve ser feita\nem pacientes com diarreia crônica e perda de peso. Nesse contexto, a investigação que identifica\ngiardíase é:","options":{"A":"Protoparasitológicos (PPFs) ? 3 amostras.","B":"pH fecal e pesquisa de substâncias redutoras.","C":"Gordura nas fezes.","D":"Coprocultura."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-315798","number":"315798","sourceNumber":"315798","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É um análogo da somatostatina que inibe a secreção de alguns hormônios hipofisários\ne gastrointestinais, aumentando a resistência\narteriolar esplâncnica, diminuindo o fluxo\ngastrointestinal e, por consequência, o fluxo linfático. Pode ser utilizado no tratamento de\nhemorragias digestivas, quilotórax, hipertensão portal e para tratamento de alguns tumores\nneuroendócrinos.","options":{"A":"Ácido tranexâmico.","B":"Glargina.","C":"Peptideo vasointestinal.","D":"Octreotide."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-314129","number":"314129","sourceNumber":"314129","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É tratamento de primeira linha para teníase:","options":{"A":"Albendazol.","B":"Ivermectina.","C":"Mebendazol.","D":"Praziquantel."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-300979","number":"300979","sourceNumber":"300979","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O achado anatômico mais característico de jejuno, que o diferencia do duodeno e íleo\né:","options":{"A":"Presenças de apêndices epiploicos.","B":"Mesentério com várias arcadas vasculares e vasos retos curtos.","C":"Mesentério com única arcada vascular e vasos retos longos.","D":"Mesentério com poucas arcadas vasculares com vasos retos longos."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-308292","number":"308292","sourceNumber":"308292","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Gael, nove anos, há 10 dias com quadro de prurido anal diário, durante a madrugada, o\nque faz perder o sono. Ao exame físico, sem\nalterações. Qual o agente e medicamento\nrespectivamente do quadro acima?","options":{"A":"Ascaris lumbricoides e ivermectina.","B":"Trichuris trichiura e mebendazol.","C":"Strongyloides stercoralis e secnidazol.","D":"Enterobius vermiculares e pamoato de pirvinio"},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-295420","number":"295420","sourceNumber":"295420","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A manifestação clínica e parasitose intestinal estão relacionadas em:","options":{"A":"Pancreatite aguda = ascaridíase.","B":"Prolapso retal = enterobíase.","C":"Síndrome de Loeffler (migração errática para a via respiratória) = tricuríase.","D":"Diarreia sanguinolenta = ancilostomíase."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-316382","number":"316382","sourceNumber":"316382","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A larva migrans cutânea, chamada popularmente por bicho geográfico, é uma infecção\nde distribuição mundial causada pelas larvas de\nparasitas que vivem no intestino de cães e gatos,\nconhecidas como:","options":{"A":"Enterobius vermicularis.","B":"Ancylostoma braziliense ou Ancylostoma caninum.","C":"Entamoeba histolytica.","D":"Toxocara canis ou Toxocara cati."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-294335","number":"294335","sourceNumber":"294335","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual é o tratamento de primeira linha para teníase?","options":{"A":"Mebendazol.","B":"Albendazol.","C":"Praziquantel.","D":"Ivermectina."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-257715","number":"257715","sourceNumber":"257715","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente de 30 anos, do sexo masculino, portador de\nretocolite ulcerativa, forma pancolônica em uso de mesalazina 4,8 g ao dia, que necessitou de\ncorticoterapia por três vezes no último ano. Nesse caso, a melhor indicação de tratamento é:","options":{"A":"Manutenção do corticoide por tempo prolongado para evitar recaídas.","B":"Aumento das doses de mesalazina acima de 5 gramas ao dia.","C":"Introdução de azatioprina ou 6 mercapto purina.","D":"Introdução de ciclosporina pela comodidade terapêutica."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-257716","number":"257716","sourceNumber":"257716","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente portador de doença de Crohn, em uso de\nbudesonida e mesalazina há cerca de oito\nanos, apresentando quadros de dor e distensão\nabdominal recorrente, náuseas, vômitos, hipoproteinemia, anemia e perda de peso. Realizado\nexame de enterorressonância magnética, que identificou tratar-se de forma estenosante jejunoileal\ncom fibrose e dilatação a montante. Nesse caso, qual é a melhor opção terapêutica?","options":{"A":"Tratamento cirúrgico, uma vez que se trata de um paciente que perdeu a janela de oportunidade\npara terapia medicamentosa.","B":"Introdução urgente de imunossupressão com azatioprina devido à sua rápida ação terapêutica.","C":"Introdução de terapia biológica com anti-TNF e imunossupressor em combo terapia, uma vez\nque se trata de paciente virgem para terapia\nbiológica.","D":"Terapia com corticoide, imunobiológicos e desconsiderar tratamento cirúrgico, pois deve-se\noperar pacientes com doença de Crohn apenas se\neles estiverem com obstrução ou perfuração\nintestinal."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-258166","number":"258166","sourceNumber":"258166","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um paciente do sexo masculino de 25 anos, com diagnóstico de retocolite ulcerativa e\nachado colonoscópico de comprometimento retal e\npancolônico com enantema, apagamento do\nquadro vascular e leve friabilidade da mucosa ao contato com o aparelho. Nesse caso, o\ndiagnóstico e o laudo são, respectivamente:","options":{"A":"retocolite ulcerativa Mayo 3, devido à grande extensão da doença.","B":"retocolite ulcerativa Mayo 2, devido à grande extensão da doença, mas com mucosa pouco\ninflamada.","C":"retocolite ulcerativa Mayo 1, devido ao aspecto da mucosa descrita, mas sem relação com a\nextensão.","D":"colite indeterminada ou Mayo 0, pois a forma pancolônica não é própria da retocolite ulcerativa."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-277425","number":"277425","sourceNumber":"277425","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Após a realização de uma colonoscopia, o médico assistente informa ao paciente que o\ndiagnóstico de Doença de Crohn é muito provável por ter identificado ao exame a lesão mais\nprecoce ligada a essa patologia. Essas lesões são:","options":{"A":"úlceras aftosas","B":"estenoses segmentares","C":"fístulas digestivas","D":"abscessos de cripta"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-277426","number":"277426","sourceNumber":"277426","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A doença inflamatória intestinal pode evoluir gravemente, sendo fator de risco para o\ndesenvolvimento de carcinoma colorretal. Com relação aos carcinomas que surgem no contexto da\nColite Ulcerativa, é correto que:","options":{"A":"são tumores bem diferenciados e pouco agressivos","B":"os pacientes com doença restrita ao lado esquerdo do cólon têm menor risco de desenvolver\ncâncer do que aqueles com doença pancolônica","C":"o risco de câncer não aumenta com o tempo de duração da doença","D":"o risco de desenvolvimento de câncer é menor do que na doença de Crohn"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-281286","number":"281286","sourceNumber":"281286","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre os tumores carcinoides do estômago, assinale a correta.","options":{"A":"O tipo I de Rindi é o menos comum e está associado à hipergastrinemia sérica sem gastrite\natrófica com hiperacidez.","B":"O tipo I de Rindi é o mais comum e está associado à hipergastrinemia sérica sem gastrite\natrófica com hiperacidez.","C":"O tipo II de Rindi geralmente é associado à neoplasia endócrina múltipla tipo 1 (NEM1) ou a\nSíndrome de Zollinger-Ellison.","D":"O tipo III de Rindi é frequentemente localizado no antro gástrico e está muito relacionado à\nhipergastrinemia sérica."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-274485","number":"274485","sourceNumber":"274485","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a colite pseudomembranosa como causadora da diarreia assinale a\nINCORRETA:","options":{"A":"Principal agente é o Clostridium difficile e está relacionada ao uso de cefalosporinas,\namoxicilina,\nampicilina.","B":"Diagnóstico pode ser firmado pela pesquisa de toxina A e B nas fezes ou pela realização de\ncolonoscopia.","C":"Tratamento inclui a suspensão imediata do antibiótico relacionado à infecção pelo Clostridium,\nuso de metronidazol oral ou vancomicina.","D":"Na forma grave, mesmo antes de colite fulminante deve-se propor ao invés de vancomicina\nendovenosa a laparotomia para colectomia subtotal."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-274493","number":"274493","sourceNumber":"274493","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Referente aos gastrinomas marque a CORRETA:","options":{"A":"O diagnóstico de gastrinoma pode ser suspeitado ao considerar a apresentação clínica de\núlceras pépticas frequentes ou múltiplas com\nbaixa resposta à terapia habitual e dosagens\nelevadas de gastrina e a, partir dessa suspeita, não há a necessidade de realização confirmação\nimaginológica.","B":"A topografia dos gastrinomas é preferencialmente pancreática ou duodenal em 80 a 90% dos\ncasos e não estão relacionados a\nmalignidade.","C":"O uso do octreotide de longa duração não tem indicação, afinal o controle se dá com inibidores\nde bomba de prótons, mesmo nos pacientes em que\na ressecção cirúrgica seja inviável.","D":"Há a relação com neoplasia endócrina múltipla tipo I."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-265908","number":"265908","sourceNumber":"265908","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A manifestação hepática MAIS comum associada a Retocolite Ulcerativa é:","options":{"A":"hepatite transinfecciosa.","B":"colangite esclerosante primária.","C":"colelitíase.","D":"divertículos de colédoco."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-246521","number":"246521","sourceNumber":"246521","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a estrongiloidíase, assinale a alternativa incorreta.","options":{"A":"A estrongiloidíase é uma helmintose causada por dois geohelmintos, pertencentes à família\nRhabdisidae, sendo seus representantes o Strongyloides Stercoralis e o Strongyloides fullebormi.","B":"A transmissão pode ser fecal-oral ou por meio da penetração pela pele de larvas presentes no\nsolo.","C":"Entre as medicações utilizadas na profilaxia de estrongiloidíase em indivíduos que serão\nsubmetidos à imunossupressão, podem ser utilizados albendazol ou ivermectina.","D":"Entre os métodos de detecção de larvas, o método de Kato-Katz é o padrão-ouro para detecção\nda estrongiloidíase.","E":"Nos quadros de estrongiloidíase disseminada, as larvas podem ser identificadas em qualquer\nfluído orgânico, como lavado bronco-alveolar,\nlíquido cefalorraquidiano, entre outros."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249461","number":"249461","sourceNumber":"249461","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença inflamatória intestinal, podemos apenas aceitar\ncomo adequado o item:","options":{"A":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela tipicamente lesões ulceradas, entremeadas de\náreas com mucosa normal, acometimento focal, assimétrico e descontínuo.","B":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\npior método para o diagnóstico e revela tipicamente lesões ulceradas.","C":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela tipicamente lesões ulceradas, não entremeadas de\náreas com mucosa normal, acometimento generalizado, simétrico e descontínuo.","D":"A endoscopia digestiva baixa (colonoscopia) com biópsias de sítios distintos, incluindo o íleo,\né o\nmétodo preferencial para o diagnóstico e revela raramente lesões ulceradas, e nunca entremeadas\nde áreas com mucosa normal, acometimento focal, assimétrico e contínuo."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249463","number":"249463","sourceNumber":"249463","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn (DC) é uma doença inflamatória intestinal, que apresenta exame\nhistopatológico pode indicar o seguinte item:","options":{"A":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão não segmentar\ne presença de granulomas não caseosos.","B":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão segmentar e\npresença de granulomas não caseosos.","C":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão segmentar e\npresença de granulomas caseosos.","D":"Acometimento transmural (quando da análise de ressecções cirúrgicas), padrão generalizado e\nausência de granulomas não caseosos."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-241691","number":"241691","sourceNumber":"241691","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 38 anos procura atendimento ambulatorial com episódios repetidos de\ndiarreia, sangramento retal e eliminação de muco nas fezes, último há um mês. Nesse caso, a\nmelhor estratégia para diminuir a recorrência é o uso de:","options":{"A":"colestiramina.","B":"norfloxacino.","C":"racecadotrila.","D":"sulfassalazina.","E":"sulfametoxazol + trimetoprim."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249466","number":"249466","sourceNumber":"249466","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na Doença de Crohn (DC) nos casos em que não há resposta inicial com o uso em\ndoses adequadas de azatioprina, recomenda-se a\nassociação de azatioprina mais alopurinol.\n\nAssim, está correto que:","options":{"A":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) semanal.","B":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) mensal.","C":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente tenha\nhistória de efeito adverso ou\nhipersensibilidade à azatioprina, pode-se usar metotrexato por via EV\nquinzenal.","D":"Alternativamente, caso o médico assistente prefira ou o paciente cortiço dependente não tenha\nhistória de efeito adverso ou hipersensibilidade à azatioprina, pode-se usar metotrexato por via\nintramuscular (IM) semanal."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-246528","number":"246528","sourceNumber":"246528","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A respeito da manifestação sobre as diarreias, podemos afirmar que se classifica como\ndiarreia secretora:","options":{"A":"colite actínica.","B":"colite pseudomembranosa.","C":"deficiência de lactase.","D":"doença de Crohn.","E":"Ingesta crônica de álcool."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249473","number":"249473","sourceNumber":"249473","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na Doença de Crohn (DC) a atividade aumentada da enzima tiopurinametiltransferase\nTPMT leva a baixa formação de 6-tioguanina e a\naumento dos níveis de 6-metilmercaptopurina,\ncom consequentes redução da eficácia e maior risco de hepatotoxicidade da azatioprina. Podemos\nconcordar com o item:","options":{"A":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativo aumento da atividade da doença,\npossibilitando a redução da dose de corticosteroide, sem aumento de toxicidade hepática.","B":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativa diminuição da atividade da\ndoença, possibilitando a redução da dose de corticosteroide, sem aumento de toxicidade hepática.","C":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina,\nlevou a significativa diminuição da atividade da\ndoença, possibilitando a aumento da dose de corticosteroide, sem aumento de toxicidade hepática.","D":"Adição de alopurinol, um inibidor daxantinaoxidase capaz de desviar o metabolismo da\nazatioprina para a produção de 6- tioguanina, levou a significativa diminuição da atividade da\ndoença, possibilitando a redução da dose de corticosteroide, mas também com aumento de\ntoxicidade hepática."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-232220","number":"232220","sourceNumber":"232220","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente de 30 anos, do sexo masculino, portador de\nretocolite ulcerativa, em tratamento com\nmesalazina oral na dose de 4,8 g/dia, mantendo crises de\ndiarreia sanguinolenta e cólicas abdominais, níveis de PCR elevados e colonoscopia evidenciando\nretocolite Mayo 2. Nos últimos meses, fez uso de prednisona por curtos períodos, trazendo\nbenefícios satisfatórios. Neste caso, seria adequado","options":{"A":"manter corticoterapia como droga de manutenção e suspender a mesalazina.","B":"aumentar a dose da mesalazina, já que está usando baixas doses.","C":"iniciar tiopurinas.","D":"associar corticoides, via retal e oral como resgate."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-234321","number":"234321","sourceNumber":"234321","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O maior risco de câncer colorretal nos portadores de retocolite ulcerativa está\nassociado a fatores como o início da doença em idade muito jovem e a paciente:","options":{"A":"Com doença restrita ao reto.","B":"Com colangite esclerosante.","C":"Com eritema nodoso.","D":"Em tratamento com 5-ASA."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-241702","number":"241702","sourceNumber":"241702","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 68 anos, portador de doença de Parkinson, encontra-se internado para\ntratamento de pneumonia aspirativa há 12\ndias, em uso de ceftriaxona e clindamicina. Em 48 horas\nevolui com febre, diarreia e dor abdominal. Ao exame REG, desidratado+/4; FC: 110 bpm, PA: 90 x\n54 mmHg. Abdome: dor à palpação profunda difusamente, sem sinais de irritação peritoneal.\n\nExames laboratoriais: Hb: 12,3 g/dL; Ht: 35%; GB: 16.200/mm³ (bastonetes 10%, neutrófilos\nsegmentados 62%; linfócitos 28%); plaquetas: 160.000/mm³; creatinina: 1,5 mg/dL; proteína C\nreativa: 20 mg/dL. Considerando-se a hipótese mais provável, a propedêutica indicada é:","options":{"A":"exame parasitológico de fezes.","B":"ultrassonografia total de abdome.","C":"pesquisa de toxinas A e B nas fezes.","D":"tomografia de abdome com contraste.","E":"colonoscopia."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249475","number":"249475","sourceNumber":"249475","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na Doença de Crohn (DC) com atividade inflamatória intestinal grave a fulminante os\npacientes serão tratados preferencialmente em hospitais terciários. Está inadequado apenas que:","options":{"A":"Devem receber hidratação, transfusões e suporte nutricional se clinicamente indicados.","B":"A avaliação cirúrgica será solicitada se houver suspeita de obstrução.","C":"Inicia-se o tratamento com hidrocortisona, IV, na dose de 100 mg, de 8/8h, se não houver\ncontraindicação.","D":"Caso ocorra a piora clínica e a retomada da via oral, pode-se substituir o corticosteroide IV por\n40 a 60 mg de prednisona, por Via Oral\n(VO), passando, então, os pacientes a serem tratados da\nmesma forma que os com doença moderada a grave."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-247414","number":"247414","sourceNumber":"247414","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 21 anos, sexo feminino, é atendida ambulatorialmente com queixa de\ndiarreia crônica persistente há 30 dias. É portadora de doença celiaca em tratamento regular. A\nmelhor conduta para o controle da diarreia é:","options":{"A":"dieta restrita.","B":"mesalazina.","C":"colestiramina.","D":"probióticos."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-252752","number":"252752","sourceNumber":"252752","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente procura atendimento referindo diarreia com sangue há 2 dias. Ao exame\nfísico, encontra-se em mau estado geral,\ndesidratado e com hipotensão arterial. Durante a\ninternação, evoluiu com insuficiência renal, anemia hemolítica microangiopática e trombocitopenia.\nO agente etiológico mais comum desses casos é:","options":{"A":"Klebsiella pneumoniae.","B":"Campylobacter jejuni.","C":"Salmonella.","D":"Escherichia coli."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-254240","number":"254240","sourceNumber":"254240","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Relacione as colunas a seguir: 1. Áscaris; 2. Giárdia; 3. Tricocéfalos; 4. Ancylostoma;\n5.\nOxiúro; ( ) Prurido anal; ( ) Pneumonia eosinofílica; ( ) Sangue oculto nas fezes; ( ) Diarréia\ncrônica;\n( ) Prolapso retal.","options":{"A":"2, 1, 3, 4, 5.","B":"2, 4, 3, 5, 1.","C":"5, 4, 3, 2, 1.","D":"5, 1, 4, 2, 3."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-248930","number":"248930","sourceNumber":"248930","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O tumor carcinoide, da base do apêndice cecal, com 2,5cm deve ser tratado com:","options":{"A":"colectomia direita e reconstrução primária","B":"quimioterapia e radioterapia","C":"apendicectomia","D":"quimioterapia"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-231969","number":"231969","sourceNumber":"231969","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a infecção por rotavírus, assinale a alternativa correta:","options":{"A":"o soro de reidratação oral não é eficaz no combate à desidratação nas infecções por esse\nagente","B":"a vacina não deve ser aplicada fora dos prazos recomendados pelo risco aumentado de\ninvaginação intestinal","C":"a transmissão ocorre exclusivamente por via fecal-oral","D":"os casos mais graves ocorrem entre crianças maiores de 2 anos","E":"a dose da vacina deve ser repetida se a criança vomita ou regurgita"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-246563","number":"246563","sourceNumber":"246563","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a cisticercose, julgue os seguintes itens. I. Em seres humanos, pode ser causada\npelas tênias do porco, do boi ou \"do peixe\",\nembora a neurocisticercose, forma mais grave\nconhecida da doença, seja causada apenas pela \"tênia do porco\". II. De maneira geral, os cistos\nvivos da maioria das tênias não provocam resposta imunológica intensa, mas podem desencadear\nneurocisticercose quando a invasão do parasita no cérebro é maciça ou quando os vermes\nobstruem o fluxo liquórico. III. As convulsões são o achado inicial da neurocisticercose,\nrespondendo por mais de 70% dos casos. Desses, mais de 80% são crises generalizadas, embora\npossam se iniciar como convulsões simples ou parciais complexas. IV. Como a neurocisticercose\npode acometer diversas regiões do sistema nervoso central (SNC), seu diagnóstico diferencial\nreside, sobretudo, entre as doenças do SNC: meningites, encefalites, acidentes vasculares, dentre\noutras. Pode-se afirmar que:","options":{"A":"todos os itens estão certos.","B":"apenas os itens I, II e III estão certos.","C":"apenas os itens II, III e IV estão certos.","D":"apenas os itens II e IV estão certos.","E":"apenas o item IV está certo."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-241740","number":"241740","sourceNumber":"241740","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No que diz respeito à giardíase, assinale a alternativa incorreta.","options":{"A":"Em algumas regiões dos Estados Unidos, entre 20% e 30% dos portadores de Giardia lamblia\npodem ser assintomáticos e o estado de portador assintomático pode persistir por meses.","B":"Os cistos de Giardia são muito sensíveis a cloração e radiação ultravioleta, o que torna baixa a\ntransmissibilidade de giardíase em piscinas.","C":"Em regiões de aglomerações humanas e onde o padrão de higiene é baixo, a disseminação da\ngiardíase pessoa a pessoa pode ocorrer por transmissão fecal-oral.","D":"As infecções sintomáticas por Giardia lamblia são mais comuns em crianças que em adultos.","E":"Exceto em situações específicas, os excretores assintomáticos de G. lamblia não precisam\nreceber tratamento."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-249514","number":"249514","sourceNumber":"249514","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A parede posterior duodenal é o local responsável pela maioria dos casos de\nhemorragia digestiva alta. Assinale a artéria responsável pelo sangramento:","options":{"A":"Artéria gástrica esquerda.","B":"Artéria gastroduodenal.","C":"Artéria gastro-epiploica direita.","D":"Artéria mesentérica superior."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-229554","number":"229554","sourceNumber":"229554","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 70 anos, em internação prolongada por fratura exposta de fêmur,\napresentando quadro de disenteria, com presença\nde toxinas para Clostridium A e B em fezes\npresente. Está em tratamento com metronidazol via oral, sem melhora. A MELHOR opção\nterapêutica nesse caso é:","options":{"A":"dobrar dose de metronidazol, por mais 14 dias.","B":"mantem metronidazol em associação com ciprofloxacino.","C":"substituir metronidazol por vancomicina endovenosa.","D":"substituir metronidazol por vancomicina via oral."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-229560","number":"229560","sourceNumber":"229560","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 85 anos, diabético e hipertenso, em tratamento de pneumonia hospitalar, foi\ninternado há 7 dias devido a uma fratura de fêmur. O médico assistente iniciou o Piperacilina com\nTazobactan e após 2 dias o paciente apresentou diarreia aquosa em grande quantidade, dor\nabdominal e febre. Nos exames laboratoriais, apresentou leucocitose e protéina C reativa\nultrassensível elevada. Solicitado novos exames, apresentava lipase, amilase e lactato normais.\n\nQual é o diagnóstico MAIS provável e tratamento?","options":{"A":"Colite pseudomembranosa / suspender antibiótico e iniciar probiótico.","B":"Colecistite alitiásica / ampliação do esquema antibiótico.","C":"Diarreia osmótica dos antibióticos / suspender antibiótico.","D":"Colite pseudomembranosa / iniciar metronidazol oral."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-254282","number":"254282","sourceNumber":"254282","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente jovem, 25 anos, com quadro de diarréia com muco, pus e sangue há 3 meses,\ncom perda ponderal. Em investigação realizou\ncolonoscopia com biópsia.","options":{"A":"Para diagnóstico de doença de Crohn observa-se um acometimento transmural com maior\npossibilidade de fístulas intestinais.","B":"A colectomia cura a doença de Crohn.","C":"p- ANCA negativo e ASCA positivo ocorrem mais na retocolite ulcerativa.","D":"O megacólon tóxico é uma complicação mais comum da doença de Crohn."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-232294","number":"232294","sourceNumber":"232294","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No Brasil, as parasitoses intestinais ainda são um grave problema de saúde pública,\npois existem muitos tipos. Nas parasitoses\nintestinais:","options":{"A":"A penetração no hospedeiro do Ascaris lumbricoides ocorre através da pele.","B":"A forma infectante do Schistosoma mansoni é a cercária.","C":"A Taenia saginata se localiza nas veias do sistema porta do hospedeiro.","D":"A forma infectante do Ancylostoma duodenale é o ovo."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-232296","number":"232296","sourceNumber":"232296","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O pamoato de pirantel é uma droga utilizada no tratamento de nematoides, enquanto o\npamoato de pirvínio é específico para tratamento de:","options":{"A":"ascaridíase.","B":"ancilostomose.","C":"oxiuríase.","D":"pediculose."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216573","number":"216573","sourceNumber":"216573","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um dos efeitos da colecistoquinina no trato gastrointestinal é:","options":{"A":"Inibir a secreção de pepsina.","B":"Relaxar o esfíncter de Oddi.","C":"Acelerar o esvaziamento gástrico.","D":"Relaxar a vesícula biliar."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-210561","number":"210561","sourceNumber":"210561","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação à diarreia aguda associada ao uso de antimicrobiano em paciente\nadmitido em Unidade de Tratamento Intensivo, assinale a afirmativa correta.","options":{"A":"Agentes constipantes ou que diminuam a motilidade gastrintestinal podem ser utilizados.","B":"O exame endoscópico para pesquisa de colite pseudomembranosa tem alta sensibilidade.","C":"É contraindicada a suspensão dos antimicrobianos nestes casos.","D":"Nos casos moderados a graves, recomenda-se esquema com metronidazol.","E":"A colectomia não apresenta benefício, mesmo nos quadros refratários."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-202663","number":"202663","sourceNumber":"202663","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Na doença de Crohn,","options":{"A":"a corticoterapia deve ser mantida por tempo prolongado nos casos de falta de resposta com o\nácido 5 aminossalicílico.","B":"a mesalazina é a droga padrão-ouro para o tratamento da forma colônica.","C":"a corticoterapia deve ser evitada para indução do tratamento.","D":"Adalimumabe, Infliximabe e Certolizumabe são imunobiológicos anti-TNF (fator de necrose\ntumoral) indicados para o tratamento adequado."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-217019","number":"217019","sourceNumber":"217019","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual é o agente causador de diarreia aguda em imunocomprometidos, associada a dor\nabdominal, febre, dispneia e esplenomegalia?","options":{"A":"Entamoeba histolytica.","B":"Clostridium difficile.","C":"Campylobacter jejuni.","D":"Strongyloides stercoralis.","E":"Yersinia enterocolitica."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216439","number":"216439","sourceNumber":"216439","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O marcador sorológico que está presente em 60 a 70% dos pacientes com retocolite\nulcerativa e que pode ajudar no diagnóstico dessa doença é o(a):","options":{"A":"Anti-DNA de dupla-hélice.","B":"Fator reumatoide.","C":"Anticorpo antimúsculo liso.","D":"Anticorpo anticitoplasma de neutrófilo perinuclear (p-Anca)."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216998","number":"216998","sourceNumber":"216998","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A colite induzida por Clostridium difficile é uma inflamação do intestino grosso que\nresulta em diarreia. A inflamação é causada\npelo crescimento de bactérias incomuns. Quais são os\nantimicrobianos que podem ser utilizados para seu tratamento?","options":{"A":"Clindamicina e metronidazol.","B":"Ciprofloxacino e metronidazol.","C":"Vancomicina e ciprofloxacino.","D":"Metronidazol e vancomicina.","E":"Clindamicina e ciprofloxacino."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-202688","number":"202688","sourceNumber":"202688","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A doença inflamatória intestinal (DII) representa um grupo de afecções intestinais\ninflamatórias crônicas idiopáticas. Além das\nmanifestações intestinais, os pacientes podem\napresentar manifestações extraintestinais. Que manifestação extraintestinal tipicamente piora com\na exacerbação da atividade das DII?","options":{"A":"Artrite.","B":"Uveíte.","C":"Colangite esclerosante primária.","D":"Espondilite anquilosante."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216484","number":"216484","sourceNumber":"216484","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"G.H., 78 anos, internado em enfermaria de clínica médica há 22 dias para tratamento\nde pneumonia bacteriana, vem evoluindo há 3 dias\ncom diarreia aquosa, sem sangue, pus ou muco\ne sem febre. Já fez uso de ceftriaxone por 7 dias e no momento está em uso de cefepime. O\ndiagnóstico mais provável é:","options":{"A":"Doença de Crohn.","B":"Colite pseudomembranosa.","C":"Pancreatite crônica.","D":"Infecção por rotavírus."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216634","number":"216634","sourceNumber":"216634","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A doença de Crohn é uma forma de doença inflamatória intestinal e o diagnóstico\ndiferencial da mesma ocorre principalmente com a retocolite ulcerativa idiopática. São\ncaracterísticas desta última (retocolite) que ajudam a diferenciá-la da doença de Crohn:","options":{"A":"1. Acometimento de todo trato gastrointestinal (podendo acometer da boca ao ânus). 2. Áreas de\nmucosa preservada. 3. Acometimento transmural da\nparede intestinal.","B":"2. Anticorpo característico é o ASCA (Anti-Saccharomyces). 2. Acometimento exclusivo da\nmucosa intestinal. 3. Maior acometimento perianal.","C":"1. Acometimento intestinal contínuo e ascendente. 2. Lesão exclusiva da mucosa intestinal. 3.\n\nAnticorpo característico é o p-ANCA.","D":"1. Acometimento predominante do íleo terminal. 2. Anticorpo característico é o p-ANCA. 3.\n\nLesão exclusivamente de mucosa intestinal."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-218231","number":"218231","sourceNumber":"218231","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Síndrome de Löffler é uma pneumonia eosinofílica, caracterizada por infiltrados\npulmonares migratórios associados, geralmente, com um\naumento do número de eosinófilos no\nsangue e escarro. O quadro clínico típico é caracterizado por tosse seca, dispneia, sibilos,\ndesconforto retroesternal e febre baixa. Assinale a alternativa que apresenta apenas possíveis\ndoenças causadoras dessa síndrome:","options":{"A":"Ascaridíase e amebíase.","B":"Estrongiloidíase e giardíase.","C":"Ascaridíase e estrongiloidíase.","D":"Amebíase e giardíase."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216996","number":"216996","sourceNumber":"216996","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale, a seguir, a alternativa que apresenta característica(s) das helmintíases na\ninfância.","options":{"A":"Infestação com tendência à suboclusão ou à obstrução total na oxiuríase.","B":"Prurido anal na esquistossomose.","C":"Prolapso retal na ascaridíase.","D":"Convulsão em adolescentes decorrente de neurocisticercose nas teníases por Taenia solium.","E":"Síndrome de Loeffler na ascaridíase, na necatoríase, na esquistossomose, na estrongiloidíase e\nna ancilostomíase."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-210530","number":"210530","sourceNumber":"210530","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Não é característica das helmintíases na infância:","options":{"A":"Infestação com tendência à suboclusão ou obstrução total na ascaridíase.","B":"Prurido anal na oxiuríase.","C":"Prolapso retal na tricuríase.","D":"Convulsão em adolescentes decorrente de neurocisticercose nas teníases por Taenia solium.","E":"Síndrome de Loeffler na ascaridíase, necatoríase, esquistossomose, estrongiloidíase e\nancilostomíase."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-215000","number":"215000","sourceNumber":"215000","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Uma escolar de 5 anos, apresenta ardência ao urinar há 1 semana. A mãe relata\nsecreção amarelada com odor ruim nas suas roupas\nintimas, sem outros sintomas. Exame físico:\nhiperemia na região vulvar. Para se formular uma hipótese diagnóstica da etiologia específica\nnesse caso, deve-se inquirir sobre:","options":{"A":"práticas esportivas","B":"higiene perianal","C":"agitação noturna","D":"produtos químicos"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-215385","number":"215385","sourceNumber":"215385","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual das alternativas abaixo NÃO é uma contraindicação absoluta para o transplante\nde intestino delgado?","options":{"A":"Disfunção neurológica progressiva.","B":"Sepse ativa.","C":"Problemas psicossociais graves.","D":"Imunodeficiência."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-205643","number":"205643","sourceNumber":"205643","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a Doença de Crohn, assinale a alternativa INCORRETA:","options":{"A":"O risco de desenvolvimento de carcinoma do cólon é menor que na colite ulcerativa.","B":"As manifestações extracolônicas são semelhantes àquelas associadas a retocolite ulcerativa.","C":"Achados radiológicos característicos são lesões salteadas, defeitos de contorno, úlceras\nlongitudinais e transversas, estenoses e defeitos nodulares irregulares.","D":"A maioria das manifestações extracolônicas melhora com a ressecção do intestino doente,\nincluindo a colangite esclerosante primária."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-202632","number":"202632","sourceNumber":"202632","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"É exemplo de doença inflamatória não formadora de granulomas:","options":{"A":"Tuberculose.","B":"Hanseníase.","C":"Doença de Crohn.","D":"Retocolite ulcerativa."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-187589","number":"187589","sourceNumber":"187589","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O parasita intestinal mais associada ao prolapso retal é:","options":{"A":"O Ascaris lumbricoides.","B":"A Giardia lamblia.","C":"A Entamoeba histolytica.","D":"O Trichuris trichiura."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-185163","number":"185163","sourceNumber":"185163","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O apêndice vermiforme tem sua vascularização através da artéria apendicular, que é\nramo direto da artéria","options":{"A":"ileocólica.","B":"pudenda interna direita.","C":"retal superior.","D":"retal inferior direita."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-187709","number":"187709","sourceNumber":"187709","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O Clostridium difficile (C. difficile) é responsável por 15 a 20% dos casos de diarréia\nsecundário ao uso de antibióticos e praticamente por 100% dos casos de colite\npseudomembranosa. Qual dos exames abaixo relacionados NÃO é utilizado para confirmar o\ndiagnóstico dessa infecção?","options":{"A":"Pesquisa do DNA do C. difficile por PCR nas fezes.","B":"Detecção de toxinas A e/ou B nas fezes pelo método ELISA.","C":"Retossigmoidoscopia.","D":"Pesquisa de leucócitos fecais."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-182464","number":"182464","sourceNumber":"182464","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale (V) para Verdadeiro e (F) para Falso com relação ao diagnóstico diferencial\nentre a retocolite ulcerativa inespecífica\n(RCUI) e a Doença de Crohn (DC): ( ) A RCUI sempre\nacomete o reto, mas não causa doença perianal.; ( ) A DC frequentemente acomete o reto e causa\ndoença perianal.; ( ) A DC raramente promove acometimento transmural.; ( ) A RCUI\nfrequentemente promove acometimento transmural.; ( ) Na RCUI não ocorrem úlceras aftosas na\nmucosa do trato digestivo. Assinale a sequência correta:","options":{"A":"V, F, V, F, V","B":"V, V, F, F, V","C":"F, V, F, V, V","D":"V, V, F, V, F"},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-178839","number":"178839","sourceNumber":"178839","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação à retocolite ulcerativa, assinale a alternativa incorreta.","options":{"A":"Abcessos de críptas são a alteração histológica mais característica.","B":"Diretamente não acomete intestino delgado.","C":"Diarreia sanguinolenta de longa duração é sintoma comum.","D":"Estenose no lúmen intestinal é comum, assim como na doença de Crohn.","E":"ASCA negativo e p-ANCA positivo."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-178774","number":"178774","sourceNumber":"178774","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a colite pseudomembranosa, assinale a alternativa correta.","options":{"A":"Closrtrídium perfringens é o agente etiológico mais comum.","B":"Toxina A e Toxina B no sangue é o exame padrão diagnóstico.","C":"Não está associada ao uso prévio de antibióticos na maioria das vezes.","D":"A associação entre ciprofloxacino e metronidazol é o tratamento de escolha.","E":"Colite fulminante com megacolon tóxico é a forma mais grave de apresentação."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-186423","number":"186423","sourceNumber":"186423","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação ao diagnóstico, tratamento e acompanhamento das doenças intestinais\ninflamatórias, marque a alternativa correta:","options":{"A":"A associação de mesalazina e prednisona representa uma ótima alternativa como terapia de\nmanutenção para evitar recidivas, após o tratamento cirúrgico.","B":"A dosagem de calprotectina fecal é útil durante o segmento pós-operatório.","C":"A presença de microabscesso de cripta no anátomo-patológico favorece o diagnóstico de\ndoença de Crohn.","D":"As manifestações perianais da doença de Crohn precedem a doença íleo-colônica em mais de\n50% dos casos."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-178817","number":"178817","sourceNumber":"178817","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente, de 9 anos, apresenta um quadro de diarreia há 30 dias, com sangue nas\nfezes. Em consulta no pronto-socorro foi\nconstatado um quadro de prolapso retal e palidez\nmucocutânea. Tendo sido diagnosticado com uma parasitose intestinal, qual é o agente etiológico\nmais provável?","options":{"A":"Taenia saginata.","B":"Ascaris lumbricoides.","C":"Entamoeba coli.","D":"Enterobius vermicularis.","E":"Trichocephalus trichiurus."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-174098","number":"174098","sourceNumber":"174098","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em qual das condições a seguir é mais provável uma biópsia mostrar evidência\nhistológica de inflamação granulomatosa?","options":{"A":"Espru celíaco.","B":"Doença de Crohn.","C":"Colite ulcerativa.","D":"Gastrite autoimune."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-174151","number":"174151","sourceNumber":"174151","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"As parasitoses intestinais são muito comuns nos pacientes pediátricos e o praziquantel\né uma das drogas utilizadas no tratamento\ndessas doenças. Para qual doença o praziquantel é a\nprimeira escolha?","options":{"A":"Giardíase.","B":"Oxiuríase.","C":"Teníase.","D":"Ascaridíase."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183304","number":"183304","sourceNumber":"183304","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn é um processo inflamatório crônico de etiologia ainda\ndesconhecida, não curável por tratamento\nclínico ou cirúrgico e que acomete o trato gastrointestinal\nde forma uni ou multifocal, de intensidade variável e transmural. Sobre isso, assinale a alternativa\nINCORRETA:","options":{"A":"Os locais de acometimento mais frequentes são o intestino delgado e o grosso.","B":"Manifestações extraintestinais associadas ou isoladas podem ocorrer e atingem mais\nfrequentemente pele, articulações, olhos, fígado e trato urinário.","C":"Manifestações perianais podem ocorrer em menos de 50% dos pacientes.","D":"A doença afeta indivíduos de qualquer idade, mas o diagnóstico é realizado com maior\nfrequência na segunda ou terceira décadas."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-183340","number":"183340","sourceNumber":"183340","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A Doença de Crohn pode ser entendida como um processo inflamatório crônico de\netiologia ainda desconhecida, não curável por tratamento clínico, quanto a isso, analise as\nalternativas abaixo e assinale a CORRETA:","options":{"A":"As manifestações extraintestinais mais frequentes correlacionam-se de forma contrária com a\nintensidade do processo inflamatório intestinal e podem ser cutâneas (eritema nodoso e pioderma\ngangrenoso), articulares periféricas (artrites) ou axiais (espondilite anquilosante e sacroileíte),\noculares (conjuntivite e uveíte) e hepáticas (colangite esclerosante primária). Colecistolitíase e\nnefrolitíase podem resultar de má absorção.","B":"As manifestações extraintestinais mais frequentes correlacionam-se de forma direta com a\nintensidade do processo inflamatório intestinal e podem ser cutâneas (eritema nodoso e pioderma\ngangrenoso), articulares periféricas (artrites) ou axiais (espondilite anquilosante e sacroileíte),\noculares (conjuntivite e uveíte) e hepáticas (colangite esclerosante primária). Colecistolitíase e\nnefrolitíase podem resultar de má absorção.","C":"As manifestações extraintestinais mais raras correlacionam-se de forma indireta com a\nintensidade do processo inflamatório intestinal e não podem ser cutâneas.","D":"As manifestações extraintestinais mais frequentes correlacionam-se de forma direta com a\nintensidade do processo inflamatório intestinal e podem ser cutâneas (eritema nodoso e pioderma\ngangrenoso), mas não articulares periféricas."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-160470","number":"160470","sourceNumber":"160470","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 47 anos com diagnóstico de retocolite ulcerativa há 30 anos, faz uso regular\nde mesalazina 2,4 g/dia. Na colonoscopia de\nacompanhamento, o histopatológico da biópsia do\ncólon sigmóide revelou displasia de alto grau. Nesse caso, qual a conduta indicada?","options":{"A":"Iniciar imunomodulador e realizar nova colonoscopia em 6 meses.","B":"Realizar proctossigmoidectomia com anastomose cólon-anal.","C":"Realizar proctossigmoidectomia com colostomia terminal.","D":"Realizar proctocolectomia total com anastomose de bolsa íleo-anal e ileostomia."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-150706","number":"150706","sourceNumber":"150706","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A droga que tem efeito terapêutico precário quando associada ao adalimumabe em\npacientes acometidos pela doença de Crohn no intestino delgado é a:","options":{"A":"5-mercaptopurina.","B":"Azatioprina.","C":"Prednisolona.","D":"Mesalazina."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-157430","number":"157430","sourceNumber":"157430","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Assinale a alternativa INCORRETA quanto à colite pseudomembranosa.","options":{"A":"É uma doença inflamatória causada por toxinas produzidas pela proliferação sem oposição da\nbactéria C. difficile.","B":"Dos pacientes que contraem a colite por C. difficile, 90% tem recebido antibioticoterapia em\nmonoterapia e 70% foram tratados com múltiplos antibióticos.","C":"Entre os principais fatores de risco encontram-se idade avançada, imunossupressores, HIV e\nquimioterapia.","D":"A minoria dos pacientes responde ao tratamento clínico, e grande parte dos pacientes evolui\npara forma mais grave da doença, como colite fulminante."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-158481","number":"158481","sourceNumber":"158481","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O agente de saúde comunitária solicita ao médico do seu PSF que faça uma palestra\nsobre verminose numa escola da comunidade, pois\nestá havendo muitos casos de ancilostomíase.\nPara melhor adesão ao tratamento, pede que o foco seja nas complicações. Durante a palestra\ndeve-se ressaltar que uma complicação importante deste parasita é:","options":{"A":"Pancreatite aguda.","B":"Colecistite aguda.","C":"Abscesso hepático.","D":"Anemia e hipoproteinemia."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-160479","number":"160479","sourceNumber":"160479","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em um paciente sob investigação de doença inflamatória intestinal, o diagnóstico de\ndoença de Crohn é possível quando","options":{"A":"Demonstra-se etiologia infecciosa da doença.","B":"O trato gastrointestinal é acometido de modo contínuo.","C":"Há acometimento de qualquer parte do sistema digestivo.","D":"A biópsia revela acometimento apenas da camada mucosa."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-150212","number":"150212","sourceNumber":"150212","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 65 anos, do sexo feminino, apresenta queixas de diarreia várias vezes ao\ndia, em pequena quantidade, tenesmo, há cinco dias, e há um dia aparecimento de febre,\n\nmal-estar, náuseas e dor abdominal. Dados de história recente indicam tratamento para pneumonia\n(SIC). Esta paciente apresenta:","options":{"A":"Diarreia alta secretória, provavelmente bacteriana.","B":"Diarreia baixa, tipo osmótica e viral.","C":"Diarreia baixa inflamatória associada a antibióticos.","D":"Diarreia motora, provavelmente por síndrome do intestino irritável."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-156476","number":"156476","sourceNumber":"156476","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Entre as manifestações extraintestinais, qual está relacionada com o aumento de risco\nde carcinoma colorretal nos pacientes portadores de doença inflamatória intestinal?","options":{"A":"Espondiloartrite.","B":"Colangite esclerosante.","C":"Hepatite autoimune.","D":"Pioderma gangrenoso."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-127249","number":"127249","sourceNumber":"127249","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Janaina, 15 anos, com historia de diarreia persistente, perda de peso, eritema nodoso e\núlceras orais. Apresenta dor abdominal, descarga purulenta retal, sangramento retal maciço. A\nsigmoidoscopia revela ulceração e pseudopolipos. O diagnóstico é:","options":{"A":"Doença de Crohn.","B":"Polipose juvenil.","C":"Síndrome de Peutz-Jeghers.","D":"Retocolite ulcerativa."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-136563","number":"136563","sourceNumber":"136563","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A indicação cirúrgica mais comum nos casos de doença de Crohn decorre de","options":{"A":"Perfuração livre.","B":"Hemorragia maciça.","C":"Obstrução intestinal.","D":"Degeneração maligna."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-137023","number":"137023","sourceNumber":"137023","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente jovem, do sexo feminino, apresenta quadro de diarreia com fezes líquidas e às\nvezes tem sangue e muco. Concomitantemente,\napresenta dor abdominal e emagrecimento. Esse\nquadro vem ocorrendo nos últimos doze meses e muito a incomoda, pois interfere em suas\natividades profissionais e sociais. Ao exame físico, foi observado fístula perianal. Qual a\nprincipal\nhipótese diagnóstica e qual o exame de escolha para confirmação?","options":{"A":"Doença inflamatória intestinal, provavelmente retocolite ulcerativa; colonoscopia.","B":"Parasitose intestinal maciça, provavelmente ascaridíase; parasitológico de fezes seriado com\ntrês amostras.","C":"Neoplasia de intestino grosso em virtude das evacuações com sangue; colonoscopia.","D":"Doença inflamatória intestinal, provavelmente doença de Crohn; colonoscopia."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-127085","number":"127085","sourceNumber":"127085","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual paralisia intestinal, em caso de parasitismo intenso, cujos vermes se fixam na\nmucosa do colón até o reto, provocando lesões\ne ulcerações com enterorragia e prolapso retal,\nprincipalmente, em lactentes desnutridos:","options":{"A":"Ascaris lumbricoides.","B":"Hymenolepis nana.","C":"Necator americanus.","D":"Trichocephalus trichiurus."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-138257","number":"138257","sourceNumber":"138257","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em crianças com sintomas intestinais causados pela infestação com a Giardia\nintestinalis (Giardia lamblia),","options":{"A":"a diarreia crônica e a síndrome de má-absorção são formas raras de manifestação dessa\nparasitese intestinal.","B":"a diarreia protraída ou intermitente é rara.","C":"a anorexia combinada com a má-absorção intestinal leva a significante perda de peso, failure to\nthrive e anemia.","D":"a giardíase é de fácil tratamento na presença de imunodeficiência humoral e desnutrição\nproteico-calórica."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-129893","number":"129893","sourceNumber":"129893","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Um portador de doença celíaca pode ingerir a seguinte substância:","options":{"A":"arroz.","B":"malte.","C":"trigo.","D":"aveia."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-103672","number":"103672","sourceNumber":"103672","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a doença de Crohn, indique a alternativa CORRETA.","options":{"A":"Atinge, na maioria dos casos, o intestino grosso.","B":"Afeta órgãos do esôfago ao ânus.","C":"A diarreia é o sintoma mais comum.","D":"Complicações como câncer é mais frequente nesses pacientes."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-110274","number":"110274","sourceNumber":"110274","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Maria, mãe de Raimundo Nonato, com 7 anos de idade, procura o médico da UBS.\nSegundo Maria, Raimundo tem anemia que foi\ndiagnosticada com um ano de idade. Faz uso,\ndesde essa época, de sulfato ferroso, mas sem melhora do quadro. Informa ainda que o menor\nestá sempre se queixando de artralgia principalmente de membros inferiores, apresenta fezes\nsecas e pétreas, evacuando 2 vezes na semana, mesmo após uso de várias medicações prescritas\npelo pediatra. Outra queixa da mãe é que o filho está \"muito miudinho, parece que não tá\ncrescendo direito\". Nega internações anteriores e outras patologias. Qual o provável diagnóstico de\nRaimundo Nonato?","options":{"A":"Amebíase.","B":"Fibrose cística.","C":"Doença celíaca.","D":"Estrongiloidíase."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-110273","number":"110273","sourceNumber":"110273","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Maria, mãe de Raimundo Nonato, com 7 anos de idade, procura o médico da UBS.\nSegundo maria, Raimundo tem anemia que foi\ndiagnosticada com um ano de idade. Faz uso,\ndesde essa época, de sulfato ferroso, mas sem melhora do quadro. Informa ainda que o menor\nestá sempre se queixando de artralgia principalmente de membros inferiores, apresenta fezes\nsecas e pétreas, evacuando 2 vezes na semana, mesmo após uso de várias medicações prescritas\npelo pediatra. Outra queixa da mãe é que o filho está \"muito miudinho, parece que não tá\ncrescendo direito\". Nega internações anteriores e outras patologias. De acordo com o quadro de\nRaimundo, qual procedimento é imprescindível para comprovar o diagnóstico?","options":{"A":"Parasitológico de fezes.","B":"Endoscopia com biópsia.","C":"Marcadores sorológicos.","D":"Laparotomia exploratória."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-109176","number":"109176","sourceNumber":"109176","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Marcos tem 12 anos e será submetido a cirurgia plástica peniana pela quarta vez para\ncorreção epispádia. Nos exames pré-operatórios,\ndiagnostica-se estrongiloidíase e giardíase. Entre\nas opções abaixo, a droga mais indicada para tratar Marcos é:","options":{"A":"Albendazol.","B":"Tiabendazol.","C":"Mebendazol.","D":"Metronidazol."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-101163","number":"101163","sourceNumber":"101163","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A diarreia crônica por hipersecreção intestinal se caracteriza por:","options":{"A":"Persistir mesmo em jejum prolongado; apresentar ausência de gordura fecal e de leucócitos\nfecais.","B":"Diminuir com o jejum prolongado; apresentar aumento de gordura fecal e de leucócitos fecais.","C":"Persistir mesmo em jejum prolongado; apresentar aumento de gordura fecal e de leucócitos\nfecais.","D":"Diminuir com o jejum; apresentar ausência de gordura fecal e de leucócitos fecais."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111370","number":"111370","sourceNumber":"111370","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Percussão hepática digito-digital intensamente dolorosa, localizada e circunscrita é\ndenominada Sinal de...","options":{"A":"Adams;","B":"Blumberg;","C":"Lapinsky;","D":"Mathieu;","E":"Torres-Homem."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-111398","number":"111398","sourceNumber":"111398","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre as Doenças Inflamatórias Intestinais (DII), que assertiva é incorreta?","options":{"A":"A retocolite ulcerativa (RCU) é localizada no colon e no reto.","B":"A RCU cursa com dor abdominal e sangramento digestivo baixo.","C":"A Doença de Crohn (DC) pode ocorrer em qualquer localização dos intestines.","D":"A DC cursa com diarreia crônica, sem dor abdominal ou perda de peso.","E":"As DII podem cursar com sintomas fora trato gastrointestinal."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-109392","number":"109392","sourceNumber":"109392","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Qual é a parasitose intestinal, na infância, que pode cursar com a síndrome de Löffler?","options":{"A":"Giardíase.","B":"Oxiuríase.","C":"Ancilostomíase.","D":"Amebíase."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-89967","number":"89967","sourceNumber":"89967","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Sobre a amebíase, qual é a afirmativa incorreta:","options":{"A":"A infecção ocorre pela ingestão de água ou alimentos contaminados ou por transmissão\nfecal-oral direta.","B":"As formas císticas da E. histolytica são bastante sensíveis às condições ambientais.","C":"Homossexualidade masculina é um fator de risco.","D":"A 1ª opção de tratamento para formas intestinais é Secnidazol.","E":"Pode complicar com megacólon tóxico."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-86348","number":"86348","sourceNumber":"86348","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 30 anos de idade, do sexo feminino, procura atendimento médico referindo\nque há seis meses iniciou dor abdominal tipo\ncólica em hipogástrio, intermitente, associado à\nalternância do hábito intestinal entre obstipação e diarreia, com eliminação de muco nas fezes,\neructação e flatulência aumentados. Negou perda de peso, febre ou despertares noturnos. A\nprincipal hipótese diagnóstica e os exames que precisam ser solicitados para confirmação\ndiagnóstica são:","options":{"A":"retocolite ulcerativa, hemograma, VHS e colonoscopia.","B":"doença de Crohn, pesquisa de leucócitos nas fezes e colonoscopia.","C":"síndrome do intestino irritável, hemograma, retossigmoidoscopia e parasitológico de fezes.","D":"verminose, hemograma, pesquisa de leucócitos nas fezes e parasitológico de fezes."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-85364","number":"85364","sourceNumber":"85364","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Criança de dez anos, branca, procedente da Bahia. História de diarreia\nmucossanguinolenta há duas semanas, com\nvômitos biliosos e febre há seis dias. Há três dias com\ndesconforto gástrico e aumento do volume abdominal. Tem história pregressa de erupções\n\nmáculo-papulares pruriginosas em membros inferiores há cinco semanas. Ao exame físico,\napresenta-se pálida, desidratação leve,\nemagrecida, presença de micropoliadenomegalia\ngeneralizada. Pulmões com murmúrio vesicular presente, fisiológico. Abdome com acentuada\nhepatomegalia e moderada esplenomegalia. O hemograma mostrou leucocitose com acentuada\neosinofilia. Os dados descritos são sugestivos de qual patologia?","options":{"A":"Salmonelose.","B":"Leucemia.","C":"Calazar.","D":"Esquitossomose."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-78104","number":"78104","sourceNumber":"78104","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"O diagnóstico de inclusão à síndrome do intestino irritável, segundo o Consenso Roma\nIII, deve ser considerado nos casos em que o\npaciente apresentar:","options":{"A":"Dor abdominal recorrente que melhora com a evacuação, associada à alteração na frequência\ndas evacuações ou do formato das fezes.","B":"Dor abdominal recorrente que piora após a evacuação, associada à flatulência e ao tenesmo.","C":"Diarreia aquosa sem a presença de dor abdominal.","D":"Dor abdominal recorrente que melhora com a evacuação, associada à presença de muco e\nsangue nas fezes."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-83823","number":"83823","sourceNumber":"83823","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Não é manifestação extra-intestinal da Retocolite Ulcerativa:","options":{"A":"Artrite","B":"Espondilite anquilosante","C":"Nefrolitíase","D":"Pioderma gangrenoso","E":"Uveíte"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-83855","number":"83855","sourceNumber":"83855","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A principal queixa clínica de uma criança com infecção por Enterobius vermicularis é?","options":{"A":"diarreia","B":"dor abdominal","C":"esteatorreia","D":"prurido anal","E":"vômitos"},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-89965","number":"89965","sourceNumber":"89965","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Criança de 8 anos chega ao pronto-socorro com diarreia aquosa. Assumindo-se que\nesta diarreia seja secundária à parasitose intestinal, qual é, dentre as abaixo, a parasitose mais\nprovável?","options":{"A":"Amebíase.","B":"Estrongiloidíase.","C":"Giardíase.","D":"Isosporíase.","E":"Triquiuríase."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-84427","number":"84427","sourceNumber":"84427","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A colite pseudomembranosa representa uma importante causa de diarreia aguda em\npacientes hospitalizados. Na abordagem clínica desta patologia, considera-se que:","options":{"A":"Na maioria dos casos, ocorre devido ao uso de antibióticos, sobretudo vancomicina e\ncefalosporinas.","B":"Pode ocorrer até 4 semanas após o término do antibiótico e o diagnóstico definitivo é realizado\npela pesquisa das toxinas do Clostridium\ndifficile nas fezes.","C":"A colonoscopia evidencia mucosa edemaciada e hiperemiada, com placas acastanhadas\naderidas de forma contínua, podendo acometer\nqualquer parte do cólon.","D":"O surgimento da diarreia após 2 semanas do término do antibiótico sugere outra etiologia, como\nparasitoses intestinais.","E":"Medicamentos antissecretores podem ser úteis para alívio sintomático nos casos de diarreia\naquosa, mas com cautela devido ao risco de megacólon tóxico."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-69202","number":"69202","sourceNumber":"69202","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Quais são as características clínicas associadas às doenças inflamatórias intestinais?","options":{"A":"Artrite periférica, escleromalácia e miocardite.","B":"Sacroileíte, pioderma gangrenoso e eritema malar.","C":"Úlceras orais, pneumonite e glomerulonefrite.","D":"Eritema nodoso, uveíte e periostite.","E":"Conjuntivite, Raynaud e síndrome nefrótica."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-63414","number":"63414","sourceNumber":"63414","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Referindo-se a Doenças inflamatórias intestinais, marque a alternativa correta:","options":{"A":"A colite por Clostridium difficile está muito associada ao uso de antibióticos, mas pode se\ndesenvolver em pacientes que não usaram esse medicamento. O sangramento via retal não é\ncomum.","B":"O granuloma epitelioide composto de células gigantes de Langhans é encontrado em 20 a 60%\ndos exames microscópicos da Retocolite\nUlcerativa.","C":"A depleção de mucina das células de Goblet é comum ser encontrada na microscopia da\nDoença de Crohn.","D":"P-Anca é um autoanticorpo encontrado em cerca de de 50-70% dos pacientes com Doença de\nCrohn.","E":"O Asca (anticorpo anti-Saccharomyces cerevisae) é muito mais específico para Retocolite\nUlcerativa."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-69209","number":"69209","sourceNumber":"69209","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Quais dos sintomas abaixo estão relacionados com doença de Crohn na forma\nfibroestenosante?","options":{"A":"Suboclusão ou oclusão intestinal.","B":"Perda de peso, febre e diarreia.","C":"Diarreia com muco, pus e sangue.","D":"Fístulas e abscessos perianais.","E":"Dilatação aguda do cólon."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-61763","number":"61763","sourceNumber":"61763","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No megacólon tóxico, qual o segmento colônico mais comumente distendido?","options":{"A":"Reto.","B":"Sigmoide.","C":"Descendente.","D":"Transverso.","E":"Íleo terminal e reto."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-64609","number":"64609","sourceNumber":"64609","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Janaína, pré-escolar de três anos, é atendida com história de pneumonia diagnosticada\nhá um mês sem melhora radiológica, apesar do\nuso de amoxicilina por 10 dias, cefalosporina por\nsete dias e macrolídeo por 10 dias. À primeira radiografia, infiltrado pulmonar de opacidade\nhomogênea, em lobo superior direito; segunda com intervalo de sete dias, infiltrado pulmonar com\ndensidade heterogênea e fugaz em língula e terceira, com intervalo de 10 dias, infiltrado pulmonar\nde opacidade homogênea em lobo superior esquerdo. Hemograma com leucocitose discreta e\neosinofilia de 18%. Qual é a hipótese diagnóstica?","options":{"A":"Pneumonia atípica.","B":"Bronquiolite.","C":"Síndrome de Löeffler.","D":"Pneumonia comunitária.","E":"Aspiração de corpo estranho."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-62695","number":"62695","sourceNumber":"62695","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Os objetivos no tratamento da doença de Crohn incluem cicatrização das lesões,\nindução da remissão e sua manutenção. A sequência que melhor caracteriza a abordagem\nterapêutica progressiva ou step-up na doença de Crohn é:","options":{"A":"Prednisona, azatioprina, adalimumabe, mesalazina e cirurgia.","B":"5-ASA, corticoides, imunossupressores, anti-TNFa e cirurgia.","C":"Colonoscopia, biópsia, mesalazina, azatioprina e cirurgia.","D":"Cirurgia, infliximabe, azatioprina, corticoides e 5-ASA."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-63221","number":"63221","sourceNumber":"63221","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação às parasitoses intestinais, assinale a resposta certa.","options":{"A":"A larva migrans cutânea é diagnosticada através do exame microscópico de amostras fecais.","B":"Ao contrário do que se pensa, a infecção por ancilostomídeos não está associada ao\nsubdesenvolvimento econômico.","C":"As larvas da ascaridíase podem ser observadas no escarro e a maioria dos pacientes apresenta\ncargas parasitárias leves a moderadas, sem\nqualquer sinal ou sintoma.","D":"Na enterobiose, infecção por oxiúrus, frequentemente se observa eosinofilia, já que o prurido e a\nreação alérgica ao parasita são frequentes.","E":"A tricuríase é comum em comunidades rurais, sendo raras a anemia e o prolapso retal."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-63263","number":"63263","sourceNumber":"63263","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Felipe, 4 anos, apresenta quadros repetidos de sibilância e tosse que não melhoram\ncom inalações com beta2-agonista, necessitando\natendimento hospitalar quinzenal e uso de\ncorticoide oral por 5-7 dias. Falta frequentemente ao CMEI em consequência das crises. Mora em\nsítio, tem dificuldades financeiras e seus 2 irmãos e o pai também têm manifestações de alergia\nrespiratória. Exame físico: FC = 108 bpm; FR = 16 irpm; Tórax: sem alterações. Abdome: figado a 2\ncm do rebordo costal direito. Exames laboratoriais: dosagem de imunoglobulina E sérica total =\n3500 UI/ml e leucograma = 13.700/mm³ (28,7% de eosinófilos). Após o uso de antiparasitário, o\nexame complementar e o tratamento são:","options":{"A":"Sorologia para toxocaríase; beta2-agonista inalatório de curta duração.","B":"Dosagem das imunoglobulinas especificas; beta2-agonista inalatório de longa duração.","C":"Dosagem de imunoglobulinas específicas; corticoide e beta2-agonista de curta duração\ninalatórios.","D":"Sorologia para toxocaríase; corticoide inalatório.","E":"NDA."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-48322","number":"48322","sourceNumber":"48322","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Para o diagnóstico diferencial das síndromes disabsortivas, podemos destacar como\nteste mais importante:","options":{"A":"Dosagem da gordura fecal","B":"Dosagem da carotenemia","C":"Teste da metirapona","D":"Teste da lactulose","E":"Teste da D-xilose"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-48161","number":"48161","sourceNumber":"48161","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Indivíduo do sexo masculino, com 14 anos de idade, natural do interior de Alagoas,\nnesta cidade há 3 anos, morador de loteamento sem\nsaneamento básico, vem ao serviço médico\ncom queixa de febre há 1 mês; além disso relata só cansaço mais fácil que o habitual. Ao exame\nfísico apresenta hepatoesplenomegalia moderada e dolorosa. O exame parasitológico de fezes\nrevela ovos viáveis de Schistosoma mansoni. Pode-se afirmar que:","options":{"A":"Trata-se de um caso de esquistossomose na fase aguda, que deve ser tratado com oxaminique.","B":"O achado isolado de ovos viáveis de S. mansoni no exame parasitológico de fezes não basta\npara se firmar o diagnóstico de\nesquistossomose.","C":"A presença de febre neste indivíduo com esquistossomose hepatoesplênica na fase crônica\nsugere associação com outra patologia, como, por\nexemplo, bacteremia prolongada por Salmonella\nsp.","D":"O achado de ovos viáveis de S. mansoni no exame parasitológico de fezes deste indivíduo, que\nestá fora da região endêmica há 3 anos, sugere reativação da esquistossomose, que pode ocorrer\nna vigência de imunodepressão adquirida.","E":"A presença de febre neste indivíduo com esquistossomose hepatoesplêndica crônica, indica\ndescompensação, caracterizando a forma hepatoesplênica crônica descompensada da\nesquistossomose."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-48854","number":"48854","sourceNumber":"48854","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Loperamida está contraindicada em qual dos patógenos abaixo? Assinale a alternativa\ncorreta.","options":{"A":"Criptosporídia.","B":"E.coli enterotoxigênica.","C":"Microsporídia.","D":"Citomegalovírus.","E":"Clostridium diffícile."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-35619","number":"35619","sourceNumber":"35619","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Homem de 21 anos é internado com queixa de fraqueza nos últimos 6 meses.\nFamiliares relatam que nesse período adquiriu o\nhábito de comer gelo todos os dias. O único\nachado de exame físico é o descoramento de mucosas. O hemograma mostra hemoglobina de 7,9\ng/dl, 8.500 leucócitos/mm³ sendo 40% neutrófilos, 40% linfócitos e 20% eosinófilos. Dentre os\nabaixo, o volume corpuscular médio (em fl) mais provável e o tratamento mais adequado são,\nrespectivamente:","options":{"A":"115, transfusão de concentrado de hemácias e folato.","B":"75, transfusão de concentrado de hemácias e ferro.","C":"75, albendazol e corticoide.","D":"75, albendazol e ferro.","E":"115, corticoide e vitamina B12."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-35674","number":"35674","sourceNumber":"35674","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A diarreia osmótica decorre da presença de solutos não absorvíveis na luz intestinal.\nSão causas deste tipo de diarreia:","options":{"A":"Infecção pela Escherichia coli e pela Shigella sp.","B":"Deficiência de lactase e ingestão excessiva de hidróxido de magnésio.","C":"Ingestão excessiva de hidróxido de magnésio e toxina da Escherichia coli.","D":"Deficiência de lactase e infecção pela Escherichia coli.","E":"Ingestão excessiva de hidróxido de magnésio e infecção pela Shigella sp."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-35657","number":"35657","sourceNumber":"35657","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Adolescente do sexo masculino, com 14 anos de idade, natural do interior de Alagoas,\nnesta cidade há 3 anos, morador de loteamento\nsem saneamento básico, vem ao serviço médico\ncom queixa de febre há 1 mês; além disso relata só cansaço mais fácil que o habitual. Ao exame\nfísico apresenta hepatoesplenomegalia moderada e dolorosa. O exame parasitológico de fezes\nrevela ovos viáveis de Schistosoma mansoni. Pode-se afirmar que:","options":{"A":"Trata-se de um caso de esquistossomose na fase aguda, que deve ser tratado com\noxaminiquine.","B":"O achado isolado de ovos viáveis de S. mansoni no exame parasitológico de fezes não basta\npara se firmar o diagnóstico de\nesquistossomose.","C":"A presença de febre neste indivíduo com esquistossomose hepatoesplênica na fase crônica\nsugere associação com outra patologia, como, por\nexemplo, bacteremia prolongada por Salmonella\nsp.","D":"O achado de ovos viáveis de S. mansoni no exame parasitológico de fezes deste indivíduo que\nestá fora da região endêmica há 3 anos, sugere reativação da esquistossomose, que pode ocorrer\nna vigência de imunodepressão adquirida.","E":"A presença de febre neste indivíduo com esquistossomose hepatoesplênica crônica, indica\ndescompensação, caracterizando a forma hepatoesplênica crônica descompensada da\nesquistossomose."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-34078","number":"34078","sourceNumber":"34078","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"A doença celíaca é uma intolerância imunologicamente mediada a grãos que contêm\nglúten. Nessa doença:","options":{"A":"as manifestações clínicas costumam aparecer após os três anos de idade.","B":"a criança apresenta diarreia crônica, distensão abdominal, mas sem comprometimento do ganho\nde peso e do crescimento.","C":"a presença de anticorpo da classe Ig A antiendomísio apresenta boa especificidade para o\ndiagnóstico.","D":"tratamento requer a exclusão da dieta de alimentos que contenham trigo, centeio, cevada e\nmilho."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-11048","number":"11048","sourceNumber":"11048","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Com relação à doença intestinal inflamatória, pode-se afirmar que:","options":{"A":"A doença de crohn é uma entidade infecciosa","B":"A doença de crohn raramente leva a fistulas","C":"A doença de crohn não acarreta perfurações intestinais","D":"A doença de crohn é tratada cirurgicamente com grande sucesso, principalmente de modo\neletivo","E":"A mesalazina é uma droga que leva a bons resultados terapêuticos nas formas de acometimento\ncolônico"},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-10689","number":"10689","sourceNumber":"10689","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente com retocolite ulcerativa inespecífica apresenta acontecimento colônico\nextenso e retal moderado. O tratamento\ncirúrgico é indicado. Dos procedimentos cirúrgicos abaixo,\nnão pode ser realizado:","options":{"A":"proctocolectomia total com ileostomia.","B":"colectomia total com ileorrectoanastomose.","C":"colectomia total com anastomose jejunoanal.","D":"proctocolectomia total com ileostomia continente (bolsa de kock).","E":"colectomia total, mucossectomia retal e anastomose do tipo bolsa ileal."},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-10602","number":"10602","sourceNumber":"10602","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Das parasitoses abaixo, a que acompanha a eosinofilia é:","options":{"A":"himenolepiase.","B":"enterobiase.","C":"giardíase.","D":"tricuriase.","E":"toxocariase."},"answer":"E","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-9005","number":"9005","sourceNumber":"9005","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"No diagnóstico diferencial entre a diarreia por rotavirus e por outras etiologias\ninfecciosas, é correto afirmar que:","options":{"A":"a faixa etária, a severidade dos sintomas e a evolução auto-limitada, confirmam a suspeita\ndiagnóstica","B":"a faixa etária, a presença de sangue nas fezes e a presença de convulsão febril, sugerem a\nhipótese diagnóstica de infecção por rotavirus","C":"a evolução e a intensidade dos sintomas (febre, vômitos e diarreia) e a faixa etária abaixo dos\nvinte e quatro meses confirmam o diagnóstico","D":"a investigação laboratorial específica não é útil em crianças com idade inferior a vinte e quatro\nmeses"},"answer":"C","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-302061","number":"302061","sourceNumber":"302061","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Pacientes adultos jovens que se apresentam com história clínica de diarreia crônica,\ndor abdominal, perda ponderal e sangramento retal\nhá mais de 30 dias, cujo exame físico\ndemonstra sinais de desnutrição, palidez cutâneo-mucosa, dor, massa abdominal palpável e com\nexame proctológico com uma ou mais fissuras anais e plicomas anais edemaciados, é sugestivo\nde:","options":{"A":"Enterocolite necrotizante.","B":"Doença de Crohn.","C":"Síndrome do intestino irritável.","D":"Retocolite ulcerativa inespecífica.","E":"Abscesso anal com síndrome de Fournier."},"answer":"B","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-250266","number":"250266","sourceNumber":"250266","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Escolar de oito anos é levado à unidade básica de saúde apresentando há uma\nsemana prurido anal diário, na madrugada, que o\nfaz perder o sono. Seu irmão mais novo teve o\nmesmo sintoma. Exame físico sem alterações. Qual o diagnóstico mais provável e o medicamento\nque pode ser utilizado no tratamento, respectivamente?","options":{"A":"Enterobiose e pamoato de pirvínio.","B":"Escabiose e ivermectina.","C":"Ancilostomíase e albendazol.","D":"Giardíase e secnidazol."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-250271","number":"250271","sourceNumber":"250271","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Parasitoses intestinais são doenças endêmicas e universais provocadas por\nprotozoários e helmintos, constituindo sérios\nproblemas de saúde pública. Assinale a alternativa\nCORRETA:","options":{"A":"A amebíase, infecção causada pela Entamoeba coli, geralmente assintomática, podendo\napresentar quadros de colite, caracterizada por\nsurtos de diarreia leve, fezes líquidas, com ou sem\nmuco, dor abdominal e náuseas esporádicas, tem como tratamento de escolha o mebendazol, na\nmesma dose utilizada para ascaridíase.","B":"A estrongiloidíase, causada pelo Strongyloides stercoralis, que acomete principalmente o cólon,\ngeralmente é assintomática e sem repercussão e quando indicado o tratamento este deve ser\nrealizado exclusivamente com mebendazol.","C":"A ancilostomíase tem como droga de escolha para seu tratamento a ivermectina.","D":"A ascaridíase causada pelo Ascaris lumbricoides, que além da dor abdominal, distensão,\nanorexia e flatulência pode causar quadros\nde obstrução ou suboclusão intestinal, tem como\nopções de tratamento o mebendazol, albendazol, pamoato de pirantel e, nos processos obstrutivos,\na piperazina."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-250273","number":"250273","sourceNumber":"250273","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Correlacione as colunas dos parasitas e seu ciclo evolutivo correspondente: (1) A.\nlumbricoides. (2) S. stercoralis. (3) A. duodenal. (4) T. trichuria. ( )Eliminação de ovos nas fezes\ncom penetração ativa na pele do novo hospedeiro; ciclo pulmonar obrigatório; pode ocorrer\n\nauto-reinfestação endógena. ( ) Eliminação de ovos nos fezes com ingestão pelo novo hospedeiro;\nno intestino delgado , os ovos eclodem em\nlarvas que migram para o ceco e cólon ascendente,\ntransformando-se no verme adulto. ( ) Eliminação de ovos nas fezes, que se transormam em larvas,\ncom penetração ativa pela pele e ciclo pulmonar obrigatório. ( )Eliminação dos ovos nas fezes com\ningestão pelo novo hospedeiro, apresenta ciclo pulmonar obrigatório. Assinale a alternativa que\napresenta a sequencia CORRETA:","options":{"A":"3 ? 1 ? 2 ?4.","B":"1 ? 2 ? 4 ? 3.","C":"4 ? 3 ? 1 ? 2.","D":"2 ? 4 ? 3 ? 1."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216372","number":"216372","sourceNumber":"216372","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação aos tumores carcinoides, marque \"V\" para Verdadeiro e \"F\" para Falso. ( ) A\nlocalização mais comum dos tumores carcinoides é o trato respiratório seguido pelo trato digestório.\n( ) A síndrome carcinoide, presente na minoria dos pacientes portadores de tumores carcinoides,\npode incluir diarreia, brocoespasmo, miopatias, artropatia, lesões cutâneas urticariformes, fibrose\npulmonar ou cardíaca. ( ) O diagnóstico laboratorial dos tumores carcinoides é feito pela dosagem\nsérica da cromogranina A e do ácido 5-hidroxiindolacético na urina de 24 horas. ( ) O tratamento\ncirúrgico dos tumores carcinoides depende da sua localização anatômica e tamanho, sendo que,\npara as lesões do apêndice cecal com até 1 cm, sugere-se a apendicectomia e, para tumores\nmaiores que 3 cm, a hemicolectomia direita. Assinale a sequência CORRETA.","options":{"A":"V - V - F - V.","B":"V - F - V - V.","C":"F - F - V - V.","D":"F - V - V - V."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-216406","number":"216406","sourceNumber":"216406","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Paciente de 19 anos de idade estudante, trazido pela mãe ao ambulatório de clínica\nmédica com quadro de diarreia há 3 meses.\nTrata-se de 3 a 6 episódios diários de evacuações\nvolumosas, sem melhora com jejum, sem tenesmo, sem muco, pus ou sangue macroscopicamente.\nAcompanha o quadro uma perda de 8% de peso basal do paciente. A mãe traz uma série de\nexames realizados ao longo do período, incluindo 3 exames parasitológicos de fezes negativos, um\nteste Sudan III positivo para gordura fecal, 3 pesquisas negativas para sangue oculto fecal, e uma\nferrocinética com ferro sérico baixo, ferritina reduzida e saturação de tranferrina reduzida. A\ncausa\nMAIS PROVÁVEL, entre as apresentadas abaixo, para diarreia, é:","options":{"A":"Doença celíaca.","B":"Adenoma viloso de cólon.","C":"Intolerância à lactose.","D":"Tuberculose intestinal."},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-155431","number":"155431","sourceNumber":"155431","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação aos tumores carcinoides, marque \"V\" para verdadeiro e \"F\" para falso: ( ) A\nlocalização mais comum dos tumores carcinoides é o trato digestório seguido pelo sistema\nrespiratório; ( ) A síndrome carcinoide, presente na maioria dos pacientes portadores de tumores\ncarcinoides, pode incluir diarreia, brocoespasmo, miopatias, artropatia, lesões cutâneas\nurticariformes, fibrose pulmonar ou cardíaca; ( ) O diagnóstico laboratorial dos tumores carcinoides\né feito pela dosagem sérica da cromogranina A e do ácido 5-hidroxiindolacético na urina de 24\nhoras; ( ) Os tumores carcinoides localizados no intestino proximal apresentam uma tendência a\nproduzir níveis mais elevados de serotonina que os do intestino médio. Assinale a sequência\nCORRETA, de cima para baixo:","options":{"A":"V, F, V, F","B":"V, F, V, V","C":"V, V, F, V","D":"F, F, V, F","E":"F, V, F, V"},"answer":"A","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-02-155259","number":"155259","sourceNumber":"155259","collectionBlock":"med:med-clinica-medica-med-clm-02","collectionLabel":"MED · MED CLM 02","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 02","subtopic":"","stem":"Em relação à salmonelose septicêmica prolongada, assinale a alternativa INCORRETA:","options":{"A":"Faz parte do diagnóstico diferencial de febre de origem indeterminada.","B":"É uma entidade clínica tipicamente decorrente da infecção por salmonelas em indivíduos com\nesquistossomose.","C":"Além da Salmonella sp, eventualmente outras enterobactérias podem causar o mesmo quadro\nclínico.","D":"O quadro clínico tipicamente confunde-se muito mais com o quadro clássico de febre tifoide,\ninclusive com os sintomas neurológicos, do que com o quadro clássico calazar.","E":"Faz parte do diagnóstico diferencial de esplenomegalia de grande monta."},"answer":"D","source":"Clinica médica/MED CLM 02/MED CLM 02.txt","sourceLabel":"MED · MED CLM 02","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 02","MED"],"answerSource":"explicit","commentDeferred":true}]};
